INSERT INTO adventure_levels (id, title_fr, title_en, intro_fr, intro_en, phase, tools, payload_fr, payload_en) VALUES (0, 'Fondations — SQL & Python sur fichiers', 'Fondations — SQL & Python sur fichiers', 'Premier jour : tu manipules les sources en scripts, pas à la souris.', 'Premier jour : tu manipules les sources en scripts, pas à la souris.', 'ingestion', ARRAY['python', 'sql']::text[], '{"id":0,"title":"Fondations — SQL & Python sur fichiers","intro":"Premier jour : tu manipules les sources en scripts, pas à la souris.","brief":{"projectName":"Mutualis Retail — scripts de découverte","context":"Tu rejoins l’équipe data Mutualis. L’objectif du jeu : maîtriser SQL / Python / Spark (Databricks) et la stack GCP, plus delivery & gouvernance.","problem":"Sans scripts reproductibles ni orchestration, chaque analyste clique dans son fichier perso — zéro industrialisation.","objectives":["Lire un CSV en pandas et inspecter le schéma.","Filtrer les employés actifs en Python (SCD).","Écrire un premier SELECT SQL d’exploration."],"consigne":"Télécharge le fichier, écris le script notebook, puis réponds aussi à la question de gouvernance data. Une tâche à la fois."},"phase":"ingestion","tools":["python","sql"],"steps":[{"id":"l0-open","title":"Python — inspecter le schéma employés","say":"Télécharge retail_employees.csv. En pandas, charge le fichier et liste les colonnes.","do":"Colle un script Python qui lit le CSV et affiche les colonnes (df.columns / print).","how":["import pandas as pd","df = pd.read_csv(\"retail_employees.csv\")","print(list(df.columns)) ou print(df.dtypes)"],"trap":"Ne te contente pas de recopier l’en-tête à la main : le script doit lire le fichier (read_csv). Sinon tu n’as rien automatisé.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":28,"mustInclude":["read"],"keywords":["pandas","csv","columns","dtype","head","import"],"keywordMin":2},"feedbackPass":"Schéma lu par script — bon réflexe data eng.","feedbackFail":"Il me faut un read_csv (ou équivalent) + inspection des colonnes.","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"retail_employees.csv\")\nprint(list(df.columns))\nprint(df.dtypes)\n```\nColonnes typiques : employee_id, employee_name, department, region, active_record, …","tool":"python","phase":"ingestion"},{"id":"l0-filter","title":"Python — filtre active_record = 1","say":"Le métier ne veut que les fiches actives (SCD). Filtre en pandas et compte les lignes.","do":"Colle un script qui filtre active_record == 1 et affiche len / shape.","how":["df[df[\"active_record\"] == 1]","print(len(actifs)) — attendu autour de 500","Option : actifs[\"department\"].value_counts()"],"trap":"active_record = 0 = anciennes versions de fiche, pas « salarié parti ». Ne filtre pas sur department seul.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":35,"keywords":["active_record","active","pandas","loc","query","len","shape","=="],"keywordMin":2,"patterns":["active_record","\\b500\\b","len\\(|\\.shape"],"patternMin":1},"feedbackPass":"Filtre SCD scripté — prêt pour un job quotidien.","feedbackFail":"Montre le filtre active_record et un comptage (len / shape).","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"retail_employees.csv\")\nactifs = df[df[\"active_record\"] == 1]\nprint(len(actifs))  # ≈ 500\nprint(actifs[\"department\"].value_counts())\n```","tool":"python","phase":"ingestion"},{"id":"l0-sql","title":"SQL — premier SELECT sur employés","say":"Même fichier, logique SQL : SELECT des actifs, GROUP BY department.","do":"Colle une requête SQL (SELECT … WHERE active_record = 1 … GROUP BY department).","how":["Imagine une table retail_employees chargée depuis le CSV.","COUNT(*) GROUP BY department WHERE active_record = 1."],"trap":"Oublier le WHERE active_record = 1 mélange historique et actif — les effectifs explosent.","expect":"sql","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":40,"mustInclude":["select","group by"],"keywords":["active_record","department","where","count"],"keywordMin":2},"feedbackPass":"Même logique métier en SQL — tu compares les deux paradigmes.","feedbackFail":"Il me faut SELECT + WHERE active_record + GROUP BY department.","correction":"```sql\nSELECT department, COUNT(*) AS n\nFROM retail_employees\nWHERE active_record = 1\nGROUP BY department\nORDER BY n DESC;\n```","tool":"sql","phase":"ingestion"}]}'::jsonb, '{"id":0,"title":"Fondations — SQL & Python sur fichiers","intro":"Premier jour : tu manipules les sources en scripts, pas à la souris.","brief":{"projectName":"Mutualis Retail — scripts de découverte","context":"Tu rejoins l’équipe data Mutualis. L’objectif du jeu : maîtriser SQL / Python / Spark (Databricks) et la stack GCP, plus delivery & gouvernance.","problem":"Sans scripts reproductibles ni orchestration, chaque analyste clique dans son fichier perso — zéro industrialisation.","objectives":["Lire un CSV en pandas et inspecter le schéma.","Filtrer les employés actifs en Python (SCD).","Écrire un premier SELECT SQL d’exploration."],"consigne":"Télécharge le fichier, écris le script notebook, puis réponds aussi à la question de gouvernance data. Une tâche à la fois."},"phase":"ingestion","tools":["python","sql"],"steps":[{"id":"l0-open","title":"Python — inspecter le schéma employés","say":"Télécharge retail_employees.csv. En pandas, charge le fichier et liste les colonnes.","do":"Colle un script Python qui lit le CSV et affiche les colonnes (df.columns / print).","how":["import pandas as pd","df = pd.read_csv(\"retail_employees.csv\")","print(list(df.columns)) ou print(df.dtypes)"],"trap":"Ne te contente pas de recopier l’en-tête à la main : le script doit lire le fichier (read_csv). Sinon tu n’as rien automatisé.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":28,"mustInclude":["read"],"keywords":["pandas","csv","columns","dtype","head","import"],"keywordMin":2},"feedbackPass":"Schéma lu par script — bon réflexe data eng.","feedbackFail":"Il me faut un read_csv (ou équivalent) + inspection des colonnes.","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"retail_employees.csv\")\nprint(list(df.columns))\nprint(df.dtypes)\n```\nColonnes typiques : employee_id, employee_name, department, region, active_record, …","tool":"python","phase":"ingestion"},{"id":"l0-filter","title":"Python — filtre active_record = 1","say":"Le métier ne veut que les fiches actives (SCD). Filtre en pandas et compte les lignes.","do":"Colle un script qui filtre active_record == 1 et affiche len / shape.","how":["df[df[\"active_record\"] == 1]","print(len(actifs)) — attendu autour de 500","Option : actifs[\"department\"].value_counts()"],"trap":"active_record = 0 = anciennes versions de fiche, pas « salarié parti ». Ne filtre pas sur department seul.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":35,"keywords":["active_record","active","pandas","loc","query","len","shape","=="],"keywordMin":2,"patterns":["active_record","\\b500\\b","len\\(|\\.shape"],"patternMin":1},"feedbackPass":"Filtre SCD scripté — prêt pour un job quotidien.","feedbackFail":"Montre le filtre active_record et un comptage (len / shape).","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"retail_employees.csv\")\nactifs = df[df[\"active_record\"] == 1]\nprint(len(actifs))  # ≈ 500\nprint(actifs[\"department\"].value_counts())\n```","tool":"python","phase":"ingestion"},{"id":"l0-sql","title":"SQL — premier SELECT sur employés","say":"Même fichier, logique SQL : SELECT des actifs, GROUP BY department.","do":"Colle une requête SQL (SELECT … WHERE active_record = 1 … GROUP BY department).","how":["Imagine une table retail_employees chargée depuis le CSV.","COUNT(*) GROUP BY department WHERE active_record = 1."],"trap":"Oublier le WHERE active_record = 1 mélange historique et actif — les effectifs explosent.","expect":"sql","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":40,"mustInclude":["select","group by"],"keywords":["active_record","department","where","count"],"keywordMin":2},"feedbackPass":"Même logique métier en SQL — tu compares les deux paradigmes.","feedbackFail":"Il me faut SELECT + WHERE active_record + GROUP BY department.","correction":"```sql\nSELECT department, COUNT(*) AS n\nFROM retail_employees\nWHERE active_record = 1\nGROUP BY department\nORDER BY n DESC;\n```","tool":"sql","phase":"ingestion"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_fr=EXCLUDED.title_fr, intro_fr=EXCLUDED.intro_fr, phase=EXCLUDED.phase, tools=EXCLUDED.tools, payload_fr=EXCLUDED.payload_fr, payload_en=EXCLUDED.payload_en;
