INSERT INTO adventure_levels (id, title_fr, title_en, intro_fr, intro_en, phase, tools, payload_fr, payload_en) VALUES (1, 'Qualité & jointures — SQL / Python', 'Qualité & jointures — SQL / Python', 'Avant le mart : qualité CRM et jointures fiables.', 'Avant le mart : qualité CRM et jointures fiables.', 'ingestion', ARRAY['sql', 'python']::text[], '{"id":1,"title":"Qualité & jointures — SQL / Python","intro":"Avant le mart : qualité CRM et jointures fiables.","brief":{"projectName":"Mutualis Retail — nettoyage & jointures","context":"Le CRM sale et les ventes hebdo doivent être fiabilisés en scripts. On pose la logique avant dbt / BI.","problem":"Des emails en doublon et des jointures mal nettoyées faussent le CA et les effectifs clients.","objectives":["Détecter les doublons email en SQL.","Joindre ventes ↔ clients en SQL.","Nettoyer / dédoublonner en Python (pandas)."],"consigne":"Télécharge les CSV indiqués. Colle le SQL/Python et réponds à la question gouvernance (owner, MDM, grain…)."},"phase":"ingestion","tools":["sql","python"],"steps":[{"id":"l1-dupes","title":"SQL — doublons email CRM","say":"clients_doublons.csv surestime les clients uniques. Détecte les emails en doublon.","do":"Colle une requête GROUP BY email + HAVING COUNT(*) > 1 (avec LOWER/TRIM).","how":["LOWER(TRIM(email))","GROUP BY 1 HAVING COUNT(*) > 1","Ignore email vide / unknown"],"trap":"Les sociétés ne sont pas orthographiées à l’identique — ne te fie pas au nom seul sans LOWER/TRIM sur l’email.","expect":"sql","dataset":{"href":"/data-game/clients_doublons.csv","label":"clients_doublons.csv","hint":"Extract CRM sale : doublons email / orthographes sociétés.","source":"SQL"},"validate":{"minLength":40,"mustInclude":["group by"],"keywords":["having","count","email","lower","trim"],"keywordMin":2},"feedbackPass":"Qualité CRM traitée comme en projet réel.","feedbackFail":"Il me faut GROUP BY email + HAVING COUNT(*) > 1 (+ LOWER/TRIM idéalement).","correction":"```sql\nSELECT LOWER(TRIM(email)) AS email_n, COUNT(*) AS c\nFROM clients_doublons\nWHERE NULLIF(LOWER(TRIM(email)), '''') IS NOT NULL\n  AND LOWER(TRIM(email)) <> ''unknown''\nGROUP BY 1\nHAVING COUNT(*) > 1;\n```","tool":"sql","phase":"ingestion"},{"id":"l1-join","title":"SQL — CA livré joint au référentiel","say":"Avec ventes_semaine + clients_ref, calcule le CA HT des commandes livrées par segment client.","do":"Colle une requête JOIN + SUM + filtre statut = livree.","how":["JOIN clients_ref ON client_id","WHERE statut = ''livree''","GROUP BY segment (ou magasin)"],"trap":"Les commandes « annulee » ne doivent pas entrer dans le CA. Vérifie aussi le type de jointure (INNER vs LEFT).","expect":"sql","dataset":{"href":"/data-game/ventes_semaine.csv","label":"ventes_semaine.csv","hint":"Commandes hebdo Mutualis (statut, magasin, montant).","source":"SQL"},"alsoDownload":[{"href":"/data-game/clients_ref.csv","label":"clients_ref.csv","hint":"Référentiel clients Mutualis (clé client_id).","source":"SQL"}],"validate":{"minLength":50,"mustInclude":["join","sum"],"keywords":["livree","client","montant","group by","on "],"keywordMin":2},"feedbackPass":"Jointure métier + agrégat — cœur du métier data.","feedbackFail":"Il me faut un JOIN, un SUM(montant_ht) et le filtre livree.","correction":"```sql\nSELECT c.segment, SUM(v.montant_ht) AS ca_ht\nFROM ventes_semaine v\nJOIN clients_ref c ON v.client_id = c.client_id\nWHERE v.statut = ''livree''\nGROUP BY c.segment\nORDER BY ca_ht DESC;\n```","tool":"sql","phase":"ingestion"},{"id":"l1-py-clean","title":"Python — dédoublonnage pandas","say":"Reproduis le nettoyage CRM en Python : normalise l’email et drop_duplicates.","do":"Colle un script pandas (str.lower/strip + drop_duplicates).","how":["df[\"email_n\"] = df[\"email\"].str.lower().str.strip()","df.drop_duplicates(subset=[\"email_n\"])","Compare len avant / après"],"trap":"drop_duplicates sans normalisation laisse passer « A@x.com » et « a@x.com » comme deux clients.","expect":"python","dataset":{"href":"/data-game/clients_doublons.csv","label":"clients_doublons.csv","hint":"Extract CRM sale : doublons email / orthographes sociétés.","source":"SQL"},"validate":{"minLength":40,"keywords":["drop_duplicates","lower","strip","email","pandas","read_csv"],"keywordMin":2},"feedbackPass":"Même règle métier en Python — tu peux industrialiser les deux.","feedbackFail":"Montre normalisation email + drop_duplicates (ou groupby).","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"clients_doublons.csv\")\ndf[\"email_n\"] = df[\"email\"].astype(str).str.lower().str.strip()\nclean = df.drop_duplicates(subset=[\"email_n\"])\nprint(len(df), \"→\", len(clean))\n```","tool":"python","phase":"ingestion"}]}'::jsonb, '{"id":1,"title":"Qualité & jointures — SQL / Python","intro":"Avant le mart : qualité CRM et jointures fiables.","brief":{"projectName":"Mutualis Retail — nettoyage & jointures","context":"Le CRM sale et les ventes hebdo doivent être fiabilisés en scripts. On pose la logique avant dbt / BI.","problem":"Des emails en doublon et des jointures mal nettoyées faussent le CA et les effectifs clients.","objectives":["Détecter les doublons email en SQL.","Joindre ventes ↔ clients en SQL.","Nettoyer / dédoublonner en Python (pandas)."],"consigne":"Télécharge les CSV indiqués. Colle le SQL/Python et réponds à la question gouvernance (owner, MDM, grain…)."},"phase":"ingestion","tools":["sql","python"],"steps":[{"id":"l1-dupes","title":"SQL — doublons email CRM","say":"clients_doublons.csv surestime les clients uniques. Détecte les emails en doublon.","do":"Colle une requête GROUP BY email + HAVING COUNT(*) > 1 (avec LOWER/TRIM).","how":["LOWER(TRIM(email))","GROUP BY 1 HAVING COUNT(*) > 1","Ignore email vide / unknown"],"trap":"Les sociétés ne sont pas orthographiées à l’identique — ne te fie pas au nom seul sans LOWER/TRIM sur l’email.","expect":"sql","dataset":{"href":"/data-game/clients_doublons.csv","label":"clients_doublons.csv","hint":"Extract CRM sale : doublons email / orthographes sociétés.","source":"SQL"},"validate":{"minLength":40,"mustInclude":["group by"],"keywords":["having","count","email","lower","trim"],"keywordMin":2},"feedbackPass":"Qualité CRM traitée comme en projet réel.","feedbackFail":"Il me faut GROUP BY email + HAVING COUNT(*) > 1 (+ LOWER/TRIM idéalement).","correction":"```sql\nSELECT LOWER(TRIM(email)) AS email_n, COUNT(*) AS c\nFROM clients_doublons\nWHERE NULLIF(LOWER(TRIM(email)), '''') IS NOT NULL\n  AND LOWER(TRIM(email)) <> ''unknown''\nGROUP BY 1\nHAVING COUNT(*) > 1;\n```","tool":"sql","phase":"ingestion"},{"id":"l1-join","title":"SQL — CA livré joint au référentiel","say":"Avec ventes_semaine + clients_ref, calcule le CA HT des commandes livrées par segment client.","do":"Colle une requête JOIN + SUM + filtre statut = livree.","how":["JOIN clients_ref ON client_id","WHERE statut = ''livree''","GROUP BY segment (ou magasin)"],"trap":"Les commandes « annulee » ne doivent pas entrer dans le CA. Vérifie aussi le type de jointure (INNER vs LEFT).","expect":"sql","dataset":{"href":"/data-game/ventes_semaine.csv","label":"ventes_semaine.csv","hint":"Commandes hebdo Mutualis (statut, magasin, montant).","source":"SQL"},"alsoDownload":[{"href":"/data-game/clients_ref.csv","label":"clients_ref.csv","hint":"Référentiel clients Mutualis (clé client_id).","source":"SQL"}],"validate":{"minLength":50,"mustInclude":["join","sum"],"keywords":["livree","client","montant","group by","on "],"keywordMin":2},"feedbackPass":"Jointure métier + agrégat — cœur du métier data.","feedbackFail":"Il me faut un JOIN, un SUM(montant_ht) et le filtre livree.","correction":"```sql\nSELECT c.segment, SUM(v.montant_ht) AS ca_ht\nFROM ventes_semaine v\nJOIN clients_ref c ON v.client_id = c.client_id\nWHERE v.statut = ''livree''\nGROUP BY c.segment\nORDER BY ca_ht DESC;\n```","tool":"sql","phase":"ingestion"},{"id":"l1-py-clean","title":"Python — dédoublonnage pandas","say":"Reproduis le nettoyage CRM en Python : normalise l’email et drop_duplicates.","do":"Colle un script pandas (str.lower/strip + drop_duplicates).","how":["df[\"email_n\"] = df[\"email\"].str.lower().str.strip()","df.drop_duplicates(subset=[\"email_n\"])","Compare len avant / après"],"trap":"drop_duplicates sans normalisation laisse passer « A@x.com » et « a@x.com » comme deux clients.","expect":"python","dataset":{"href":"/data-game/clients_doublons.csv","label":"clients_doublons.csv","hint":"Extract CRM sale : doublons email / orthographes sociétés.","source":"SQL"},"validate":{"minLength":40,"keywords":["drop_duplicates","lower","strip","email","pandas","read_csv"],"keywordMin":2},"feedbackPass":"Même règle métier en Python — tu peux industrialiser les deux.","feedbackFail":"Montre normalisation email + drop_duplicates (ou groupby).","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"clients_doublons.csv\")\ndf[\"email_n\"] = df[\"email\"].astype(str).str.lower().str.strip()\nclean = df.drop_duplicates(subset=[\"email_n\"])\nprint(len(df), \"→\", len(clean))\n```","tool":"python","phase":"ingestion"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_fr=EXCLUDED.title_fr, intro_fr=EXCLUDED.intro_fr, phase=EXCLUDED.phase, tools=EXCLUDED.tools, payload_fr=EXCLUDED.payload_fr, payload_en=EXCLUDED.payload_en;
