INSERT INTO adventure_levels (id, title_fr, title_en, intro_fr, intro_en, phase, tools, payload_fr, payload_en) VALUES (2, 'SQL avancé — agrégats & fenêtres', 'SQL avancé — agrégats & fenêtres', 'Requêtes d’exploration sur les datasets métier du projet.', 'Requêtes d’exploration sur les datasets métier du projet.', 'ingestion', ARRAY['sql']::text[], '{"id":2,"title":"SQL avancé — agrégats & fenêtres","intro":"Requêtes d’exploration sur les datasets métier du projet.","brief":{"projectName":"Mutualis — SQL sur datasets projet","context":"Appartements, capteur retail, football : tu consolides les patterns SQL (GROUP BY, filtres, CASE).","problem":"Sans requêtes standard, chaque analyste recalcule à sa façon — KPI non auditables.","objectives":["Agrégation immobilière par commune.","Jours sous seuil sur le capteur.","CASE / agrégat sportifs (même geste qu’un mart retail)."],"consigne":"Télécharge le CSV, écris la requête SQL complète, colle-la dans le notebook."},"phase":"ingestion","tools":["sql"],"steps":[{"id":"l2-sql","title":"SQL GROUP BY — appartements","say":"Mutations immobilières : COUNT et AVG(valeur_fonciere) par Commune.","do":"Colle ta requête SQL (GROUP BY Commune).","how":["COUNT(*) et AVG(valeur_fonciere) GROUP BY Commune","ORDER BY nb DESC — LIMIT pour tester"],"trap":"Des colonnes ont des espaces (« Date mutation ») : quote-les. La surface Carrez peut utiliser la virgule française.","expect":"sql","dataset":{"href":"/data-game/appartements_nord_pdc.csv","label":"appartements_nord_pdc.csv","hint":"Mutations immobilières Nord / PdC — module SQL.","source":"SQL"},"validate":{"minLength":40,"mustInclude":["select","group by"],"keywords":["commune","count","avg","valeur"],"keywordMin":2},"feedbackPass":"Agrégation SQL posée sur une vraie base métier.","feedbackFail":"Il me faut SELECT + GROUP BY (Commune) et un agrégat COUNT/AVG.","correction":"```sql\nSELECT Commune,\n       COUNT(*) AS nb_mutations,\n       AVG(valeur_fonciere) AS vf_moyenne\nFROM appartements_nord_pdc\nGROUP BY Commune\nORDER BY nb_mutations DESC;\n```","tool":"sql","phase":"ingestion"},{"id":"l2-capteur","title":"SQL — jours sous seuil capteur","say":"capteur_a_retail : jours où visiteurs_count < threshold_twenty_pct.","do":"Colle une requête SQL avec le filtre sur threshold_twenty_pct.","how":["WHERE visiteurs_count < threshold_twenty_pct","SELECT date, visiteurs_count, threshold_twenty_pct"],"trap":"N’invente pas « 20 % » à la main : utilise la colonne threshold_twenty_pct ligne à ligne.","expect":"sql","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"validate":{"minLength":40,"mustInclude":["select","where"],"keywords":["threshold","visiteur","select"],"keywordMin":2,"patterns":["threshold_twenty_pct","2023-08-1[47]"],"patternMin":1},"feedbackPass":"Signal ops lu en SQL — prêt pour un alerting.","feedbackFail":"Filtre visiteurs vs threshold_twenty_pct (ou dates 2023-08-14 / 17).","correction":"```sql\nSELECT date, visiteurs_count, threshold_twenty_pct\nFROM capteur_a_retail\nWHERE visiteurs_count < threshold_twenty_pct;\n```\nJours typiques : 2023-08-14 et 2023-08-17.","tool":"sql","phase":"ingestion"},{"id":"l2-foot","title":"SQL — CASE WHEN / HomeTeam","say":"football_season_1011 : matchs et victoires domicile (FTR = H) par HomeTeam.","do":"Colle une requête avec GROUP BY HomeTeam et CASE WHEN FTR = ''H''.","how":["SUM(CASE WHEN FTR = ''H'' THEN 1 ELSE 0 END)","WHERE Div = ''F1'' optionnel"],"trap":"Dates au format JJ/MM/AA — ne les parse pas comme MM/JJ/AAAA.","expect":"sql","dataset":{"href":"/data-game/football_season_1011.csv","label":"football_season_1011.csv","hint":"Résultats Ligue 1 saison 2010-11 — module SQL.","source":"SQL"},"alsoDownload":[{"href":"/data-game/notes_season_1011.txt","label":"notes_season_1011.txt","hint":"Notes associées au dataset football.","source":"SQL"}],"validate":{"minLength":50,"mustInclude":["group by","hometeam"],"keywords":["case","ftr","count","when","sum"],"keywordMin":2},"feedbackPass":"CASE + agrégat — pattern de mart KPI.","feedbackFail":"GROUP BY HomeTeam + CASE sur FTR = H.","correction":"```sql\nSELECT HomeTeam,\n       COUNT(*) AS nb_matchs,\n       SUM(CASE WHEN FTR = ''H'' THEN 1 ELSE 0 END) AS victoires_domicile\nFROM football_season_1011\nWHERE Div = ''F1''\nGROUP BY HomeTeam\nORDER BY victoires_domicile DESC;\n```","tool":"sql","phase":"ingestion"},{"id":"l2-window","title":"SQL — fenêtre sur le CA retail","say":"Sur weights_turnover_sample : classements / running total par magasin (fenêtre).","do":"Colle une requête avec OVER (PARTITION BY … ORDER BY …) — RANK ou SUM.","how":["PARTITION BY store_name","SUM(turnover_weight) OVER (...) ou RANK()"],"trap":"Sans PARTITION BY store_name, tu classes tous les magasins ensemble — le ranking métier n’a plus de sens.","expect":"sql","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"validate":{"minLength":45,"mustInclude":["over"],"keywords":["partition","rank","sum","order by","store","turnover"],"keywordMin":2},"feedbackPass":"Window functions — niveau senior SQL data.","feedbackFail":"Il me faut une clause OVER (… PARTITION BY …).","correction":"```sql\nSELECT store_name, quarterhour, turnover_weight,\n       SUM(turnover_weight) OVER (\n         PARTITION BY store_name ORDER BY quarterhour\n       ) AS running_weight,\n       RANK() OVER (\n         PARTITION BY store_name ORDER BY turnover_weight DESC\n       ) AS rnk\nFROM weights_turnover_sample;\n```","tool":"sql","phase":"ingestion"}]}'::jsonb, '{"id":2,"title":"SQL avancé — agrégats & fenêtres","intro":"Requêtes d’exploration sur les datasets métier du projet.","brief":{"projectName":"Mutualis — SQL sur datasets projet","context":"Appartements, capteur retail, football : tu consolides les patterns SQL (GROUP BY, filtres, CASE).","problem":"Sans requêtes standard, chaque analyste recalcule à sa façon — KPI non auditables.","objectives":["Agrégation immobilière par commune.","Jours sous seuil sur le capteur.","CASE / agrégat sportifs (même geste qu’un mart retail)."],"consigne":"Télécharge le CSV, écris la requête SQL complète, colle-la dans le notebook."},"phase":"ingestion","tools":["sql"],"steps":[{"id":"l2-sql","title":"SQL GROUP BY — appartements","say":"Mutations immobilières : COUNT et AVG(valeur_fonciere) par Commune.","do":"Colle ta requête SQL (GROUP BY Commune).","how":["COUNT(*) et AVG(valeur_fonciere) GROUP BY Commune","ORDER BY nb DESC — LIMIT pour tester"],"trap":"Des colonnes ont des espaces (« Date mutation ») : quote-les. La surface Carrez peut utiliser la virgule française.","expect":"sql","dataset":{"href":"/data-game/appartements_nord_pdc.csv","label":"appartements_nord_pdc.csv","hint":"Mutations immobilières Nord / PdC — module SQL.","source":"SQL"},"validate":{"minLength":40,"mustInclude":["select","group by"],"keywords":["commune","count","avg","valeur"],"keywordMin":2},"feedbackPass":"Agrégation SQL posée sur une vraie base métier.","feedbackFail":"Il me faut SELECT + GROUP BY (Commune) et un agrégat COUNT/AVG.","correction":"```sql\nSELECT Commune,\n       COUNT(*) AS nb_mutations,\n       AVG(valeur_fonciere) AS vf_moyenne\nFROM appartements_nord_pdc\nGROUP BY Commune\nORDER BY nb_mutations DESC;\n```","tool":"sql","phase":"ingestion"},{"id":"l2-capteur","title":"SQL — jours sous seuil capteur","say":"capteur_a_retail : jours où visiteurs_count < threshold_twenty_pct.","do":"Colle une requête SQL avec le filtre sur threshold_twenty_pct.","how":["WHERE visiteurs_count < threshold_twenty_pct","SELECT date, visiteurs_count, threshold_twenty_pct"],"trap":"N’invente pas « 20 % » à la main : utilise la colonne threshold_twenty_pct ligne à ligne.","expect":"sql","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"validate":{"minLength":40,"mustInclude":["select","where"],"keywords":["threshold","visiteur","select"],"keywordMin":2,"patterns":["threshold_twenty_pct","2023-08-1[47]"],"patternMin":1},"feedbackPass":"Signal ops lu en SQL — prêt pour un alerting.","feedbackFail":"Filtre visiteurs vs threshold_twenty_pct (ou dates 2023-08-14 / 17).","correction":"```sql\nSELECT date, visiteurs_count, threshold_twenty_pct\nFROM capteur_a_retail\nWHERE visiteurs_count < threshold_twenty_pct;\n```\nJours typiques : 2023-08-14 et 2023-08-17.","tool":"sql","phase":"ingestion"},{"id":"l2-foot","title":"SQL — CASE WHEN / HomeTeam","say":"football_season_1011 : matchs et victoires domicile (FTR = H) par HomeTeam.","do":"Colle une requête avec GROUP BY HomeTeam et CASE WHEN FTR = ''H''.","how":["SUM(CASE WHEN FTR = ''H'' THEN 1 ELSE 0 END)","WHERE Div = ''F1'' optionnel"],"trap":"Dates au format JJ/MM/AA — ne les parse pas comme MM/JJ/AAAA.","expect":"sql","dataset":{"href":"/data-game/football_season_1011.csv","label":"football_season_1011.csv","hint":"Résultats Ligue 1 saison 2010-11 — module SQL.","source":"SQL"},"alsoDownload":[{"href":"/data-game/notes_season_1011.txt","label":"notes_season_1011.txt","hint":"Notes associées au dataset football.","source":"SQL"}],"validate":{"minLength":50,"mustInclude":["group by","hometeam"],"keywords":["case","ftr","count","when","sum"],"keywordMin":2},"feedbackPass":"CASE + agrégat — pattern de mart KPI.","feedbackFail":"GROUP BY HomeTeam + CASE sur FTR = H.","correction":"```sql\nSELECT HomeTeam,\n       COUNT(*) AS nb_matchs,\n       SUM(CASE WHEN FTR = ''H'' THEN 1 ELSE 0 END) AS victoires_domicile\nFROM football_season_1011\nWHERE Div = ''F1''\nGROUP BY HomeTeam\nORDER BY victoires_domicile DESC;\n```","tool":"sql","phase":"ingestion"},{"id":"l2-window","title":"SQL — fenêtre sur le CA retail","say":"Sur weights_turnover_sample : classements / running total par magasin (fenêtre).","do":"Colle une requête avec OVER (PARTITION BY … ORDER BY …) — RANK ou SUM.","how":["PARTITION BY store_name","SUM(turnover_weight) OVER (...) ou RANK()"],"trap":"Sans PARTITION BY store_name, tu classes tous les magasins ensemble — le ranking métier n’a plus de sens.","expect":"sql","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"validate":{"minLength":45,"mustInclude":["over"],"keywords":["partition","rank","sum","order by","store","turnover"],"keywordMin":2},"feedbackPass":"Window functions — niveau senior SQL data.","feedbackFail":"Il me faut une clause OVER (… PARTITION BY …).","correction":"```sql\nSELECT store_name, quarterhour, turnover_weight,\n       SUM(turnover_weight) OVER (\n         PARTITION BY store_name ORDER BY quarterhour\n       ) AS running_weight,\n       RANK() OVER (\n         PARTITION BY store_name ORDER BY turnover_weight DESC\n       ) AS rnk\nFROM weights_turnover_sample;\n```","tool":"sql","phase":"ingestion"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_fr=EXCLUDED.title_fr, intro_fr=EXCLUDED.intro_fr, phase=EXCLUDED.phase, tools=EXCLUDED.tools, payload_fr=EXCLUDED.payload_fr, payload_en=EXCLUDED.payload_en;
