INSERT INTO adventure_steps (id, level_id, sort_order, title_fr, title_en, say_fr, say_en, do_fr, do_en, expect_type, correction_fr, correction_en, keywords, tool_id, phase, payload_fr, payload_en) VALUES ('l2-window', 2, 3, 'SQL — fenêtre sur le CA retail', 'SQL — fenêtre sur le CA retail', 'Sur weights_turnover_sample : classements / running total par magasin (fenêtre).', 'Sur weights_turnover_sample : classements / running total par magasin (fenêtre).', 'Colle une requête avec OVER (PARTITION BY … ORDER BY …) — RANK ou SUM.', 'Colle une requête avec OVER (PARTITION BY … ORDER BY …) — RANK ou SUM.', 'sql', '```sql
INSERT INTO adventure_levels (id, title_fr, title_en, intro_fr, intro_en, phase, tools, payload_fr, payload_en) VALUES (3, 'Python ETL & dbt SQL', 'Python ETL & dbt SQL', 'Transformer : JSON, pandas, modèles dbt.', 'Transformer : JSON, pandas, modèles dbt.', 'transformation', ARRAY['python', 'dbt', 'sql']::text[], '{"id":3,"title":"Python ETL & dbt SQL","intro":"Transformer : JSON, pandas, modèles dbt.","brief":{"projectName":"Mutualis — Python & dbt","context":"JSON machine, SCD employés, modèles staging→mart : tu industrialises la transformation en code.","problem":"Sans parsing JSON, filtre SCD ni couches dbt, le mart mélange historique et actif.","objectives":["Parser le JSON machine en Python.","Pipeline pandas CSV → clean → export.","Écrire stg_ / mart_ en SQL dbt + tests."],"consigne":"Scripts complets uniquement — pas de résumé texte."},"phase":"transformation","tools":["python","dbt","sql"],"steps":[{"id":"l3-json","title":"Python — parser drill_machine.json","say":"Extrais machine_id, status et location.region via json.load.","do":"Colle un script Python complet (open + json.load + print des 3 champs).","how":["import json","data[\"machine_id\"], data[\"status\"], data[\"location\"][\"region\"]"],"trap":"region est imbriquée sous location — data[\"region\"] lève une KeyError.","expect":"python","dataset":{"href":"/data-game/drill_machine.json","label":"drill_machine.json","hint":"Fiche machine (JSON) — module Python.","source":"Python"},"validate":{"minLength":40,"mustInclude":["json"],"keywords":["load","machine_id","status","location","region","open"],"keywordMin":2},"feedbackPass":"Parsing JSON OK — geste Python de base en projet.","feedbackFail":"Script avec json.load + accès machine_id / status / location.region.","correction":"```python\nimport json\nwith open(\"drill_machine.json\", encoding=\"utf-8\") as f:\n    data = json.load(f)\nprint(data[\"machine_id\"], data[\"status\"], data[\"location\"][\"region\"])\n```\n→ DM-2 · Under Maintenance · San Juan Basin","tool":"python","phase":"transformation"},{"id":"l3-py","title":"Python — ETL employés actifs","say":"Pipeline : read_csv → filtre active_record == 1 → to_csv.","do":"Colle le script pandas complet (lecture, filtre, écriture).","how":["actifs = df[df[\"active_record\"] == 1]","actifs.to_csv(\"employees_actifs.csv\", index=False)"],"trap":"Certaines lignes OFFICE ont region vide — un groupby region sans fillna crée un bucket trompeur.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":50,"keywords":["read_csv","to_csv","active_record","pandas"],"keywordMin":2},"feedbackPass":"ETL pandas industrialisable.","feedbackFail":"Montre read_csv + filtre active_record + to_csv.","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"retail_employees.csv\")\nactifs = df[df[\"active_record\"] == 1]\nactifs.to_csv(\"employees_actifs.csv\", index=False)\n```","tool":"python","phase":"transformation"},{"id":"l3-py-merge","title":"Python — merge ventes × clients","say":"En pandas, joint ventes_semaine et clients_ref, filtre livree, agrège le CA.","do":"Colle un script merge + groupby + sum.","how":["pd.merge(..., on=\"client_id\")","query statut == ''livree''","groupby(\"segment\" ou \"magasin\")[\"montant_ht\"].sum()"],"trap":"Un merge sans valider les clés (dtypes / espaces) produit des NaN silencieux sur le CA.","expect":"python","dataset":{"href":"/data-game/ventes_semaine.csv","label":"ventes_semaine.csv","hint":"Commandes hebdo Mutualis (statut, magasin, montant).","source":"SQL"},"alsoDownload":[{"href":"/data-game/clients_ref.csv","label":"clients_ref.csv","hint":"Référentiel clients Mutualis (clé client_id).","source":"SQL"}],"validate":{"minLength":55,"keywords":["merge","groupby","montant","livree","sum","read_csv"],"keywordMin":2},"feedbackPass":"Jointure pandas — miroir du SQL JOIN.","feedbackFail":"Il me faut merge + filtre livree + agrégation sum.","correction":"```python\nimport pandas as pd\nv = pd.read_csv(\"ventes_semaine.csv\")\nc = pd.read_csv(\"clients_ref.csv\")\nm = v.merge(c, on=\"client_id\", how=\"inner\")\nca = (\n    m[m[\"statut\"] == \"livree\"]\n    .groupby(\"segment\")[\"montant_ht\"]\n    .sum()\n    .sort_values(ascending=False)\n)\nprint(ca)\n```","tool":"python","phase":"transformation"},{"id":"l3-dbt","title":"dbt SQL — staging → mart","say":"Pose stg_ + mart_ employés actifs + un test unique/not_null.","do":"Colle le SQL dbt (stg_… / mart_…) et les tests.","how":["stg_spark__retail_employees","mart_employees_actifs WHERE active_record = 1","tests unique + not_null sur employee_id (mart)"],"trap":"unique(employee_id) sur le staging brut échoue (versions SCD). Place le test sur le mart filtré.","expect":"sql","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":40,"mustInclude":["stg","mart"],"keywords":["unique","not_null","active","select","where","ref"],"keywordMin":2},"feedbackPass":"Couches dbt posées — transformation versionnée.","feedbackFail":"Cite stg_ + mart_ et un test unique / not_null.","correction":"```sql\n-- stg_spark__retail_employees.sql\nSELECT * FROM {{ source(''spark'', ''retail_employees'') }};\n\n-- mart_employees_actifs.sql\nSELECT * FROM {{ ref(''stg_spark__retail_employees'') }}\nWHERE active_record = 1;\n```\nTests YAML : not_null + unique sur employee_id du mart.","tool":"dbt","phase":"transformation"}]}'::jsonb, '{"id":3,"title":"Python ETL & dbt SQL","intro":"Transformer : JSON, pandas, modèles dbt.","brief":{"projectName":"Mutualis — Python & dbt","context":"JSON machine, SCD employés, modèles staging→mart : tu industrialises la transformation en code.","problem":"Sans parsing JSON, filtre SCD ni couches dbt, le mart mélange historique et actif.","objectives":["Parser le JSON machine en Python.","Pipeline pandas CSV → clean → export.","Écrire stg_ / mart_ en SQL dbt + tests."],"consigne":"Scripts complets uniquement — pas de résumé texte."},"phase":"transformation","tools":["python","dbt","sql"],"steps":[{"id":"l3-json","title":"Python — parser drill_machine.json","say":"Extrais machine_id, status et location.region via json.load.","do":"Colle un script Python complet (open + json.load + print des 3 champs).","how":["import json","data[\"machine_id\"], data[\"status\"], data[\"location\"][\"region\"]"],"trap":"region est imbriquée sous location — data[\"region\"] lève une KeyError.","expect":"python","dataset":{"href":"/data-game/drill_machine.json","label":"drill_machine.json","hint":"Fiche machine (JSON) — module Python.","source":"Python"},"validate":{"minLength":40,"mustInclude":["json"],"keywords":["load","machine_id","status","location","region","open"],"keywordMin":2},"feedbackPass":"Parsing JSON OK — geste Python de base en projet.","feedbackFail":"Script avec json.load + accès machine_id / status / location.region.","correction":"```python\nimport json\nwith open(\"drill_machine.json\", encoding=\"utf-8\") as f:\n    data = json.load(f)\nprint(data[\"machine_id\"], data[\"status\"], data[\"location\"][\"region\"])\n```\n→ DM-2 · Under Maintenance · San Juan Basin","tool":"python","phase":"transformation"},{"id":"l3-py","title":"Python — ETL employés actifs","say":"Pipeline : read_csv → filtre active_record == 1 → to_csv.","do":"Colle le script pandas complet (lecture, filtre, écriture).","how":["actifs = df[df[\"active_record\"] == 1]","actifs.to_csv(\"employees_actifs.csv\", index=False)"],"trap":"Certaines lignes OFFICE ont region vide — un groupby region sans fillna crée un bucket trompeur.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":50,"keywords":["read_csv","to_csv","active_record","pandas"],"keywordMin":2},"feedbackPass":"ETL pandas industrialisable.","feedbackFail":"Montre read_csv + filtre active_record + to_csv.","correction":"```python\nimport pandas as pd\ndf = pd.read_csv(\"retail_employees.csv\")\nactifs = df[df[\"active_record\"] == 1]\nactifs.to_csv(\"employees_actifs.csv\", index=False)\n```","tool":"python","phase":"transformation"},{"id":"l3-py-merge","title":"Python — merge ventes × clients","say":"En pandas, joint ventes_semaine et clients_ref, filtre livree, agrège le CA.","do":"Colle un script merge + groupby + sum.","how":["pd.merge(..., on=\"client_id\")","query statut == ''livree''","groupby(\"segment\" ou \"magasin\")[\"montant_ht\"].sum()"],"trap":"Un merge sans valider les clés (dtypes / espaces) produit des NaN silencieux sur le CA.","expect":"python","dataset":{"href":"/data-game/ventes_semaine.csv","label":"ventes_semaine.csv","hint":"Commandes hebdo Mutualis (statut, magasin, montant).","source":"SQL"},"alsoDownload":[{"href":"/data-game/clients_ref.csv","label":"clients_ref.csv","hint":"Référentiel clients Mutualis (clé client_id).","source":"SQL"}],"validate":{"minLength":55,"keywords":["merge","groupby","montant","livree","sum","read_csv"],"keywordMin":2},"feedbackPass":"Jointure pandas — miroir du SQL JOIN.","feedbackFail":"Il me faut merge + filtre livree + agrégation sum.","correction":"```python\nimport pandas as pd\nv = pd.read_csv(\"ventes_semaine.csv\")\nc = pd.read_csv(\"clients_ref.csv\")\nm = v.merge(c, on=\"client_id\", how=\"inner\")\nca = (\n    m[m[\"statut\"] == \"livree\"]\n    .groupby(\"segment\")[\"montant_ht\"]\n    .sum()\n    .sort_values(ascending=False)\n)\nprint(ca)\n```","tool":"python","phase":"transformation"},{"id":"l3-dbt","title":"dbt SQL — staging → mart","say":"Pose stg_ + mart_ employés actifs + un test unique/not_null.","do":"Colle le SQL dbt (stg_… / mart_…) et les tests.","how":["stg_spark__retail_employees","mart_employees_actifs WHERE active_record = 1","tests unique + not_null sur employee_id (mart)"],"trap":"unique(employee_id) sur le staging brut échoue (versions SCD). Place le test sur le mart filtré.","expect":"sql","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":40,"mustInclude":["stg","mart"],"keywords":["unique","not_null","active","select","where","ref"],"keywordMin":2},"feedbackPass":"Couches dbt posées — transformation versionnée.","feedbackFail":"Cite stg_ + mart_ et un test unique / not_null.","correction":"```sql\n-- stg_spark__retail_employees.sql\nSELECT * FROM {{ source(''spark'', ''retail_employees'') }};\n\n-- mart_employees_actifs.sql\nSELECT * FROM {{ ref(''stg_spark__retail_employees'') }}\nWHERE active_record = 1;\n```\nTests YAML : not_null + unique sur employee_id du mart.","tool":"dbt","phase":"transformation"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_fr=EXCLUDED.title_fr, intro_fr=EXCLUDED.intro_fr, phase=EXCLUDED.phase, tools=EXCLUDED.tools, payload_fr=EXCLUDED.payload_fr, payload_en=EXCLUDED.payload_en;
