INSERT INTO adventure_levels (id, title_fr, title_en, intro_fr, intro_en, phase, tools, payload_fr, payload_en) VALUES (4, 'KPI en code — SQL métriques & Python grain', 'KPI en code — SQL métriques & Python grain', 'La gouvernance et la BI commencent par des définitions exécutables.', 'La gouvernance et la BI commencent par des définitions exécutables.', 'gouvernance', ARRAY['sql', 'python', 'powerbi']::text[], '{"id":4,"title":"KPI en code — SQL métriques & Python grain","intro":"La gouvernance et la BI commencent par des définitions exécutables.","brief":{"projectName":"Mutualis — métriques certifiées en scripts","context":"Avant Power BI / DataGalaxy, tu codes la définition KPI et le croisement de grains.","problem":"Sans requête de référence, deux dashboards comparent des « intensités CA » incomparables.","objectives":["Écrire la requête KPI de référence (SQL).","Croiser fréquentation × intensité en SQL ou Python.","Esquisser une mesure (commentaire SQL/DAX) — capture optionnelle."],"consigne":"Priorité au code. Une capture BI n’est utile qu’après la requête de vérité."},"phase":"gouvernance","tools":["sql","python","powerbi"],"steps":[{"id":"l4-kpi-sql","title":"SQL — requête KPI intensité CA","say":"Définis le KPI « intensité CA » comme une requête : SUM(turnover_weight) par magasin / jour.","do":"Colle la requête SQL de référence (GROUP BY store_name, date éventuelle).","how":["SUM(turnover_weight) GROUP BY store_name","Documente le grain en commentaire SQL"],"trap":"Sans préciser le grain (magasin / jour / créneau), deux directions compareront des totaux faux.","expect":"sql","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"alsoDownload":[{"href":"/data-game/weights_turnover_retail.csv","label":"weights_turnover_retail.csv","hint":"Poids de CA retail complet (~87k lignes) — module SQL.","source":"SQL"}],"validate":{"minLength":40,"mustInclude":["sum","group by"],"keywords":["turnover","store","weight","select"],"keywordMin":2},"feedbackPass":"KPI = requête versionnable — base de gouvernance.","feedbackFail":"Il me faut SUM(turnover_weight) + GROUP BY magasin.","correction":"```sql\n-- Grain : magasin (échantillon) — documenter owner Retail\nSELECT store_name,\n       SUM(turnover_weight) AS intensite_ca\nFROM weights_turnover_sample\nGROUP BY store_name\nORDER BY intensite_ca DESC;\n```","tool":"sql","phase":"gouvernance"},{"id":"l4-grain","title":"Python — aligner grains capteur × CA","say":"capteur = 1 ligne/jour (global) ; weights = magasin×créneau. Agrège weights par magasin avant toute jointure — pas de clé date commune.","do":"Colle un script Python qui agrège weights par store_name et documente pourquoi on ne merge pas aveuglément avec capteur.","how":["weights.groupby(\"store_name\")[\"turnover_weight\"].sum()","capteur sans magasin → pas de merge 1:1","ratio intensité par magasin (sans diviser par visiteurs magasin absents)"],"trap":"Joindre sans agréger multiplie les lignes (créneaux × jour) et fausse les totaux.","expect":"python","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"alsoDownload":[{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"}],"validate":{"minLength":50,"keywords":["groupby","store","sum","turnover","read_csv","grain","magasin"],"keywordMin":2},"feedbackPass":"Tu raisonnes grain avant dashboard — essentiel.","feedbackFail":"Montre une agrégation par magasin et explique l’absence de clé commune avec capteur.","correction":"```python\nimport pandas as pd\ncap = pd.read_csv(\"capteur_a_retail.csv\")\nw = pd.read_csv(\"weights_turnover_sample.csv\")\nby_store = w.groupby(\"store_name\", as_index=False)[\"turnover_weight\"].sum()\n# capteur = trafic journalier global (pas de store_name) — pas de merge direct\nprint(by_store.head())\nprint(cap[[\"date\", \"visiteurs_count\"]].head())\n```","tool":"python","phase":"gouvernance"},{"id":"l4-pbi","title":"Mesure BI (après la vérité SQL)","say":"Maintenant seulement : propose la mesure DAX/équivalent alignée sur ta requête KPI, avec capture optionnelle.","do":"Colle la mesure (SUM…) et joins une capture si tu as Power BI / Looker / Sheets.","how":["Mesure = SUM(turnover_weight) — même grain que la requête","Capture du visuel par store_name (fichier optionnel)"],"trap":"Une belle carte Power BI qui ne matche pas la requête SQL de référence n’a aucune valeur en comité.","expect":"screenshot","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"validate":{"requireFile":false,"minLength":12,"keywords":["sum","turnover","weight","dax","mesure","store"],"keywordMin":1},"feedbackPass":"BI branchée sur une définition SQL — bon ordre.","feedbackFail":"Écris au moins la mesure SUM(turnover_weight) (capture bonus).","correction":"Intensité CA = SUM(weights[turnover_weight]) — doit matcher la requête l4-kpi-sql.","tool":"powerbi","phase":"gouvernance"}]}'::jsonb, '{"id":4,"title":"KPI en code — SQL métriques & Python grain","intro":"La gouvernance et la BI commencent par des définitions exécutables.","brief":{"projectName":"Mutualis — métriques certifiées en scripts","context":"Avant Power BI / DataGalaxy, tu codes la définition KPI et le croisement de grains.","problem":"Sans requête de référence, deux dashboards comparent des « intensités CA » incomparables.","objectives":["Écrire la requête KPI de référence (SQL).","Croiser fréquentation × intensité en SQL ou Python.","Esquisser une mesure (commentaire SQL/DAX) — capture optionnelle."],"consigne":"Priorité au code. Une capture BI n’est utile qu’après la requête de vérité."},"phase":"gouvernance","tools":["sql","python","powerbi"],"steps":[{"id":"l4-kpi-sql","title":"SQL — requête KPI intensité CA","say":"Définis le KPI « intensité CA » comme une requête : SUM(turnover_weight) par magasin / jour.","do":"Colle la requête SQL de référence (GROUP BY store_name, date éventuelle).","how":["SUM(turnover_weight) GROUP BY store_name","Documente le grain en commentaire SQL"],"trap":"Sans préciser le grain (magasin / jour / créneau), deux directions compareront des totaux faux.","expect":"sql","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"alsoDownload":[{"href":"/data-game/weights_turnover_retail.csv","label":"weights_turnover_retail.csv","hint":"Poids de CA retail complet (~87k lignes) — module SQL.","source":"SQL"}],"validate":{"minLength":40,"mustInclude":["sum","group by"],"keywords":["turnover","store","weight","select"],"keywordMin":2},"feedbackPass":"KPI = requête versionnable — base de gouvernance.","feedbackFail":"Il me faut SUM(turnover_weight) + GROUP BY magasin.","correction":"```sql\n-- Grain : magasin (échantillon) — documenter owner Retail\nSELECT store_name,\n       SUM(turnover_weight) AS intensite_ca\nFROM weights_turnover_sample\nGROUP BY store_name\nORDER BY intensite_ca DESC;\n```","tool":"sql","phase":"gouvernance"},{"id":"l4-grain","title":"Python — aligner grains capteur × CA","say":"capteur = 1 ligne/jour (global) ; weights = magasin×créneau. Agrège weights par magasin avant toute jointure — pas de clé date commune.","do":"Colle un script Python qui agrège weights par store_name et documente pourquoi on ne merge pas aveuglément avec capteur.","how":["weights.groupby(\"store_name\")[\"turnover_weight\"].sum()","capteur sans magasin → pas de merge 1:1","ratio intensité par magasin (sans diviser par visiteurs magasin absents)"],"trap":"Joindre sans agréger multiplie les lignes (créneaux × jour) et fausse les totaux.","expect":"python","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"alsoDownload":[{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"}],"validate":{"minLength":50,"keywords":["groupby","store","sum","turnover","read_csv","grain","magasin"],"keywordMin":2},"feedbackPass":"Tu raisonnes grain avant dashboard — essentiel.","feedbackFail":"Montre une agrégation par magasin et explique l’absence de clé commune avec capteur.","correction":"```python\nimport pandas as pd\ncap = pd.read_csv(\"capteur_a_retail.csv\")\nw = pd.read_csv(\"weights_turnover_sample.csv\")\nby_store = w.groupby(\"store_name\", as_index=False)[\"turnover_weight\"].sum()\n# capteur = trafic journalier global (pas de store_name) — pas de merge direct\nprint(by_store.head())\nprint(cap[[\"date\", \"visiteurs_count\"]].head())\n```","tool":"python","phase":"gouvernance"},{"id":"l4-pbi","title":"Mesure BI (après la vérité SQL)","say":"Maintenant seulement : propose la mesure DAX/équivalent alignée sur ta requête KPI, avec capture optionnelle.","do":"Colle la mesure (SUM…) et joins une capture si tu as Power BI / Looker / Sheets.","how":["Mesure = SUM(turnover_weight) — même grain que la requête","Capture du visuel par store_name (fichier optionnel)"],"trap":"Une belle carte Power BI qui ne matche pas la requête SQL de référence n’a aucune valeur en comité.","expect":"screenshot","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"validate":{"requireFile":false,"minLength":12,"keywords":["sum","turnover","weight","dax","mesure","store"],"keywordMin":1},"feedbackPass":"BI branchée sur une définition SQL — bon ordre.","feedbackFail":"Écris au moins la mesure SUM(turnover_weight) (capture bonus).","correction":"Intensité CA = SUM(weights[turnover_weight]) — doit matcher la requête l4-kpi-sql.","tool":"powerbi","phase":"gouvernance"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_fr=EXCLUDED.title_fr, intro_fr=EXCLUDED.intro_fr, phase=EXCLUDED.phase, tools=EXCLUDED.tools, payload_fr=EXCLUDED.payload_fr, payload_en=EXCLUDED.payload_en;
