INSERT INTO adventure_steps (id, level_id, sort_order, title_fr, title_en, say_fr, say_en, do_fr, do_en, expect_type, correction_fr, correction_en, keywords, tool_id, phase, payload_fr, payload_en) VALUES ('l4-pbi', 4, 2, 'Mesure BI (après la vérité SQL)', 'Mesure BI (après la vérité SQL)', 'Maintenant seulement : propose la mesure DAX/équivalent alignée sur ta requête KPI, avec capture optionnelle.', 'Maintenant seulement : propose la mesure DAX/équivalent alignée sur ta requête KPI, avec capture optionnelle.', 'Colle la mesure (SUM…) et joins une capture si tu as Power BI / Looker / Sheets.', 'Colle la mesure (SUM…) et joins une capture si tu as Power BI / Looker / Sheets.', 'screenshot', 'Intensité CA = SUM(weights[turnover_weight]) — doit matcher la requête l4-kpi-sql.', 'Intensité CA = SUM(weights[turnover_weight]) — doit matcher la requête l4-kpi-sql.', ARRAY['sum', 'turnover', 'weight', 'dax', 'mesure', 'store']::text[], 'powerbi', 'gouvernance', '{"id":"l4-pbi","title":"Mesure BI (après la vérité SQL)","say":"Maintenant seulement : propose la mesure DAX/équivalent alignée sur ta requête KPI, avec capture optionnelle.","do":"Colle la mesure (SUM…) et joins une capture si tu as Power BI / Looker / Sheets.","how":["Mesure = SUM(turnover_weight) — même grain que la requête","Capture du visuel par store_name (fichier optionnel)"],"trap":"Une belle carte Power BI qui ne matche pas la requête SQL de référence n’a aucune valeur en comité.","expect":"screenshot","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"validate":{"requireFile":false,"minLength":12,"keywords":["sum","turnover","weight","dax","mesure","store"],"keywordMin":1},"feedbackPass":"BI branchée sur une définition SQL — bon ordre.","feedbackFail":"Écris au moins la mesure SUM(turnover_weight) (capture bonus).","correction":"Intensité CA = SUM(weights[turnover_weight]) — doit matcher la requête l4-kpi-sql.","tool":"powerbi","phase":"gouvernance"}'::jsonb, '{"id":"l4-pbi","title":"Mesure BI (après la vérité SQL)","say":"Maintenant seulement : propose la mesure DAX/équivalent alignée sur ta requête KPI, avec capture optionnelle.","do":"Colle la mesure (SUM…) et joins une capture si tu as Power BI / Looker / Sheets.","how":["Mesure = SUM(turnover_weight) — même grain que la requête","Capture du visuel par store_name (fichier optionnel)"],"trap":"Une belle carte Power BI qui ne matche pas la requête SQL de référence n’a aucune valeur en comité.","expect":"screenshot","dataset":{"href":"/data-game/weights_turnover_sample.csv","label":"weights_turnover_sample.csv","hint":"Échantillon léger (~480 lignes, 6 magasins) pour Power BI — UTF-8.","source":"SQL"},"validate":{"requireFile":false,"minLength":12,"keywords":["sum","turnover","weight","dax","mesure","store"],"keywordMin":1},"feedbackPass":"BI branchée sur une définition SQL — bon ordre.","feedbackFail":"Écris au moins la mesure SUM(turnover_weight) (capture bonus).","correction":"Intensité CA = SUM(weights[turnover_weight]) — doit matcher la requête l4-kpi-sql.","tool":"powerbi","phase":"gouvernance"}'::jsonb) ON CONFLICT (id) DO UPDATE SET level_id=EXCLUDED.level_id, sort_order=EXCLUDED.sort_order, title_fr=EXCLUDED.title_fr, say_fr=EXCLUDED.say_fr, do_fr=EXCLUDED.do_fr, expect_type=EXCLUDED.expect_type, correction_fr=EXCLUDED.correction_fr, keywords=EXCLUDED.keywords, tool_id=EXCLUDED.tool_id, phase=EXCLUDED.phase, payload_fr=EXCLUDED.payload_fr;
INSERT INTO adventure_levels (id, title_fr, title_en, intro_fr, intro_en, phase, tools, payload_fr, payload_en) VALUES (5, 'Ops en code — DAG & jobs', 'Ops en code — DAG & jobs', 'Le pipeline tourne : Airflow + jobs Python/SQL.', 'Le pipeline tourne : Airflow + jobs Python/SQL.', 'ops', ARRAY['airflow', 'python', 'sql']::text[], '{"id":5,"title":"Ops en code — DAG & jobs","intro":"Le pipeline tourne : Airflow + jobs Python/SQL.","brief":{"projectName":"Mutualis — orchestration scriptée","context":"Chaque matin : sensor landing → transform SQL/Python → publication. Tu codes l’ops.","problem":"Sans sensor ni retries, un CSV en retard fait rater le COMEX.","objectives":["Écrire un squelette DAG Airflow en Python.","Esquisser la task de transform (SQL ou pandas).","Documenter le runbook en commentaires de code."],"consigne":"Livrables = scripts. Les outils hors code restent secondaires."},"phase":"ops","tools":["airflow","python","sql"],"steps":[{"id":"l5-af","title":"Python — squelette DAG Airflow","say":"Le CSV capteur arrive en landing chaque matin. Esquisse le DAG : sensor → transform → notify.","do":"Colle un squelette Python DAG (with DAG / tasks chaînées).","how":["schedule_interval / timetable matin","FileSensor path …/dt={{ ds }}/capteur_a_retail.csv","retries = 2"],"trap":"Le path du FileSensor doit coller au fichier landing (dt={{ ds }}) — un typo = DAG stuck.","expect":"python","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"validate":{"minLength":40,"keywords":["dag","sensor","schedule","retry","task","op_","python"],"keywordMin":2},"feedbackPass":"Ops industrialisée en code.","feedbackFail":"Montre DAG + sensor → traitement (+ schedule / retries).","correction":"```python\nfrom airflow import DAG\nfrom airflow.sensors.filesystem import FileSensor\nfrom airflow.operators.bash import BashOperator\nwith DAG(\"mutualis_capteur\", schedule=\"0 6 * * *\", catchup=False) as dag:\n    sensor = FileSensor(task_id=\"wait_landing\", filepath=\"/landing/capteur/dt={{ ds }}/capteur_a_retail.csv\", retries=2)\n    transform = BashOperator(task_id=\"transform\", bash_command=\"python transform_capteur.py {{ ds }}\")\n    sensor >> transform\n```","tool":"airflow","phase":"ops"},{"id":"l5-transform","title":"SQL/Python — task de transform","say":"La task appelée par le DAG : filtre jours sous seuil (SQL) OU pandas équivalent.","do":"Colle le script SQL ou Python que la task exécute.","how":["SQL : WHERE visiteurs_count < threshold_twenty_pct","ou pandas : df.query(...) puis to_csv / to_gbq"],"trap":"Une task sans argument de date (ds) recharge toujours « aujourd’hui » et casse le rejeu.","expect":"sql","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"validate":{"minLength":35,"keywords":["select","where","threshold","visiteur","read_csv","query","to_csv"],"keywordMin":2},"feedbackPass":"Transform versionnable — le cœur du DAG.","feedbackFail":"Colle le filtre seuil en SQL ou le pipeline pandas.","correction":"```sql\nSELECT *\nFROM capteur_a_retail\nWHERE visiteurs_count < threshold_twenty_pct\n  AND date = DATE ''{{ ds }}'';\n```\nou équivalent pandas avec sys.argv / ds.","tool":"sql","phase":"ops"},{"id":"l5-cap","title":"Python — runbook pipeline en docstring","say":"Synthèse exécutable : un module Python dont la docstring décrit les 6 étapes du pipeline Mutualis (avec datasets).","do":"Colle un fichier .py avec docstring + éventuellement une fonction main() qui liste les étapes.","how":["Docstring : discovery → qualité SQL → ETL Python → dbt → KPI SQL → Airflow","Cite retail_employees, capteur, weights, ventes…"],"trap":"Une liste d’outils sans scripts associés n’est pas un runbook ops.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":80,"keywords":["sql","python","dbt","airflow","def","\"\"\"","''''''","pipeline","landing"],"keywordMin":3},"feedbackPass":"Vision bout-en-bout ancrée dans le code.","feedbackFail":"Docstring / script citant au moins SQL, Python, dbt ou Airflow.","correction":"```python\n\"\"\"Pipeline Mutualis\n1. Discovery pandas retail_employees\n2. Qualité SQL doublons CRM\n3. ETL Python ventes×clients\n4. dbt stg→mart\n5. KPI SQL intensité CA\n6. Airflow sensor capteur\n\"\"\"\ndef main():\n    steps = [\"sql\", \"python\", \"dbt\", \"airflow\"]\n    print(\" → \".join(steps))\n\nif __name__ == \"__main__\":\n    main()\n```","tool":"python","phase":"ops"}]}'::jsonb, '{"id":5,"title":"Ops en code — DAG & jobs","intro":"Le pipeline tourne : Airflow + jobs Python/SQL.","brief":{"projectName":"Mutualis — orchestration scriptée","context":"Chaque matin : sensor landing → transform SQL/Python → publication. Tu codes l’ops.","problem":"Sans sensor ni retries, un CSV en retard fait rater le COMEX.","objectives":["Écrire un squelette DAG Airflow en Python.","Esquisser la task de transform (SQL ou pandas).","Documenter le runbook en commentaires de code."],"consigne":"Livrables = scripts. Les outils hors code restent secondaires."},"phase":"ops","tools":["airflow","python","sql"],"steps":[{"id":"l5-af","title":"Python — squelette DAG Airflow","say":"Le CSV capteur arrive en landing chaque matin. Esquisse le DAG : sensor → transform → notify.","do":"Colle un squelette Python DAG (with DAG / tasks chaînées).","how":["schedule_interval / timetable matin","FileSensor path …/dt={{ ds }}/capteur_a_retail.csv","retries = 2"],"trap":"Le path du FileSensor doit coller au fichier landing (dt={{ ds }}) — un typo = DAG stuck.","expect":"python","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"validate":{"minLength":40,"keywords":["dag","sensor","schedule","retry","task","op_","python"],"keywordMin":2},"feedbackPass":"Ops industrialisée en code.","feedbackFail":"Montre DAG + sensor → traitement (+ schedule / retries).","correction":"```python\nfrom airflow import DAG\nfrom airflow.sensors.filesystem import FileSensor\nfrom airflow.operators.bash import BashOperator\nwith DAG(\"mutualis_capteur\", schedule=\"0 6 * * *\", catchup=False) as dag:\n    sensor = FileSensor(task_id=\"wait_landing\", filepath=\"/landing/capteur/dt={{ ds }}/capteur_a_retail.csv\", retries=2)\n    transform = BashOperator(task_id=\"transform\", bash_command=\"python transform_capteur.py {{ ds }}\")\n    sensor >> transform\n```","tool":"airflow","phase":"ops"},{"id":"l5-transform","title":"SQL/Python — task de transform","say":"La task appelée par le DAG : filtre jours sous seuil (SQL) OU pandas équivalent.","do":"Colle le script SQL ou Python que la task exécute.","how":["SQL : WHERE visiteurs_count < threshold_twenty_pct","ou pandas : df.query(...) puis to_csv / to_gbq"],"trap":"Une task sans argument de date (ds) recharge toujours « aujourd’hui » et casse le rejeu.","expect":"sql","dataset":{"href":"/data-game/capteur_a_retail.csv","label":"capteur_a_retail.csv","hint":"Fréquentation capteur porte A — module SQL.","source":"SQL"},"validate":{"minLength":35,"keywords":["select","where","threshold","visiteur","read_csv","query","to_csv"],"keywordMin":2},"feedbackPass":"Transform versionnable — le cœur du DAG.","feedbackFail":"Colle le filtre seuil en SQL ou le pipeline pandas.","correction":"```sql\nSELECT *\nFROM capteur_a_retail\nWHERE visiteurs_count < threshold_twenty_pct\n  AND date = DATE ''{{ ds }}'';\n```\nou équivalent pandas avec sys.argv / ds.","tool":"sql","phase":"ops"},{"id":"l5-cap","title":"Python — runbook pipeline en docstring","say":"Synthèse exécutable : un module Python dont la docstring décrit les 6 étapes du pipeline Mutualis (avec datasets).","do":"Colle un fichier .py avec docstring + éventuellement une fonction main() qui liste les étapes.","how":["Docstring : discovery → qualité SQL → ETL Python → dbt → KPI SQL → Airflow","Cite retail_employees, capteur, weights, ventes…"],"trap":"Une liste d’outils sans scripts associés n’est pas un runbook ops.","expect":"python","dataset":{"href":"/data-game/retail_employees.csv","label":"retail_employees.csv","hint":"Employés retail (SCD-like) — module Spark.","source":"Spark"},"validate":{"minLength":80,"keywords":["sql","python","dbt","airflow","def","\"\"\"","''''''","pipeline","landing"],"keywordMin":3},"feedbackPass":"Vision bout-en-bout ancrée dans le code.","feedbackFail":"Docstring / script citant au moins SQL, Python, dbt ou Airflow.","correction":"```python\n\"\"\"Pipeline Mutualis\n1. Discovery pandas retail_employees\n2. Qualité SQL doublons CRM\n3. ETL Python ventes×clients\n4. dbt stg→mart\n5. KPI SQL intensité CA\n6. Airflow sensor capteur\n\"\"\"\ndef main():\n    steps = [\"sql\", \"python\", \"dbt\", \"airflow\"]\n    print(\" → \".join(steps))\n\nif __name__ == \"__main__\":\n    main()\n```","tool":"python","phase":"ops"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_fr=EXCLUDED.title_fr, intro_fr=EXCLUDED.intro_fr, phase=EXCLUDED.phase, tools=EXCLUDED.tools, payload_fr=EXCLUDED.payload_fr, payload_en=EXCLUDED.payload_en;
INSERT INTO adventure_steps (id, level_id, sort_order, title_fr, title_en, say_fr, say_en, do_fr, do_en, expect_type, correction_fr, correction_en, keywords, tool_id, phase, payload_fr, payload_en) VALUES ('l5-af', 5, 0, 'Python — squelette DAG Airflow', 'Python — squelette DAG Airflow', 'Le CSV capteur arrive en landing chaque matin. Esquisse le DAG : sensor → transform → notify.', 'Le CSV capteur arrive en landing chaque matin. Esquisse le DAG : sensor → transform → notify.', 'Colle un squelette Python DAG (with DAG / tasks chaînées).', 'Colle un squelette Python DAG (with DAG / tasks chaînées).', 'python', '```python
INSERT INTO adventure_steps (id, level_id, sort_order, title_fr, title_en, say_fr, say_en, do_fr, do_en, expect_type, correction_fr, correction_en, keywords, tool_id, phase, payload_fr, payload_en) VALUES ('l5-transform', 5, 1, 'SQL/Python — task de transform', 'SQL/Python — task de transform', 'La task appelée par le DAG : filtre jours sous seuil (SQL) OU pandas équivalent.', 'La task appelée par le DAG : filtre jours sous seuil (SQL) OU pandas équivalent.', 'Colle le script SQL ou Python que la task exécute.', 'Colle le script SQL ou Python que la task exécute.', 'sql', '```sql
INSERT INTO adventure_steps (id, level_id, sort_order, title_fr, title_en, say_fr, say_en, do_fr, do_en, expect_type, correction_fr, correction_en, keywords, tool_id, phase, payload_fr, payload_en) VALUES ('l5-cap', 5, 2, 'Python — runbook pipeline en docstring', 'Python — runbook pipeline en docstring', 'Synthèse exécutable : un module Python dont la docstring décrit les 6 étapes du pipeline Mutualis (avec datasets).', 'Synthèse exécutable : un module Python dont la docstring décrit les 6 étapes du pipeline Mutualis (avec datasets).', 'Colle un fichier .py avec docstring + éventuellement une fonction main() qui liste les étapes.', 'Colle un fichier .py avec docstring + éventuellement une fonction main() qui liste les étapes.', 'python', '```python
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l0-open', 'fr', 0, '{"frameworkRef":"Gestion de projet — Focus on value · Scrum — empiricism / Sprint Goal","scenarioTwist":"Kick-off Mutualis : le sponsor avance la date COMEX de 2 semaines. L’équipe data n’a pas encore ouvert les CSV.","link":"Phase discovery / initiation : sans comprendre les sources, tout planning est du théâtre.","question":"En tant que PM, quel premier geste est le plus aligné « focus on value » + empirisme ?","options":["Verrouiller un Gantt de 40 tâches avant d’ouvrir un fichier","Lancer une discovery courte des sources (schéma) pour éclairer le backlog et le risque","Attendre que l’architecture cloud soit signée à 100 %"],"correctIndex":1,"correction":"La valeur commence par réduire l’incertitude utile. Une discovery source (transparent inspection) éclaire le Product Backlog et le plan. Un Gantt figé avant les données = anti-pattern gestion de projet / agile."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l0-filter', 'fr', 0, '{"frameworkRef":"Scrum — Definition of Done / AC · Gestion de projet — Quality","link":"Après le schéma, le filtre métier « actifs » est une Definition of Done / critère d’acceptation en devenir.","question":"Comment formuler ce filtre pour qu’il soit testable en revue (Scrum / qualité projet) ?","options":["« Que ça marche » sans métrique","Critère mesurable : effectif = COUNT active_record=1 (±0 vs extract de référence)","Reporter la règle au Sprint suivant sans l’écrire"],"correctIndex":1,"correction":"Done et qualité exigent des critères vérifiables. Un AC chiffré permet d’accepter/refuser l’Increment ; « ça marche » n’est pas inspectable."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l0-sql', 'fr', 0, '{"frameworkRef":"Scrum — Product Owner / Backlog · agile à l’échelle — WSJF / capacity · Gestion de projet — Change","scenarioTwist":"Le PO RH demande le même KPI en SQL « pour la DSI » alors que l’équipe avait prévu uniquement pandas.","link":"Changement de besoin mid-stream : adapter le backlog sans perdre le Product Goal.","question":"Quelle réponse PM est la plus saine ?","options":["Dire non par principe (outil déjà choisi)","Clarifier le Product Goal, estimer l’impact, prioriser une story SQL dans le backlog","Promettre les deux pour vendredi sans capacity check"],"correctIndex":1,"correction":"Le changement est normal. On l’accueille via le backlog (transparence), on évalue coût/risque (changement projet / capacité multi-équipes), on protège le Goal. Promesse sans capacité = dette et échec de Sprint."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l1-dupes', 'fr', 0, '{"frameworkRef":"agile à l’échelle — ROAM · Gestion de projet — Risk responses · Scrum — impediment","link":"Qualité CRM = risque projet (scope, réputation, COMEX). Le PM doit ROAM / escalader.","question":"Les doublons email menacent le KPI clients uniques. Meilleure posture PM ?","options":["Ignorer : « on nettoiera en prod »","Élever en risque (Owned), définir mitigation (règle MDM) et impact sur le Sprint Goal","Demander à chaque analyste de dédupliquer dans son Excel perso"],"correctIndex":1,"correction":"Un défaut qualité systémique est un risque/impediment. ROAM (Owned) + mitigation explicite protège la valeur. Le shadow Excel multiplie les vérités."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l1-join', 'fr', 0, '{"frameworkRef":"Gestion de projet — Stakeholder / Integration · Scrum — clarification PO · gouvernance data alignment","scenarioTwist":"Finance annonce que « livree » changera de sens la semaine prochaine (nouveau statut WMS).","link":"Dépendance métier / définition KPI : intégration et gestion des interfaces.","question":"Que fais-tu immédiatement en tant que PM ?","options":["Continuer le JOIN actuel et « on verra »","Bloquer/clarifier la définition avec Owner Finance, mettre à jour AC et risque de régression","Dupliquer deux KPI secrets pour contenter tout le monde"],"correctIndex":1,"correction":"Changement de définition = impact scope/qualité. Clarifier avec l’Accountable, mettre à jour AC et communiquer. Deux KPI homonymes = chaos (anti-pattern BI + DG)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l1-py-clean', 'fr', 0, '{"frameworkRef":"agile à l’échelle — Enablers · Scrum — Backlog transparency · Gestion de projet — Tailoring","link":"Industrialiser une règle = enabler technique + gouvernance du changement.","question":"Comment prioriser ce nettoyage dans un ART / équipe Scrum ?","options":["Le laisser en « dette invisible » hors backlog","Enabler / story technique liée à un bénéfice (fiabilité CRM) et capacity allouée","Le faire uniquement le week-end hors process"],"correctIndex":1,"correction":"Les enablers ont de la valeur (réduire le risque qualité). Ils doivent être visibles, estimés et planifiés — pas de shadow work."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-sql', 'fr', 0, '{"frameworkRef":"Scrum — Increment · Gestion de projet — Incremental delivery · agile à l’échelle — MVP","link":"Ingestion analytique : livrer un Increment utile (agrégat) plutôt qu’un monolithe.","question":"Quelle découpe de livraison est la plus agile / Gestion de projet value-driven ?","options":["Attendre le data lake complet avant tout SELECT","Livrer d’abord un agrégat commune inspectable, puis itérer","Ouvrir 12 chantiers parallèles sans Sprint Goal"],"correctIndex":1,"correction":"Un Increment inspectable (même petit) crée du feedback. Attendre le monolithe retarde l’apprentissage ; trop de WIP détruit le focus."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-capteur', 'fr', 0, '{"frameworkRef":"Scrum — Sprint Goal protection · agile à l’échelle — MVP · Gestion de projet — Negotiate","scenarioTwist":"Ops magasin escalade : 2 jours sous seuil non détectés — le COMEX veut un « alert SLA » dès demain.","link":"Passage discovery → ops control : urgence vs capacité.","question":"Comment arbitrer l’urgence COMEX ?","options":["Tout stopper et coder 48h non-stop sans DoD","Négocier un MVP alerte (filtre SQL + canal) + AC/SLA, protéger le reste du Goal","Promettre un SI temps réel complet pour demain matin"],"correctIndex":1,"correction":"Le PM négocie un Increment minimal viable avec AC clairs, sans sacrifier la qualité ni promettre l’impossible. Le Sprint Goal se protège, il ne s’efface pas."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-foot', 'fr', 0, '{"frameworkRef":"Scrum — DoR/DoD · Gestion de projet — Requirements quality","link":"Exercice « sport » = même pattern mart KPI : formaliser la règle métier.","question":"Pourquoi le PM insiste-t-il sur une règle FTR=H écrite ?","options":["Pour faire joli dans Confluence","Pour des AC testables et une Definition of Ready/Done partagée","Parce que le coach Agile l’a exigé sans raison"],"correctIndex":1,"correction":"Sans règle écrite, l’équipe ne peut pas livrer un Increment « Done » cohérent. DoR/DoD et exigences testables réduisent le rework."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-window', 'fr', 0, '{"frameworkRef":"Scrum — one Product Goal clarity · Gestion de projet — Stakeholder engagement · agile à l’échelle — alignment","scenarioTwist":"Deux directions veulent le même nom de KPI mais des grains différents (créneau vs jour).","link":"Conflit stakeholders / Product Goal uniqueness.","question":"Meilleure facilitation PM ?","options":["Choisir au hasard et cacher le grain","Séparer en deux indicateurs nommés, faire trancher l’Owner, documenter","Livrer un seul KPI ambigu pour « calmer » le comité"],"correctIndex":1,"correction":"Un nom, une définition. Le PM facilite l’arbitrage Owner et évite les indicateurs fourre-tout qui détruisent la confiance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-json', 'fr', 0, '{"frameworkRef":"Gestion de projet — Integration / Risk · agile à l’échelle — Architectural Runway · Scrum — backlog item","link":"Nouvelle source IoT = intégration : contrats, risques, architecture émergente.","question":"Avant de parser le JSON en prod, que sécurises-tu en PM ?","options":["Rien : « on parse et on verra »","Owner du schéma, risques breaking change, place dans le PI/Sprint backlog","Uniquement le logo du vendor dans la slide deck"],"correctIndex":1,"correction":"Toute nouvelle interface est un risque d’intégration. Owner + runway + item de backlog = delivery contrôlée."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-py', 'fr', 0, '{"frameworkRef":"Gestion de projet — Compliance · Scrum — DoD · agile à l’échelle — Guardrails","scenarioTwist":"RGPD : la DPO demande la finalité et la rétention du fichier employés actifs avant le prochain Increment.","link":"Compliance = contrainte projet, pas option.","question":"Comment intègres-tu la demande DPO sans casser le flux ?","options":["Ignorer jusqu’à l’audit","Ajouter des AC compliance (finalité/rétention) et bloquer Done tant que non satisfaits","Publier les PII en self-service pour « transparence »"],"correctIndex":1,"correction":"La compliance entre dans le DoD / AC. Livrer sans finalité/rétention = risque légal et échec de stewardship."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-py-merge', 'fr', 0, '{"frameworkRef":"agile à l’échelle — PO Sync / alignment · Scrum — PO · Gestion de projet — Conflict management","link":"Produit data Finance×CRM : dépendances cross-équipe.","question":"Finance et CRM divergent sur « livree ». Rôle du PM / RTE / PO ?","options":["Laisser chaque équipe livrer sa vérité","Faciliter un arbitrage Accountable, mettre à jour le backlog commun","Coder les deux JOIN en silence"],"correctIndex":1,"correction":"L’alignement cross-domaine est le job du système de delivery (PO/RTE/PM). Deux vérités = échec d’intégration."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-dbt', 'fr', 0, '{"frameworkRef":"Scrum — DoD · agile à l’échelle — Built-in Quality · Gestion de projet — Quality","link":"Transformation industrialisée : qualité dans la Definition of Done.","question":"Où place-t-on les tests unique du golden record dans le DoD data ?","options":["Nulle part — « dbt suffit comme process »","Sur le mart (règle appliquée), exigés pour Done de l’Increment","Uniquement sur des slides de gouvernance"],"correctIndex":1,"correction":"Built-in quality : les tests font partie de Done. Sur le mart, ils protègent le golden record."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l4-kpi-sql', 'fr', 0, '{"frameworkRef":"Gestion de projet — Focus on value · agile à l’échelle — sequencing · Scrum — Goal","scenarioTwist":"Le sponsor veut « une belle carte Power BI demain » alors que la requête KPI de référence n’existe pas.","link":"Exposition vs vérité : ordre de livraison value-driven.","question":"Que priorises-tu ?","options":["La carte d’abord, la définition SQL « plus tard »","La requête / définition KPI d’abord, puis la viz alignée","Les deux en parallèle sans Owner"],"correctIndex":1,"correction":"Sans définition exécutable, la viz n’a pas de valeur fiable. Séquencer vérité → exposition évite le théâtre COMEX."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l4-grain', 'fr', 0, '{"frameworkRef":"Gestion de projet — Issue mgmt · agile à l’échelle — Inspect & Adapt · Scrum — adaptation","link":"Incident qualité grain = gestion d’issue / risque réalisé.","question":"Dashboard qui multiplie les faits (mauvais grain). Action PM ?","options":["Minimiser auprès du sponsor","Incident qualité : retirer/corriger, post-mortem, AC grain mis à jour","Ajouter un filtre cosmétique et fermer le ticket"],"correctIndex":1,"correction":"Un défaut de grain est un issue qualité. Transparence, correction, apprentissage (I&A) — pas de cosmétiques."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l4-pbi', 'fr', 0, '{"frameworkRef":"Scrum — Sprint Review / acceptance · Gestion de projet — Validate scope","link":"Certification BI = acceptance de l’Increment analytique.","question":"Quand acceptes-tu la carte Power BI en revue ?","options":["Dès que le visuel est joli","Quand elle réconcilie avec la requête SQL de référence sous Owner","Quand personne n’a levé la main en réunion"],"correctIndex":1,"correction":"L’acceptance se base sur des AC/DoD (réconciliation), pas sur l’esthétique ni le silence."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l5-af', 'fr', 0, '{"frameworkRef":"agile à l’échelle — Flow / Impediment · Scrum — SM removes impediments · Gestion de projet — Ops handover","scenarioTwist":"Le FileSensor timeout trois matins de suite : le COMEX n’a pas eu le mart à 7h.","link":"Ops / Run : fiabilité = valeur continue (flow).","question":"Réponse PM / RTE la plus adaptée ?","options":["Blâmer l’équipe data en public","Traiter comme impediment système : SLA, retries, escalade runbook, capacity pour fiabiliser","Désactiver le DAG pour « éviter le bruit »"],"correctIndex":1,"correction":"La fiabilité du pipeline est un objectif de flow. On traite la cause (SLA, sensor, escalade), on alloue de la capacity — on ne coupe pas le signal."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l5-transform', 'fr', 0, '{"frameworkRef":"Gestion de projet — Adaptability & resilience · agile à l’échelle — Built-in Quality","link":"Rejeu par date = auditabilité et résilience (adaptability).","question":"Pourquoi le PM exige-t-il le paramètre {{ ds }} sur la task ?","options":["Pour décorer Airflow","Pour permettre rejeu, audit et recovery — résilience du système de delivery","Pour éviter d’écrire des AC"],"correctIndex":1,"correction":"Un système non rejouable n’est pas résilient. ds rend l’ops auditable et récupérable — exigence de qualité système."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l5-cap', 'fr', 0, '{"frameworkRef":"agile à l’échelle — System Demo / I&A · Gestion de projet — Stewardship · Scrum — accountability","link":"Clôture de lot / I&A : RACI et apprentissages.","question":"Pour le mart employés actifs, quel RACI présentes-tu en System Demo / Review ?","options":["Personne accountable","Responsible = data engineer ; Accountable = Data Owner RH","Accountable = l’outil Airflow"],"correctIndex":1,"correction":"Les rôles restent humains. Accountable Owner + Responsible delivery = gouvernance et delivery alignées."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l0-open', 'en', 0, '{"frameworkRef":"Project management — Focus on value · Scrum — empiricism / Sprint Goal","scenarioTwist":"Mutualis kick-off: the sponsor pulls the board date forward by 2 weeks. The data team has not opened the CSVs yet.","link":"Discovery / initiation phase: without understanding sources, any plan is theater.","question":"As PM, which first move best aligns “focus on value” + empiricism?","options":["Lock a 40-task Gantt before opening a file","Run a short source discovery (schema) to illuminate backlog and risk","Wait until cloud architecture is 100% signed off"],"correctIndex":1,"correction":"Value starts by reducing useful uncertainty. Source discovery (transparent inspection) illuminates the Product Backlog and the plan. A frozen Gantt before data = project management/Agile anti-pattern."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l0-filter', 'en', 0, '{"frameworkRef":"Scrum — Definition of Done / AC · Project management — Quality","link":"After the schema, the “active” business filter becomes a Definition of Done / acceptance criterion in the making.","question":"How do you phrase this filter so it is testable in review (Scrum / project management quality)?","options":["“Make it work” with no metric","Measurable criterion: headcount = COUNT active_record=1 (±0 vs reference extract)","Defer the rule to the next Sprint without writing it"],"correctIndex":1,"correction":"Done and quality require verifiable criteria. A quantified AC lets you accept/reject the Increment; “it works” is not inspectable."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l0-sql', 'en', 0, '{"frameworkRef":"Scrum — Product Owner / Backlog · scaled agile — WSJF / capacity · Project management — Change","scenarioTwist":"The HR PO asks for the same KPI in SQL “for IT” while the team had planned pandas only.","link":"Mid-stream need change: adapt the backlog without losing the Product Goal.","question":"Which PM response is healthiest?","options":["Say no on principle (tool already chosen)","Clarify the Product Goal, estimate impact, prioritize a SQL story in the backlog","Promise both by Friday with no capacity check"],"correctIndex":1,"correction":"Change is normal. Welcome it via the backlog (transparency), assess cost/risk (project management change / scaled agile capacity), protect the Goal. Promise without capacity = debt and Sprint failure."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l1-dupes', 'en', 0, '{"frameworkRef":"scaled agile — ROAM · Project management — Risk responses · Scrum — impediment","link":"CRM quality = project risk (scope, reputation, board). The PM must ROAM / escalate.","question":"Email duplicates threaten the unique-customers KPI. Best PM stance?","options":["Ignore: “we’ll clean in prod”","Raise as risk (Owned), define mitigation (MDM rule) and Sprint Goal impact","Ask each analyst to dedupe in their personal spreadsheet"],"correctIndex":1,"correction":"A systemic quality defect is a risk/impediment. ROAM (Owned) + explicit mitigation protects value. Shadow Excel multiplies truths."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l1-join', 'en', 0, '{"frameworkRef":"Project management — Stakeholder / Integration · Scrum — clarification PO · data governance alignment","scenarioTwist":"Finance announces that “delivered” will change meaning next week (new WMS status).","link":"Business dependency / KPI definition: integration and interface management.","question":"What do you do immediately as PM?","options":["Keep the current JOIN and “we’ll see”","Block/clarify the definition with Finance Owner; update AC and regression risk","Duplicate two secret KPIs to please everyone"],"correctIndex":1,"correction":"Definition change = scope/quality impact. Clarify with the Accountable, update AC, communicate. Two same-named KPIs = chaos (BI + DG anti-pattern)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l1-py-clean', 'en', 0, '{"frameworkRef":"scaled agile — Enablers · Scrum — Backlog transparency · Project management — Tailoring","link":"Industrializing a rule = technical enabler + change governance.","question":"How do you prioritize this cleanup in an ART / Scrum team?","options":["Leave it as “invisible debt” outside the backlog","Enabler / technical story tied to a benefit (CRM reliability) with allocated capacity","Do it only on weekends outside process"],"correctIndex":1,"correction":"Enablers have value (reduce quality risk). They must be visible, estimated, and planned — no shadow work."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-sql', 'en', 0, '{"frameworkRef":"Scrum — Increment · Project management — Incremental delivery · scaled agile — MVP","link":"Analytical ingestion: deliver a useful Increment (aggregate) rather than a monolith.","question":"Which delivery slice is most agile / Project management value-driven?","options":["Wait for the full data lake before any SELECT","Deliver an inspectable commune aggregate first, then iterate","Open 12 parallel workstreams with no Sprint Goal"],"correctIndex":1,"correction":"An inspectable Increment (even small) creates feedback. Waiting for the monolith delays learning; too much WIP destroys focus."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-capteur', 'en', 0, '{"frameworkRef":"Scrum — Sprint Goal protection · scaled agile — MVP · Project management — Negotiate","scenarioTwist":"Store Ops escalates: 2 days under threshold undetected — the board wants an “alert SLA” by tomorrow.","link":"Discovery → ops control: urgency vs capacity.","question":"How do you arbitrate the board urgency?","options":["Stop everything and code 48h non-stop with no DoD","Negotiate an alert MVP (SQL filter + channel) + AC/SLA; protect the rest of the Goal","Promise a full real-time IS for tomorrow morning"],"correctIndex":1,"correction":"The PM negotiates a minimal viable Increment with clear AC, without sacrificing quality or promising the impossible. The Sprint Goal is protected, not erased."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-foot', 'en', 0, '{"frameworkRef":"Scrum — DoR/DoD · Project management — Requirements quality","link":"“Sport” exercise = same mart KPI pattern: formalize the business rule.","question":"Why does the PM insist on a written FTR=H rule?","options":["To look nice in Confluence","For testable AC and a shared Definition of Ready/Done","Because the Agile coach demanded it for no reason"],"correctIndex":1,"correction":"Without a written rule, the team cannot deliver a coherent “Done” Increment. DoR/DoD and testable requirements reduce rework."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l2-window', 'en', 0, '{"frameworkRef":"Scrum — one Product Goal clarity · Project management — Stakeholder engagement · scaled agile — alignment","scenarioTwist":"Two departments want the same KPI name but different grains (slot vs day).","link":"Stakeholder conflict / Product Goal uniqueness.","question":"Best PM facilitation?","options":["Pick at random and hide the grain","Split into two named indicators; have Owner decide; document","Ship one ambiguous KPI to “calm” the committee"],"correctIndex":1,"correction":"One name, one definition. The PM facilitates Owner arbitration and avoids catch-all indicators that destroy trust."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-json', 'en', 0, '{"frameworkRef":"Project management — Integration / Risk · scaled agile — Architectural Runway · Scrum — backlog item","link":"New IoT source = integration: contracts, risks, emerging architecture.","question":"Before parsing JSON in prod, what do you secure as PM?","options":["Nothing: “parse and see”","Schema Owner, breaking-change risks, place in the PI/Sprint backlog","Only the vendor logo in the slide deck"],"correctIndex":1,"correction":"Every new interface is an integration risk. Owner + runway + backlog item = controlled delivery."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-py', 'en', 0, '{"frameworkRef":"Project management — Compliance · Scrum — DoD · scaled agile — Guardrails","scenarioTwist":"GDPR: the DPO asks for purpose and retention of the active-employees file before the next Increment.","link":"Compliance = project constraint, not optional.","question":"How do you integrate the DPO request without breaking flow?","options":["Ignore until the audit","Add compliance AC (purpose/retention) and block Done until satisfied","Publish PII in self-service for “transparency”"],"correctIndex":1,"correction":"Compliance enters the DoD / AC. Shipping without purpose/retention = legal risk and stewardship failure."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-py-merge', 'en', 0, '{"frameworkRef":"scaled agile — PO Sync / alignment · Scrum — PO · Project management — Conflict management","link":"Finance×CRM data product: cross-team dependencies.","question":"Finance and CRM diverge on “delivered”. Role of PM / RTE / PO?","options":["Let each team ship its own truth","Facilitate Accountable arbitration; update the shared backlog","Code both JOINs in silence"],"correctIndex":1,"correction":"Cross-domain alignment is the delivery system’s job (PO/RTE/PM). Two truths = integration failure."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l3-dbt', 'en', 0, '{"frameworkRef":"Scrum — DoD · scaled agile — Built-in Quality · Project management — Quality","link":"Industrialized transformation: quality in the Definition of Done.","question":"Where do golden-record uniqueness tests belong in the data DoD?","options":["Nowhere — “dbt is enough as process”","On the mart (applied rule), required for Increment Done","Only on governance slides"],"correctIndex":1,"correction":"Built-in quality: tests are part of Done. On the mart, they protect the golden record."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l4-kpi-sql', 'en', 0, '{"frameworkRef":"Project management — Focus on value · scaled agile — sequencing · Scrum — Goal","scenarioTwist":"The sponsor wants “a nice Power BI map tomorrow” while the reference KPI query does not exist.","link":"Exposition vs truth: value-driven delivery order.","question":"What do you prioritize?","options":["The map first, the SQL definition “later”","The query / KPI definition first, then aligned viz","Both in parallel with no Owner"],"correctIndex":1,"correction":"Without an executable definition, viz has no reliable value. Sequencing truth → exposition avoids board theater."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l4-grain', 'en', 0, '{"frameworkRef":"Project management — Issue mgmt · scaled agile — Inspect & Adapt · Scrum — adaptation","link":"Grain quality incident = issue / realized risk management.","question":"Dashboard that multiplies facts (wrong grain). PM action?","options":["Downplay it to the sponsor","Quality incident: withdraw/fix, post-mortem, update grain AC","Add a cosmetic filter and close the ticket"],"correctIndex":1,"correction":"A grain defect is a quality issue. Transparency, fix, learning (I&A) — no cosmetics."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l4-pbi', 'en', 0, '{"frameworkRef":"Scrum — Sprint Review / acceptance · Project management — Validate scope","link":"BI certification = analytical Increment acceptance.","question":"When do you accept the Power BI map in review?","options":["As soon as the visual looks nice","When it reconciles with the reference SQL query under Owner","When nobody raised a hand in the meeting"],"correctIndex":1,"correction":"Acceptance is based on AC/DoD (reconciliation), not aesthetics or silence."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l5-af', 'en', 0, '{"frameworkRef":"scaled agile — Flow / Impediment · Scrum — SM removes impediments · Project management — Ops handover","scenarioTwist":"FileSensor timeout three mornings in a row: the board did not get the mart at 7am.","link":"Ops / Run: reliability = continuous value (flow).","question":"Most appropriate PM / RTE response?","options":["Blame the data team in public","Treat as system impediment: SLA, retries, runbook escalation, capacity to harden","Disable the DAG to “avoid noise”"],"correctIndex":1,"correction":"Pipeline reliability is a flow objective. Treat the cause (SLA, sensor, escalation), allocate capacity — do not cut the signal."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l5-transform', 'en', 0, '{"frameworkRef":"Project management — Adaptability & resilience · scaled agile — Built-in Quality","link":"Date replay = auditability and resilience (adaptability).","question":"Why does the PM require the {{ ds }} parameter on the task?","options":["To decorate Airflow","To enable replay, audit and recovery — delivery-system resilience","To avoid writing AC"],"correctIndex":1,"correction":"A non-replayable system is not resilient. ds makes ops auditable and recoverable — a system quality requirement."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_curated', 'l5-cap', 'en', 0, '{"frameworkRef":"scaled agile — System Demo / I&A · Project management — Stewardship · Scrum — accountability","link":"Lot closure / I&A: RACI and learnings.","question":"For the active-employees mart, which RACI do you present in System Demo / Review?","options":["Nobody accountable","Responsible = data engineer; Accountable = HR Data Owner","Accountable = the Airflow tool"],"correctIndex":1,"correction":"Roles stay human. Accountable Owner + Responsible delivery = aligned governance and delivery."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l0-open', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.3 Data Governance · Ch.12 Metadata","link":"Inspecter le schéma, c’est poser le catalogue technique : sans colonnes documentées, pas de steward ni de glossaire fiables.","question":"Après discovery de retail_employees, quel couple Owner / artefact est le plus aligné avec la gouvernance data ?","options":["IT Support = Owner ; aucun artefact (le CSV suffit)","DRH / Ops RH = Data Owner ; mise à jour catalogue + glossaire « salarié actif »","Le stagiaire data = Owner unique ; fiche Excel personnelle non partagée"],"correctIndex":1,"correction":"En gouvernance data, le Data Owner est accountable métier (ici RH/ops retail), pas « celui qui a le fichier ». Le Steward opérationnalise qualité/métadonnées. Après discovery, on enrichit métadonnées business + techniques (catalogue/glossaire) — Ch.12 Metadata Management."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l0-filter', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.13 Data Quality · Ch.3 Data Governance","link":"Le filtre active_record = 1 matérialise une règle métier de qualité : la gouvernance doit la figer comme définition d’« effectif actif ».","question":"Où doit vivre en priorité la règle « employé actif = active_record = 1 » ?","options":["Uniquement dans la tête de l’analyste qui filtre Excel","Comme règle de qualité / définition gouvernée, testée (script ou dbt) sur le mart","Uniquement dans un slide PowerPoint du dernier COMEX"],"correctIndex":1,"correction":"gouvernance data (Data Quality) : les règles de qualité sont définies, mesurées et contrôlées — pas improvisées. Lier la règle à une définition métier gouvernée (DG) et la faire exécuter (tests) évite les KPI divergents."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l0-sql', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.13 Data Quality · Ch.12 Metadata","link":"La même définition métier doit produire le même résultat en SQL et en Python — cohérence sémantique des définitions.","question":"Comment la gouvernance data recommande-t-elle de garantir SQL COUNT ≈ pandas value_counts ?","options":["Faire confiance au feeling si les ordres de grandeur se ressemblent","Réconciliation / contrôle qualité documenté (gold set, assert, test CI) sur la même définition","Changer la définition SQL jusqu’à ce que le dashboard soit « joli »"],"correctIndex":1,"correction":"La qualité « fitness for purpose » implique des contrôles de cohérence entre pipelines. Une réconciliation chiffrée + métadonnée de définition partagée (glossaire/KPI) est le bon réflexe de gouvernance ; l’écart devient un incident qualité, pas un ajustement cosmétique."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l1-dupes', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.10 Reference & Master Data","link":"Les doublons email sont un défaut d’unicité master data : matching, survivorship et stewardship.","question":"Quelle approche MDM est la plus correcte en gouvernance data pour les emails en doublon ?","options":["Supprimer aléatoirement une ligne sur deux sans règle de survie","Clé normalisée (email) + règle de survivorship + Owner/Steward CRM documentés","Ignorer les doublons tant que le CA « a l’air bon »"],"correctIndex":1,"correction":"Ch.10 MDM : matching (exact/fuzzy), golden record / trusted version, règles de survivorship, stewardship dédié. Sans politique, le hub ou le script ne « gouverne » rien."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l1-join', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.12 Metadata (lineage) · Ch.11 DW/BI (grain)","link":"Une jointure CA × clients engage grain et linéage du KPI finance.","question":"Quel énoncé décrit le mieux grain + linéage pour « CA livré par segment » ?","options":["Grain = une ligne Excel quelconque ; linéage inutile si le JOIN « marche »","Grain = segment × période ; linéage ventes + clients_ref → mart documenté au catalogue","Grain = pixel du dashboard ; linéage = nom du fichier Power BI seulement"],"correctIndex":1,"correction":"Le grain (Kimball/gouvernance data DW-BI) doit être explicite. Le linéage (Metadata) trace sources → transformations → produit data. Sans les deux, pas de « single version of truth » gouvernée."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l1-py-clean', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.13 Data Quality · Ch.3 Data Governance","link":"Industrialiser le nettoyage = politique de qualité versionnée, pas un one-shot.","question":"Où versionner et qui valide un changement de règle de normalisation email ?","options":["Uniquement en local sur le laptop, sans revue","Dans le repo (code + doc) avec PR revue Steward/Owner métier","Uniquement oralement en daily Scrum"],"correctIndex":1,"correction":"Les règles de qualité sont des actifs gouvernés : traçabilité du changement (qui a décidé quoi) fait partie de la DG. Code + documentation + accountability Owner/Steward = pratique de gouvernance data."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-sql', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.3 Data Governance · Ch.7 Data Security","link":"Un agrégat publié exige classification, Owner et droits d’usage.","question":"Pour l’agrégat immobilier par commune, quelle posture gouvernance data est correcte ?","options":["Données publiques par défaut ; tout le monde exporte sans contrôle","Classification (ex. interne) + Owner nommé + accès self-service sous garde-fous","Pas de classification : seul le CTO décide au cas par cas par Slack"],"correctIndex":1,"correction":"DG + Security : classifier, assigner la responsabilité, contrôler l’accès selon le risque. L’agrégat réduit le risque PII mais ne dispense pas de gouvernance d’usage."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-capteur', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.13 Data Quality · Ch.3 Data Governance","link":"Un seuil ops est un contrôle de qualité / fraîcheur opérationnelle.","question":"Que doit définir la gouvernance quand visiteurs < threshold ?","options":["Rien : le fichier CSV « parlera de lui-même »","Alerte + responsable + SLA / runbook (timeliness & issue management)","Uniquement un emoji dans le canal #random"],"correctIndex":1,"correction":"La qualité inclut la fraîcheur (timeliness) et le traitement des anomalies. Un contrôle sans propriétaire ni escalade n’est pas gouverné — la gouvernance data insiste sur rôles et processus, pas seulement sur la métrique."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-foot', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.12 Metadata · Ch.13 Data Quality","link":"CASE/agrégats formalisent des règles métier testables — comme toute définition gouvernée.","question":"Comment formaliser « victoire à domicile » selon les règles de gouvernance data ?","options":["Laisser chaque analyste interpréter FTR à sa guise","Définition explicite (FTR = H) + test d’acceptation chiffré","Remplacer la définition par le storytelling du dashboard"],"correctIndex":1,"correction":"Les définitions business metadata doivent être non ambiguës ; les contrôles prouvent le respect de la règle. Sinon : défaut sémantique (même nom, sens différents)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-window', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.11 DW & BI · Ch.3 Data Governance","link":"Window functions sur CA : le grain temporel du KPI doit être tranché.","question":"Si métier veut ranking créneau ET jour, que fait la gouvernance ?","options":["Un seul KPI ambigu qui mélange les deux grains","Deux définitions/KPI distincts, Owner Retail tranche, Steward publie","Cacher le grain pour « simplifier » le COMEX"],"correctIndex":1,"correction":"Le grain est un concept fondateur du décisionnel. Deux besoins = deux produits/définitions gouvernés, pas un indicateur fourre-tout. L’Owner arbitre ; le Steward documente."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-json', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.5 Data Modeling · Ch.8 Data Integration · Ch.3 DG","link":"Intégrer un JSON machine = contrat de schéma, rétention, ownership.","question":"Quel mini data contract est le plus compatible avec la gouvernance data ?","options":["Aucun champ obligatoire ; rétention infinie ; Owner inconnu","Champs obligatoires typés + rétention définie + Owner du schéma nommé","Contracter uniquement le logo du fournisseur IoT"],"correctIndex":1,"correction":"Contrats / standards de données (modélisation + intégration) et accountability DG. Un breaking change de schéma sans Owner = dette et risque ops."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-py', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.2 Ethics · Ch.7 Security/Privacy · Ch.3 DG","link":"L’ETL SCD vers actifs RH engage finalité et rétention (privacy / DG).","question":"Quelle affirmation est la plus alignée gouvernance data / privacy pour employees_actifs ?","options":["Conserver le landing brut indéfiniment « au cas où » sans finalité","Finalité métier explicite + rétention différenciée landing vs mart","Publier les noms sur un dashboard public pour « transparence »"],"correctIndex":1,"correction":"Finalité, minimisation et rétention sont au cœur privacy/éthique gouvernance data. Landing ≠ mart : politiques de cycle de vie distinctes sous gouvernance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-py-merge', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.3 Data Governance · Ch.10 MDM","link":"Merge CA×clients = produit data partagé Finance/CRM — stewardship clair.","question":"Si Finance et CRM divergent sur « livree », que faire (gouvernance data) ?","options":["Laisser deux définitions homonymes en production","Arbitrage Owner accountable + une définition publiée (comité / ADR)","Prendre la définition du dernier qui a parlé en réunion"],"correctIndex":1,"correction":"La DG tranche les conflits de définition ; l’Accountable Owner assume. Deux « vérités » = échec de gouvernance sémantique (et de confiance BI)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-dbt', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.10 MDM · Ch.13 Data Quality","link":"dbt encode la gouvernance opérationnelle : tests = politique qualité exécutable.","question":"Pourquoi unique(employee_id) sur le mart (pas le staging SCD) ?","options":["Parce que dbt refuse les tests sur le staging par principe technique","Le staging SCD a plusieurs versions ; le mart actifs est le golden record à contrôler","Les tests unique sont décoratifs et n’ont pas d’impact gouvernance"],"correctIndex":1,"correction":"Le golden / trusted record se contrôle où la règle métier est appliquée. Sur SCD brut, l’unicité de la clé métier échoue légitimement — mauvais contrôle = faux négatifs et confusion."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l4-kpi-sql', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.12 Metadata · Ch.11 DW/BI · Ch.3 DG","link":"La requête KPI est la définition exécutable : elle prime sur le storytelling BI.","question":"Que doit contenir une fiche KPI « Intensité CA » selon la gouvernance data ?","options":["Uniquement une capture d’écran Power BI sans Owner","Nom, définition (ex. SUM weight), Owner, classification / lien technique","Seulement le nom marketing du dashboard"],"correctIndex":1,"correction":"Métadonnées business (définition, Owner) + lien technique. Sans accountability ni classification, le KPI n’est pas gouverné — la viz seule ne suffit pas."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l4-grain', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.13 Data Quality · Ch.11 DW/BI","link":"Joindre sans aligner les grains = défaut sémantique / qualité majeur.","question":"Jointure capteur × weights sans agrégation : quelle réaction gouvernance ?","options":["Ignorer : « les totaux finiront par se stabiliser »","Incident qualité (sévérité haute) : retirer/corriger le produit, documenter le grain","Doubler les chiffres volontairement pour « être prudent »"],"correctIndex":1,"correction":"Un mauvais grain produit des faits non fitness-for-purpose. La gouvernance data traite cela comme un enjeu qualité + définition dimensionnelle — escalade et correction, pas silence."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l4-pbi', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.11 DW/BI · Ch.13 Data Quality","link":"Exposition BI : traçabilité mesure ↔ SQL de référence.","question":"Comment prouver en comité que la mesure BI = la requête de référence ?","options":["Affirmer que Power BI « calcule toujours juste »","Réconciliation chiffrée sur échantillon (SQL vs BI) sous Owner","Changer la requête SQL pour coller au dashboard"],"correctIndex":1,"correction":"Self-service / BI sous garde-fous : contenu certifié et contrôles. La réconciliation prouve la confiance ; inverser la vérité technique pour « coller » à la viz casse la gouvernance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l5-af', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.13 Data Quality (timeliness) · Ch.3 DG","link":"DAG Airflow = contrôle ops de fraîcheur (timeliness).","question":"Que doit fixer la gouvernance autour du sensor capteur ?","options":["Aucun SLA : on regarde le DAG quand on y pense","SLA de fraîcheur + retries + escalade runbook si timeout","Uniquement une belle capture Grafana sans propriétaire"],"correctIndex":1,"correction":"Timeliness est une dimension de qualité. Processus, rôles et escalade relèvent de la DG opérationnelle — le sensor technique sans SLA n’est pas une gouvernance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l5-transform', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.8 Data Integration & Interoperability · Ch.12 Metadata","link":"Transform paramétrée par date = idempotence et auditabilité.","question":"Pourquoi {{ ds }} est-il un prérequis gouvernance ?","options":["Pour faire joli dans les logs Airflow","Permettre rejeu, audit et partitions datées (preuve / idempotence)","Pour éviter d’écrire des tests de qualité"],"correctIndex":1,"correction":"Intégration gouvernée : traçabilité par lot/période, rejouabilité, métadonnées opérationnelles. Sans clé de run (ds), pas d’audit fiable du « quelle donnée pour quelle date »."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l5-cap', 'fr', 0, '{"damaRef":"Référentiel gouvernance · Ch.3 Data Governance (roles)","link":"Runbook pipeline = RACI / accountability de bout en bout.","question":"Pour la qualité du mart employés actifs, quel RACI est le plus gouvernance data ?","options":["Personne accountable ; tout le monde « co-owner » sans décision","Responsible = data engineer ; Accountable = Data Owner RH","Accountable = l’outil dbt lui-même"],"correctIndex":1,"correction":"La gouvernance data sépare accountability (Owner) et responsabilité opérationnelle (Steward / ingénierie). Un outil ne peut pas être Accountable. RACI clair = décision et escalade possibles."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l0-open', 'en', 0, '{"damaRef":"Governance framework · Ch.3 Data Governance · Ch.12 Metadata","link":"Inspecting the schema means establishing the technical catalog: without documented columns, no reliable steward or glossary.","question":"After retail_employees discovery, which Owner / artifact pair is most aligned with data governance?","options":["IT Support = Owner; no artifact (the CSV is enough)","HR Director / HR Ops = Data Owner; update catalog + “active employee” glossary","The data intern = sole Owner; personal unshared spreadsheet"],"correctIndex":1,"correction":"In data governance, the Data Owner is business-accountable (here retail HR/ops), not “whoever has the file.” The Steward operationalizes quality/metadata. After discovery, enrich business + technical metadata (catalog/glossary) — Ch.12 Metadata Management."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l0-filter', 'en', 0, '{"damaRef":"Governance framework · Ch.13 Data Quality · Ch.3 Data Governance","link":"The filter active_record = 1 materializes a quality business rule: governance must freeze it as the “active headcount” definition.","question":"Where should the rule “active employee = active_record = 1” live first?","options":["Only in the head of the analyst who filters Excel","As a governed quality rule / definition, tested (script or dbt) on the mart","Only in a PowerPoint slide from the last board meeting"],"correctIndex":1,"correction":"data governance (Data Quality): quality rules are defined, measured, and controlled — not improvised. Tie the rule to a governed business definition (DG) and execute it (tests) to avoid divergent KPIs."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l0-sql', 'en', 0, '{"damaRef":"Governance framework · Ch.13 Data Quality · Ch.12 Metadata","link":"The same business definition must produce the same result in SQL and Python — semantic consistency of definitions.","question":"How should data governance ensure SQL COUNT ≈ pandas value_counts?","options":["Trust the feeling if orders of magnitude look similar","Documented reconciliation / quality control (gold set, assert, CI test) on the same definition","Change the SQL definition until the dashboard looks “pretty”"],"correctIndex":1,"correction":"“Fitness for purpose” quality implies consistency controls across pipelines. Quantified reconciliation + shared definition metadata (glossary/KPI) is the data governance move; variance becomes a quality incident, not a cosmetic tweak."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l1-dupes', 'en', 0, '{"damaRef":"Governance framework · Ch.10 Reference & Master Data","link":"Email duplicates are a master-data uniqueness defect: matching, survivorship, and stewardship.","question":"Which MDM approach is most correct under data governance for duplicate emails?","options":["Randomly delete every other row with no survivorship rule","Normalized key (email) + survivorship rule + documented CRM Owner/Steward","Ignore duplicates as long as revenue “looks fine”"],"correctIndex":1,"correction":"Ch.10 MDM: matching (exact/fuzzy), golden record / trusted version, survivorship rules, dedicated stewardship. Without policy, the hub or script “governs” nothing."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l1-join', 'en', 0, '{"damaRef":"Governance framework · Ch.12 Metadata (lineage) · Ch.11 DW/BI (grain)","link":"A revenue × customers join commits grain and lineage of the finance KPI.","question":"Which statement best describes grain + lineage for “delivered revenue by segment”?","options":["Grain = any Excel row; lineage useless if the JOIN “works”","Grain = segment × period; lineage sales + clients_ref → mart documented in the catalog","Grain = dashboard pixel; lineage = Power BI file name only"],"correctIndex":1,"correction":"Grain (Kimball/data governance DW-BI) must be explicit. Lineage (Metadata) traces sources → transformations → data product. Without both, no governed “single version of truth.”"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l1-py-clean', 'en', 0, '{"damaRef":"Governance framework · Ch.13 Data Quality · Ch.3 Data Governance","link":"Industrializing cleanup = versioned quality policy, not a one-shot.","question":"Where do you version and who validates an email-normalization rule change?","options":["Only locally on the laptop, with no review","In the repo (code + docs) with PR reviewed by Steward/business Owner","Only verbally in the daily Scrum"],"correctIndex":1,"correction":"Quality rules are governed assets: change traceability (who decided what) is part of DG. Code + documentation + Owner/Steward accountability = data governance practice."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-sql', 'en', 0, '{"damaRef":"Governance framework · Ch.3 Data Governance · Ch.7 Data Security","link":"A published aggregate requires classification, Owner, and usage rights.","question":"For the real-estate aggregate by commune, which data governance stance is correct?","options":["Public by default; everyone exports with no control","Classification (e.g. internal) + named Owner + self-service access under guardrails","No classification: only the CTO decides case-by-case on Slack"],"correctIndex":1,"correction":"DG + Security: classify, assign responsibility, control access by risk. Aggregation reduces PII risk but does not waive usage governance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-capteur', 'en', 0, '{"damaRef":"Governance framework · Ch.13 Data Quality · Ch.3 Data Governance","link":"An ops threshold is an operational quality / freshness control.","question":"What must governance define when visitors < threshold?","options":["Nothing: the CSV file “will speak for itself”","Alert + owner + SLA / runbook (timeliness & issue management)","Only an emoji in the #random channel"],"correctIndex":1,"correction":"Quality includes freshness (timeliness) and anomaly handling. A control without owner or escalation is not governed — data governance insists on roles and process, not just the metric."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-foot', 'en', 0, '{"damaRef":"Governance framework · Ch.12 Metadata · Ch.13 Data Quality","link":"CASE/aggregates formalize testable business rules — like any governed definition.","question":"How do you formalize “home win” under data-governance rules?","options":["Let each analyst interpret FTR as they like","Explicit definition (FTR = H) + quantified acceptance test","Replace the definition with dashboard storytelling"],"correctIndex":1,"correction":"Business metadata definitions must be unambiguous; controls prove rule compliance. Otherwise: semantic defect (same name, different meanings)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l2-window', 'en', 0, '{"damaRef":"Governance framework · Ch.11 DW & BI · Ch.3 Data Governance","link":"Window functions on revenue: the KPI’s temporal grain must be decided.","question":"If business wants ranking by slot AND by day, what does governance do?","options":["One ambiguous KPI that mixes both grains","Two distinct definitions/KPIs; Retail Owner decides; Steward publishes","Hide the grain to “simplify” the board"],"correctIndex":1,"correction":"Grain is a foundational BI concept. Two needs = two governed products/definitions, not a catch-all indicator. The Owner arbitrates; the Steward documents."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-json', 'en', 0, '{"damaRef":"Governance framework · Ch.5 Data Modeling · Ch.8 Data Integration · Ch.3 DG","link":"Integrating machine JSON = schema contract, retention, ownership.","question":"Which mini data contract is most compatible with data governance?","options":["No mandatory fields; infinite retention; unknown Owner","Typed mandatory fields + defined retention + named schema Owner","Contract only the IoT vendor logo"],"correctIndex":1,"correction":"Data contracts / standards (modeling + integration) and DG accountability. A schema breaking change with no Owner = debt and ops risk."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-py', 'en', 0, '{"damaRef":"Governance framework · Ch.2 Ethics · Ch.7 Security/Privacy · Ch.3 DG","link":"SCD ETL to active HR engages purpose and retention (privacy / DG).","question":"Which statement is most aligned with data governance / privacy for employees_actifs?","options":["Keep raw landing forever “just in case” with no purpose","Explicit business purpose + differentiated retention landing vs mart","Publish names on a public dashboard for “transparency”"],"correctIndex":1,"correction":"Purpose, minimization, and retention are core to data governance privacy/ethics. Landing ≠ mart: distinct lifecycle policies under governance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-py-merge', 'en', 0, '{"damaRef":"Governance framework · Ch.3 Data Governance · Ch.10 MDM","link":"CA×clients merge = shared Finance/CRM data product — clear stewardship.","question":"If Finance and CRM diverge on “delivered”, what to do (data governance)?","options":["Leave two same-named definitions in production","Accountable Owner arbitration + one published definition (committee / ADR)","Take the definition of whoever spoke last in the meeting"],"correctIndex":1,"correction":"DG resolves definition conflicts; the Accountable Owner owns the call. Two “truths” = semantic governance failure (and BI trust failure)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l3-dbt', 'en', 0, '{"damaRef":"Governance framework · Ch.10 MDM · Ch.13 Data Quality","link":"dbt encodes operational governance: tests = executable quality policy.","question":"Why unique(employee_id) on the mart (not SCD staging)?","options":["Because dbt refuses tests on staging on technical principle","SCD staging has multiple versions; the active mart is the golden record to control","Uniqueness tests are decorative and have no governance impact"],"correctIndex":1,"correction":"The golden / trusted record is controlled where the business rule is applied. On raw SCD, business-key uniqueness legitimately fails — wrong control = false negatives and confusion."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l4-kpi-sql', 'en', 0, '{"damaRef":"Governance framework · Ch.12 Metadata · Ch.11 DW/BI · Ch.3 DG","link":"The KPI query is the executable definition: it takes precedence over BI storytelling.","question":"What must a “Revenue Intensity” KPI sheet contain under data governance?","options":["Only a Power BI screenshot with no Owner","Name, definition (e.g. SUM weight), Owner, classification / technical link","Only the dashboard marketing name"],"correctIndex":1,"correction":"Business metadata (definition, Owner) + technical link. Without accountability or classification, the KPI is not governed — viz alone is not enough."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l4-grain', 'en', 0, '{"damaRef":"Governance framework · Ch.13 Data Quality · Ch.11 DW/BI","link":"Joining without aligning grains = major semantic / quality defect.","question":"Sensor × weights join without aggregation: governance reaction?","options":["Ignore: “totals will eventually stabilize”","Quality incident (high severity): withdraw/fix the product, document the grain","Double the figures on purpose to “be cautious”"],"correctIndex":1,"correction":"Wrong grain produces facts that are not fitness-for-purpose. Data governance treats this as a quality + dimensional definition issue — escalate and fix, do not stay silent."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l4-pbi', 'en', 0, '{"damaRef":"Governance framework · Ch.11 DW/BI · Ch.13 Data Quality","link":"BI exposition: measure ↔ reference SQL traceability.","question":"How do you prove in committee that the BI measure = the reference query?","options":["Claim Power BI “always calculates correctly”","Quantified reconciliation on a sample (SQL vs BI) under Owner","Change the SQL query to match the dashboard"],"correctIndex":1,"correction":"Self-service / BI under guardrails: certified content and controls. Reconciliation proves trust; inverting technical truth to “match” viz breaks governance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l5-af', 'en', 0, '{"damaRef":"Governance framework · Ch.13 Data Quality (timeliness) · Ch.3 DG","link":"Airflow DAG = ops freshness control (timeliness).","question":"What must governance set around the sensor?","options":["No SLA: we look at the DAG when we think of it","Freshness SLA + retries + runbook escalation on timeout","Only a pretty Grafana screenshot with no owner"],"correctIndex":1,"correction":"Timeliness is a quality dimension. Process, roles, and escalation belong to operational DG — a technical sensor with no SLA is not governance."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l5-transform', 'en', 0, '{"damaRef":"Governance framework · Ch.8 Data Integration & Interoperability · Ch.12 Metadata","link":"Date-parameterized transform = idempotence and auditability.","question":"Why is {{ ds }} a governance prerequisite?","options":["To look nice in Airflow logs","Enable replay, audit and dated partitions (evidence / idempotence)","To avoid writing quality tests"],"correctIndex":1,"correction":"Governed integration: batch/period traceability, replayability, operational metadata. Without a run key (ds), no reliable audit of “which data for which date.”"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('gov_curated', 'l5-cap', 'en', 0, '{"damaRef":"Governance framework · Ch.3 Data Governance (roles)","link":"Pipeline runbook = end-to-end RACI / accountability.","question":"For active-employees mart quality, which RACI best fits data governance?","options":["Nobody accountable; everyone “co-owner” with no decision","Responsible = data engineer; Accountable = HR Data Owner","Accountable = the dbt tool itself"],"correctIndex":1,"correction":"Data governance separates accountability (Owner) from operational responsibility (Steward / engineering). A tool cannot be Accountable. Clear RACI = decision and escalation possible."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-0', 'fr', 0, '{"frameworkRef":"Scrum — facilitation · Gestion de projet — Conflict management","link":"Gestion de conflit — désaccord technique en public.","question":"Deux seniors s’affrontent en Daily sur une approche. Meilleure posture PM / SM ?","options":["Laisser durer pour « que ça se règle »","Parker le débat, recentrer le Goal, faciliter un créneau dédié hors Daily","Imposer ta solution préférée devant tout le monde"],"correctIndex":1,"correction":"Le Daily n’est pas un tribunal. On protège le flux, on traite le conflit en espace adapté, sans humiliation."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-1', 'fr', 1, '{"frameworkRef":"Gestion de projet — Stakeholder & conflict · agile à l’échelle — alignment","link":"Gestion de conflit — métier vs IT.","question":"Le métier accuse la DSI de « freiner » ; la DSI accuse le métier d’« improviser ». Que fais-tu ?","options":["Prendre parti pour le plus haut gradé","Faciliter un atelier faits / impacts / options, faire trancher l’Accountable","Éviter le sujet jusqu’au prochain PI"],"correctIndex":1,"correction":"On remplace les accusations par des faits et un arbitrage Owner. Le PM facilite, il ne joue pas les clans."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-2', 'fr', 2, '{"frameworkRef":"agile à l’échelle — sustainable pace · Scrum — team health · Gestion de projet — Resource","link":"Gestion des personnes — capacité et surcharge.","question":"Un développeur clé enchaîne les nuits pour tenir la date. Réflexe ?","options":["Le féliciter et en demander encore plus","Protéger la capacity : replanifier, dire non au scope, traiter le risque humain","Ignorer tant que le burndown est vert"],"correctIndex":1,"correction":"Le rythme soutenable est une contrainte projet. Brûler les gens détruit la delivery à moyen terme."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-3', 'fr', 3, '{"frameworkRef":"Gestion de projet — Team performance · Scrum — coaching","link":"Gestion des personnes — feedback & performance.","question":"Une personne rate plusieurs AC d’affilée. Approche constructive ?","options":["La blâmer en Sprint Review","Feedback privé factuel + pairage / clarification AC + plan d’amélioration","La retirer du board sans discussion"],"correctIndex":1,"correction":"Feedback privé, faits, soutien. La Review n’est pas un tribunal individuel."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-4', 'fr', 4, '{"frameworkRef":"Gestion de projet — Decision making · Agile — reversible decisions","link":"Prise de décision — sous incertitude.","question":"Il manque 30 % d’info pour choisir l’outil. Que décides-tu ?","options":["Attendre d’avoir 100 % des infos","Décider avec critères explicites, timebox, et critère de pivot documenté","Laisser chacun choisir son outil en silence"],"correctIndex":1,"correction":"Décider avec un cadre (critères, horizon, pivot) bat l’attente paralysante et le chaos."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-5', 'fr', 5, '{"frameworkRef":"Gestion de projet — RACI · Scrum — Product Owner · agile à l’échelle — content authority","link":"Prise de décision — RACI humain.","question":"Qui doit trancher quand PO et architecte divergent sur le scope technique ?","options":["Le plus bruyant sur Slack","L’Accountable du Goal (souvent PO / sponsor) après options chiffrées","Personne — on livre les deux options"],"correctIndex":1,"correction":"Le PO / Accountable tranche sur la valeur ; l’archi éclaire les options. Pas de double vérité."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-6', 'fr', 6, '{"frameworkRef":"Gestion de projet — Communication · agile à l’échelle — transparency","link":"Communication — mauvaise nouvelle.","question":"Tu sais que le jalon COMEX va glisser de 5 jours. Quand communiques-tu ?","options":["Le jour J, pour « ne pas stresser »","Dès que le risque est crédible : faits, impact, options, décision demandée","Seulement si quelqu’un pose la question"],"correctIndex":1,"correction":"La confiance se construit sur l’alerte précoce. Retarder = amplifier la crise."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-7', 'fr', 7, '{"frameworkRef":"Gestion de projet — Stakeholder communication · Scrum — information radiators","link":"Communication — audiences multiples.","question":"Comment adapter le message COMEX vs équipe ?","options":["Même jargon technique pour tous","COMEX : décisions/risques/valeur ; équipe : impediments/plan/DoD","Ne rien dire au COMEX pour protéger l’équipe"],"correctIndex":1,"correction":"Même vérité, niveaux de détail adaptés. Pas de double langage trompeur."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-8', 'fr', 8, '{"frameworkRef":"Gestion de projet — Negotiation · Agile — iron triangle","link":"Négociation — scope vs date.","question":"Le sponsor veut date fixe + scope fixe. Réponse saine ?","options":["Accepter les deux et « se débrouiller »","Négocier : date fixe ⇒ scope priorisé / MVP ; sinon date flottante","Promettre secrètement un overtime généralisé"],"correctIndex":1,"correction":"On ne peut pas fixer date, scope et capacity sans trade-off. Le PM rend le triangle explicite."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-9', 'fr', 9, '{"frameworkRef":"Gestion de projet — Influence · agile à l’échelle — dependency management","link":"Influence sans autorité hiérarchique.","question":"Tu n’as pas de pouvoir formel sur une équipe partenaire bloquante. Levier ?","options":["Menacer par mail en copie générale","Intérêt commun, données d’impact, escalade RACI si besoin","Contourner en Shadow IT"],"correctIndex":1,"correction":"Influence = valeur partagée + faits + escalade propre. Pas de chantage ni de shadow."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-10', 'fr', 10, '{"frameworkRef":"agile à l’échelle — Lean-Agile leadership · Gestion de projet — Team culture","link":"Leadership — sécurité psychologique.","question":"Une junior signale une erreur en prod. Réaction qui renforce l’équipe ?","options":["La ridiculiser pour « que ça serve d’exemple »","Remercier le signalement, blameless post-mortem, correctif systémique","Cacher l’incident pour protéger l’image"],"correctIndex":1,"correction":"La sécurité psychologique fait remonter les risques tôt. La culture du blâme les enterre."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-11', 'fr', 11, '{"frameworkRef":"Gestion de projet — Change management · Prosci / ADKAR (esprit)","link":"Conduite du changement — adoption.","question":"Le métier n’utilise pas le nouveau dashboard. Priorité ?","options":["Forcer l’usage par mail de direction","Comprendre les freins, co-construire enablement, mesurer l’adoption","Abandonner sans diagnostic"],"correctIndex":1,"correction":"L’adoption se gagne : freins, formation, champions, mesure — pas la contrainte seule."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-12', 'fr', 12, '{"frameworkRef":"Scrum Master — facilitation · Gestion de projet — Meeting management","link":"Réunion — facilitation.","question":"Un atelier dérape en monologue du sponsor. Que fais-tu ?","options":["Laisser finir « par respect »","Recadrer l’objectif, timebox, redistribuer la parole","Couper brutalement et quitter la salle"],"correctIndex":1,"correction":"Faciliter = protéger l’objectif et l’équité de parole, avec fermeté respectueuse."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-13', 'fr', 13, '{"frameworkRef":"Gestion de projet — Team management · Agile — collaboration","link":"Équipe — conflit de personnalité.","question":"Deux profils refusent de travailler ensemble. Option viable ?","options":["Les forcer sur le même ticket sans cadre","Clarifier RACI, interface, règles de collab ; médiation si besoin","Les isoler définitivement sans objectif commun"],"correctIndex":1,"correction":"On cadre le « comment travailler ensemble » (rôles, interfaces). L’évitement pur coûte cher."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-14', 'fr', 14, '{"frameworkRef":"Gestion de projet — Recognition · sustainable pace","link":"Motivation — reconnaissance.","question":"L’équipe vient de sauver un COMEX. Meilleur geste ?","options":["Rien dire : « c’est normal »","Reconnaître publiquement le résultat + apprentissage + recovery time","Ajouter immédiatement un lot « encore plus dur »"],"correctIndex":1,"correction":"La reconnaissance + récupération entretiennent l’engagement. L’ingratitude puis le rush brûlent l’équipe."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-15', 'fr', 15, '{"frameworkRef":"Gestion de projet — Escalation · agile à l’échelle — problem-solving","link":"Décision — escalade.","question":"Quand escalades-tu un blocage au sponsor ?","options":["Dès le premier désaccord d’équipe","Quand l’impact Goal/date/risque dépasse le mandat local et après tentative de résolution","Jamais : ça fait « mauvais PM »"],"correctIndex":1,"correction":"Escalader trop tôt = bruit. Trop tard = crise. On escalade avec faits et options."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-16', 'fr', 16, '{"frameworkRef":"Gestion de projet — Crisis communication · Compliance","link":"Communication de crise.","question":"Fuite partielle de données suspectée. Premier message interne ?","options":["Silence radio jusqu’à investigation complète","Alerte factuelle : ce qu’on sait / ne sait pas, actions, prochain point","Minimiser publiquement « ce n’est rien »"],"correctIndex":1,"correction":"Transparence contrôlée : faits, actions, cadence. Ni panique ni déni."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-17', 'fr', 17, '{"frameworkRef":"Gestion de projet — Procurement / negotiation","link":"Négociation — vendor / prestataire.","question":"Le prestataire dérive sur le forfait. Posture ?","options":["Accepter sans avenant pour « garder la paix »","Revenir au contrat / DoD, options (avenant, scope cut, exit), décider","Menacer de contentieux dès le premier retard"],"correctIndex":1,"correction":"On gère par le cadre contractuel et des options claires — pas la naïveté ni l’escalade immédiate."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-18', 'fr', 18, '{"frameworkRef":"Gestion de projet — Team development · Scrum — mentoring","link":"Personnes — onboarding nouvel arrivant.","question":"Un junior arrive en milieu de Sprint critique. Bon réflexe ?","options":["Le laisser seul sur un chantier sensible","Buddy, context Goal/DoD, tickets à sa portée, feedback court","Lui faire lire 200 pages Confluence sans pairage"],"correctIndex":1,"correction":"Onboarding = buddy + contexte + charge progressive. Sinon risque qualité et démotivation."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-19', 'fr', 19, '{"frameworkRef":"Gestion de projet — Evidence-based decisions · Agile — spike","link":"Décision — biais & données.","question":"Un directeur pousse une option « parce que ça a marché ailleurs ». Toi ?","options":["Suivre l’autorité sans analyse","Exiger critères locaux (coût, risque, fit) et une preuve / spike court","Refuser par principe toute idée externe"],"correctIndex":1,"correction":"L’autorité n’annule pas le besoin de critères et de preuve locale."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-20', 'fr', 20, '{"frameworkRef":"Scrum — Sprint Goal protection · Gestion de projet — Issue & politics","link":"Conflit — priorités politiques.","question":"Un VIP impose un ticket hors Sprint Goal. Que fais-tu ?","options":["L’insérer en silence pour éviter le clash","Rendre le trade-off visible (Goal / capacity) et faire arbitrer l’Accountable","Dire non sans explication"],"correctIndex":1,"correction":"On ne subit pas la politique en silence : on expose le coût et on fait décider."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'fr-21', 'fr', 21, '{"frameworkRef":"Gestion de projet — Communication plan · remote collaboration","link":"Communication — async & remote.","question":"Équipe hybride : décisions perdues dans les meetings. Correction ?","options":["Plus de réunions encore","Décisions écrites (ADR / Confluence), owners, canaux async clairs","Tout décider en privé entre 2 personnes"],"correctIndex":1,"correction":"Décision = écrite, trouvée, owner. L’oral seul ne scale pas en hybride."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-0', 'en', 0, '{"frameworkRef":"Scrum — facilitation · Project management — Conflict management","link":"Conflict management — public technical disagreement.","question":"Two seniors clash in Daily about an approach. Best PM / SM posture?","options":["Let it run so “they sort it out”","Park the debate, re-center the Goal, facilitate a dedicated slot outside Daily","Impose your preferred solution in front of everyone"],"correctIndex":1,"correction":"Daily is not a tribunal. Protect flow; handle conflict in a fit-for-purpose space, without humiliation."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-1', 'en', 1, '{"frameworkRef":"Project management — Stakeholder & conflict · scaled agile — alignment","link":"Conflict management — business vs IT.","question":"Business accuses IT of “blocking”; IT accuses business of “improvising”. What do you do?","options":["Side with the most senior title","Facilitate a facts / impacts / options workshop; have the Accountable decide","Avoid the topic until the next PI"],"correctIndex":1,"correction":"Replace accusations with facts and an Owner decision. The PM facilitates; they do not pick clans."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-2', 'en', 2, '{"frameworkRef":"scaled agile — sustainable pace · Scrum — team health · Project management — Resource","link":"People management — capacity and overload.","question":"A key developer works nights to hit the date. Your reflex?","options":["Praise them and ask for more","Protect capacity: replan, say no to scope, treat the human risk","Ignore it while the burndown stays green"],"correctIndex":1,"correction":"Sustainable pace is a project constraint. Burning people destroys medium-term delivery."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-3', 'en', 3, '{"frameworkRef":"Project management — Team performance · Scrum — coaching","link":"People management — feedback & performance.","question":"Someone misses several ACs in a row. Constructive approach?","options":["Blame them in Sprint Review","Private factual feedback + pairing / AC clarity + improvement plan","Remove them from the board with no discussion"],"correctIndex":1,"correction":"Private feedback, facts, support. Review is not an individual tribunal."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-4', 'en', 4, '{"frameworkRef":"Project management — Decision making · Agile — reversible decisions","link":"Decision-making — under uncertainty.","question":"You lack 30% of the info to pick a tool. What do you decide?","options":["Wait until you have 100% of the information","Decide with explicit criteria, a timebox, and a documented pivot rule","Let everyone silently pick their own tool"],"correctIndex":1,"correction":"Deciding with a frame (criteria, horizon, pivot) beats paralysis and chaos."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-5', 'en', 5, '{"frameworkRef":"Project management — RACI · Scrum — Product Owner · scaled agile — content authority","link":"Decision-making — human RACI.","question":"Who should decide when PO and architect diverge on technical scope?","options":["Whoever is loudest on Slack","The Accountable for the Goal (often PO / sponsor) after costed options","Nobody — ship both options"],"correctIndex":1,"correction":"PO / Accountable decides value; architecture clarifies options. No double truth."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-6', 'en', 6, '{"frameworkRef":"Project management — Communication · scaled agile — transparency","link":"Communication — bad news.","question":"You know the board milestone will slip 5 days. When do you communicate?","options":["On the day itself, to “avoid stress”","As soon as the risk is credible: facts, impact, options, decision needed","Only if someone asks"],"correctIndex":1,"correction":"Trust is built on early alerts. Delay amplifies the crisis."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-7', 'en', 7, '{"frameworkRef":"Project management — Stakeholder communication · Scrum — information radiators","link":"Communication — multiple audiences.","question":"How do you adapt the board message vs the team message?","options":["Same technical jargon for everyone","Board: decisions/risks/value; team: impediments/plan/DoD","Tell the board nothing to “protect” the team"],"correctIndex":1,"correction":"Same truth, adapted depth. No deceptive doublespeak."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-8', 'en', 8, '{"frameworkRef":"Project management — Negotiation · Agile — iron triangle","link":"Negotiation — scope vs date.","question":"The sponsor wants fixed date + fixed scope. Healthy answer?","options":["Accept both and “figure it out”","Negotiate: fixed date ⇒ prioritized / MVP scope; otherwise floating date","Secretly promise widespread overtime"],"correctIndex":1,"correction":"You cannot fix date, scope and capacity with no trade-off. Make the triangle explicit."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-9', 'en', 9, '{"frameworkRef":"Project management — Influence · scaled agile — dependency management","link":"Influence without hierarchy.","question":"You have no formal authority over a blocking partner team. Best lever?","options":["Threaten by email with a wide CC","Shared interest, impact data, RACI escalation if needed","Bypass with Shadow IT"],"correctIndex":1,"correction":"Influence = shared value + facts + clean escalation. No blackmail, no shadow."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-10', 'en', 10, '{"frameworkRef":"scaled agile — Lean-Agile leadership · Project management — Team culture","link":"Leadership — psychological safety.","question":"A junior reports a prod mistake. Reaction that strengthens the team?","options":["Mock them so it “sets an example”","Thank the signal, blameless post-mortem, systemic fix","Hide the incident to protect image"],"correctIndex":1,"correction":"Psychological safety surfaces risks early. Blame culture buries them."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-11', 'en', 11, '{"frameworkRef":"Project management — Change management · Prosci / ADKAR (spirit)","link":"Change management — adoption.","question":"Business is not using the new dashboard. Priority?","options":["Force usage via an exec email","Understand blockers, co-build enablement, measure adoption","Drop it with no diagnosis"],"correctIndex":1,"correction":"Adoption is earned: blockers, training, champions, measurement — not force alone."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-12', 'en', 12, '{"frameworkRef":"Scrum Master — facilitation · Project management — Meeting management","link":"Meetings — facilitation.","question":"A workshop turns into the sponsor’s monologue. What do you do?","options":["Let it finish “out of respect”","Re-center the objective, timebox, redistribute airtime","Cut them off harshly and leave the room"],"correctIndex":1,"correction":"Facilitate = protect the objective and fair airtime, with respectful firmness."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-13', 'en', 13, '{"frameworkRef":"Project management — Team management · Agile — collaboration","link":"Team — personality conflict.","question":"Two people refuse to work together. Viable option?","options":["Force them on the same ticket with no frame","Clarify RACI, interface, collab rules; mediate if needed","Isolate them forever with no shared objective"],"correctIndex":1,"correction":"Frame how to work together (roles, interfaces). Pure avoidance is expensive."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-14', 'en', 14, '{"frameworkRef":"Project management — Recognition · sustainable pace","link":"Motivation — recognition.","question":"The team just saved a board meeting. Best move?","options":["Say nothing: “that’s normal”","Publicly recognize the outcome + learning + recovery time","Immediately add an even harder batch"],"correctIndex":1,"correction":"Recognition + recovery sustain engagement. Ingratitude then rush burns the team."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-15', 'en', 15, '{"frameworkRef":"Project management — Escalation · scaled agile — problem-solving","link":"Decision — escalation.","question":"When do you escalate a blocker to the sponsor?","options":["At the first team disagreement","When Goal/date/risk impact exceeds local mandate, after a resolution attempt","Never: it looks like a “bad PM”"],"correctIndex":1,"correction":"Escalate too early = noise. Too late = crisis. Escalate with facts and options."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-16', 'en', 16, '{"frameworkRef":"Project management — Crisis communication · Compliance","link":"Crisis communication.","question":"Suspected partial data leak. First internal message?","options":["Radio silence until full investigation","Factual alert: what we know / don’t know, actions, next checkpoint","Publicly downplay “it’s nothing”"],"correctIndex":1,"correction":"Controlled transparency: facts, actions, cadence. Neither panic nor denial."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-17', 'en', 17, '{"frameworkRef":"Project management — Procurement / negotiation","link":"Negotiation — vendor.","question":"The vendor drifts on the fixed-price scope. Posture?","options":["Accept without amendment to “keep the peace”","Return to contract / DoD, options (amendment, scope cut, exit), decide","Threaten litigation at the first delay"],"correctIndex":1,"correction":"Manage via contractual frame and clear options — not naivety or instant escalation."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-18', 'en', 18, '{"frameworkRef":"Project management — Team development · Scrum — mentoring","link":"People — onboarding a newcomer.","question":"A junior joins in the middle of a critical Sprint. Good reflex?","options":["Leave them alone on a sensitive workstream","Buddy, Goal/DoD context, right-sized tickets, short feedback","Make them read 200 Confluence pages with no pairing"],"correctIndex":1,"correction":"Onboarding = buddy + context + progressive load. Else quality risk and demotivation."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-19', 'en', 19, '{"frameworkRef":"Project management — Evidence-based decisions · Agile — spike","link":"Decision — bias & data.","question":"A director pushes an option “because it worked elsewhere”. You?","options":["Follow authority with no analysis","Require local criteria (cost, risk, fit) and a short proof / spike","Reject any external idea on principle"],"correctIndex":1,"correction":"Authority does not cancel the need for local criteria and proof."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-20', 'en', 20, '{"frameworkRef":"Scrum — Sprint Goal protection · Project management — Issue & politics","link":"Conflict — political priorities.","question":"A VIP forces a ticket outside the Sprint Goal. What do you do?","options":["Insert it silently to avoid clash","Make the trade-off visible (Goal / capacity) and have the Accountable decide","Say no with no explanation"],"correctIndex":1,"correction":"Do not absorb politics silently: expose the cost and force a decision."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('pm_human', 'en-21', 'en', 21, '{"frameworkRef":"Project management — Communication plan · remote collaboration","link":"Communication — async & remote.","question":"Hybrid team: decisions get lost in meetings. Fix?","options":["Even more meetings","Written decisions (ADR / Confluence), owners, clear async channels","Decide everything privately between two people"],"correctIndex":1,"correction":"A decision is written, findable, owned. Oral-only does not scale in a hybrid setup."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
