INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'conf-charter-1', 'fr', 0, '{"id":"conf-charter-1","tool":"confluence","level":1,"title":"Charte produit data (Data Product Charter)","context":"Une banque mutualiste lance un « Client 360 » pour les conseillers. Le sponsor veut tout ; l’équipe data est de 3 personnes.","description":"Tu structures une page Confluence de cadrage pour aligner métier et data avant tout développement.","tasks":["Rédiger le problème métier en 2–3 phrases","Lister max 3 KPI de succès","Définir le hors-scope explicite","Identifier owner produit et steward data"],"trap":"Au-delà de 3 KPI, le MVP se dilue : le sponsor « veut tout » et plus rien n’est Done.","steps":[{"title":"Page & template","detail":"Crée une page « Client 360 — Charter ». Sections : Problème, Users, KPI, Hors-scope, Risques, Décisions."},{"title":"Problème","detail":"Formule : Qui souffre ? De quoi ? Impact mesurable. Ex. : « Les conseillers ouvrent 4 systèmes pour un même client → temps de préparation RDV ×2 »."},{"title":"KPI (max 3)","detail":"Choisis des indicateurs actionnables (ex. % fiches complètes, temps moyen préparation RDV, NPS usage outil). Évite les vanity metrics."},{"title":"Hors-scope","detail":"Liste ce qui n’est PAS dans le MVP (ex. scoring crédit temps réel, app mobile). Cela protège le délai."}],"questions":[{"id":"n1q1","prompt":"Combien de KPI de succès recommandés au maximum dans une charte MVP ?","kind":"mcq","options":["1","3","10","Autant que le sponsor veut"],"accept":["3"],"explanation":"3 KPI max force la priorisation. Au-delà, le MVP se dilue et on ne sait plus ce qui est « Done »."},{"id":"n1q2","prompt":"Le hors-scope sert principalement à…","kind":"mcq","options":["Remplir une case qualité","Protéger le délai et clarifier les attentes","Lister toutes les idées futures","Remplacer le backlog Jira"],"accept":["Protéger le délai et clarifier les attentes"],"explanation":"Le hors-scope aligne le sponsor : ce qui n’est pas livré dans le MVP, pour éviter le scope creep."},{"id":"n1q3","prompt":"Mot-clé d’une bonne formulation de problème (un mot) :","kind":"short","accept":["impact","mesurable","utilisateur","users","douleur","pain"],"explanation":"Un bon problème cite l’utilisateur et un impact mesurable (temps, coût, risque, qualité)."}],"modelSolution":"Charte type : Problème (conseillers multi-systèmes, temps RDV ×2) · Users (conseillers, compliance) · KPI (temps prépa, % fiches complètes, adoption) · Hors-scope (scoring temps réel, mobile) · Owner produit + steward data nommés · Risques (qualité CRM, accès RGPD)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'jira-backlog-charter-2', 'fr', 1, '{"id":"jira-backlog-charter-2","tool":"jira","level":2,"title":"Backlog Jira — data product lié à la charte","context":"Après la charte Client 360, le PO data veut un backlog vivant partagé avec data engineers et analystes.","description":"Tu structures le backlog Jira (epics / stories) pour suivre les items du produit data.","tasks":["Définir les champs essentiels (statut, priorité, KPI, owner)","Proposer 3 vues (board / sprint / roadmap)","Lier chaque item à un KPI de la charte"],"trap":"Un item de backlog sans lien vers un KPI charter est souvent du travail décoratif — hors MVP.","steps":[{"title":"Structure","detail":"Epic = outcome charter. Stories INVEST. Labels : KPI, phase (ingest/transform/expose), outil."},{"title":"Vues","detail":"Board statut (flux), filtre sprint, timeline/roadmap pour le reporting direction."},{"title":"Règle","detail":"Pas de story sans lien vers un KPI de la charte — sinon hors MVP."}],"questions":[{"id":"n2q1","prompt":"Propriété la plus critique pour éviter le travail « décoratif » :","kind":"mcq","options":["Couleur","KPI lié","Emoji","Cover image"],"accept":["KPI lié"],"explanation":"Si un item ne contribue à aucun KPI charter, il n’a pas sa place dans le MVP."},{"id":"n2q2","prompt":"Nomme une vue utile pour le daily data (un mot : board / table / timeline) :","kind":"short","accept":["board","kanban","table"],"explanation":"Un board (ou table sprint) montre le flux du jour ; la timeline sert plutôt au reporting direction."}],"modelSolution":"Jira : Epics liés KPI charter · Stories avec AC · Labels outil/phase · Board statut + filtre sprint + roadmap. Règle : pas d’item sans KPI charter."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'conf-adr-1', 'fr', 2, '{"id":"conf-adr-1","tool":"confluence","level":1,"title":"ADR — BigQuery vs Cloud SQL (mart finance)","context":"Le mart finance doit servir 40 analystes (lecture lourde) et 2 apps opérationnelles (écriture transactionnelle légère).","description":"Tu rédiges un Architecture Decision Record (ADR) pour trancher le stockage analytique.","tasks":["Rédiger Contexte, Options, Décision, Conséquences","Comparer BigQuery et Cloud SQL sur charge analytique","Documenter les trade-offs (coût, latence, ops)"],"trap":"Choisir Cloud SQL « pour tout » saturera sous 40 analystes en scan large — sépare OLTP et analytique.","steps":[{"title":"Template ADR","detail":"Titre, Statut (Proposed/Accepted), Contexte, Options (avec critères), Décision, Conséquences (+/−), Liens Jira."},{"title":"Critères","detail":"Volume scan, concurrence lecteurs, coût €/TB, besoin transactions ACID, compétences équipe."},{"title":"Décision typique","detail":"Analytique large → BigQuery ; OLTP / faible latence transactionnelle → Cloud SQL. Souvent les deux (OLTP → export → BQ)."}],"questions":[{"id":"c1q1","prompt":"Pour 40 analystes scannant des historiques multi-années, l’option la plus adaptée est :","kind":"mcq","options":["Cloud SQL seul","BigQuery (entrepôt)","CSV sur laptop","Redis"],"accept":["BigQuery (entrepôt)"],"explanation":"BigQuery est conçu pour l’analytique à large scan ; Cloud SQL sature vite sous reporting concurrent."},{"id":"c1q2","prompt":"Les 4 sections minimales d’un ADR (séparées par des virgules) :","kind":"short","accept":["contexte, options, décision, conséquences","contexte, options, decision, consequences"],"explanation":"ADR standard : Contexte → Options → Décision → Conséquences (positives et négatives)."}],"modelSolution":"Décision type : Cloud SQL = source OLTP ; BigQuery = mart analytique. Conséquences : + perf analytique, + coût scan à maîtriser (partition/cluster) ; − latence near-real-time si batch uniquement."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'conf-runbook-2', 'fr', 3, '{"id":"conf-runbook-2","tool":"confluence","level":2,"title":"Runbook incident — pipeline finance en retard","context":"Le DAG finance a 3 incidents « late » ce mois. Les ops demandent un runbook Confluence actionnable à 3 h du matin.","description":"Tu rédiges un runbook de diagnostic et remédiation pour un pipeline batch en retard.","tasks":["Définir symptômes, checks, actions, escalade","Inclure les liens Airflow / BQ / alerting","Prévoir un critère de fin d’incident"],"trap":"Sans ordre de checks (Airflow → GCS → BQ), l’astreinte refactorise dbt à 3 h du matin au lieu de relancer la bonne tâche.","steps":[{"title":"Structure","detail":"Symptômes → Vérifications (ordre) → Actions immédiates → Rollback → Escalade → Post-mortem."},{"title":"Checks","detail":"1) DAG state Airflow 2) Sensor fichier GCS 3) Slot/erreurs BQ 4) Volume vs J-1 5) Alerte fausse positive."},{"title":"Done incident","detail":"Données J disponibles avant SLA métier + alerte résolue + ticket Jira créé pour cause racine."}],"questions":[{"id":"c2q1","prompt":"Première vérif utile quand un batch est « late » :","kind":"mcq","options":["Réécrire tout le modèle dbt","État du DAG / tâche en échec","Changer le KPI métier","Supprimer le partitionnement"],"accept":["État du DAG / tâche en échec"],"explanation":"On commence par localiser où ça bloque (orchestrateur), pas par refactorer le modèle."},{"id":"c2q2","prompt":"Un runbook doit toujours inclure (un mot) :","kind":"short","accept":["escalade","rollback","symptômes","symptomes","checks"],"explanation":"Sans escalade / critères de fin / checks ordonnés, le runbook n’est pas opérable la nuit."}],"modelSolution":"Runbook : Symptômes (SLA manqué) → Checks Airflow/GCS/BQ → Relance ciblée ou skip sensor si fichier OK → Escalade data eng on-call → Ticket RCA. Fin = données OK + alerte clear."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'jira-epic-1', 'fr', 4, '{"id":"jira-epic-1","tool":"jira","level":1,"title":"Découper l’epic « Mart clients »","context":"Epic Jira : « Livrer le mart clients pour le dashboard rétention ». L’équipe mélange analyse, dbt et Power BI dans une seule story.","description":"Tu découpes en stories INVEST avec critères d’acceptation testables et DoD data.","tasks":["Proposer 5 stories testables","Ajouter critères d’acceptation par story","Définir une Definition of Done data commune"],"trap":"Une seule story « livrer tout le mart » viole Small/Testable : impossible à demo ni à refuser proprement.","steps":[{"title":"Découpe verticale","detail":"Ex. : staging CRM → tests DQ → modèle dim_customer → mart rétention → dataset Power BI → UAT métier."},{"title":"INVEST","detail":"Independent, Negotiable, Valuable, Estimable, Small, Testable. Une story = une démo possible."},{"title":"DoD data","detail":"Code review, tests dbt passent, doc/lineage à jour, données UAT validées, monitoring basique."}],"questions":[{"id":"j1q1","prompt":"Une story « Faire tout le mart clients » viole surtout quel critère INVEST ?","kind":"mcq","options":["Valuable","Small / Testable","Negotiable","Independent"],"accept":["Small / Testable"],"explanation":"Trop grosse = non Small, difficilement Testable en une itération."},{"id":"j1q2","prompt":"Sigle des critères de qualité d’une user story :","kind":"short","accept":["invest"],"explanation":"INVEST = Independent, Negotiable, Valuable, Estimable, Small, Testable."}],"modelSolution":"5 stories : 1) staging CRM + tests not_null/unique 2) dim_customer 3) fct_retention_daily 4) exposition BI 5) UAT KPI. DoD : tests verts, doc, review, UAT sign-off."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'jira-dod-2', 'fr', 5, '{"id":"jira-dod-2","tool":"jira","level":2,"title":"Definition of Done data & dépendances","context":"Deux équipes (ingestion et BI) se bloquent mutuellement. Les tickets n’expriment pas les dépendances.","description":"Tu renforces le DoD et le graphe de dépendances Jira pour fluidifier le flux.","tasks":["Écrire un DoD data en 5 bullets","Modéliser les liens « blocks / is blocked by »","Proposer un champ « Data contract » sur les stories d’interface"],"trap":"Sans liens « blocks / is blocked by », la BI démarre avant le mart et tout le monde « attend l’autre » en silence.","steps":[{"title":"DoD","detail":"Tests auto, qualité (seuils), documentation, droits d’accès, observabilité (alerte volume/nulls)."},{"title":"Dépendances","detail":"Story BI « is blocked by » mart dbt ; epic ingestion « blocks » exposition. Visible sur le board."},{"title":"Data contract","detail":"Schéma colonnes, SLA fraîcheur, owner — attaché au ticket d’interface entre équipes."}],"questions":[{"id":"j2q1","prompt":"Sans lien de dépendance Jira, le risque principal est :","kind":"mcq","options":["Trop de documentation","Travail parallèle sur une interface non prête","Trop de tests","Trop de KPI"],"accept":["Travail parallèle sur une interface non prête"],"explanation":"Les dépendances explicites évitent que la BI construise sur un mart encore instable."},{"id":"j2q2","prompt":"Élément typique d’un data contract (un mot : schéma / sla / owner) :","kind":"short","accept":["schéma","schema","sla","owner","fraîcheur","fraicheur"],"explanation":"Un contrat data fixe au minimum schéma, fraîcheur (SLA) et ownership."}],"modelSolution":"DoD : tests, seuils DQ, docs, IAM, alerte. Dépendances Jira visibles. Contracts sur tickets d’interface (schéma + SLA + owner)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-dupes-1', 'fr', 6, '{"id":"sql-dupes-1","tool":"sql","level":1,"title":"Détecter les doublons clients","context":"Le CRM contient des doublons (même email, sociétés orthographiées différemment). Le mart clients surestime le nombre de clients uniques.","description":"Tu écris une requête SQL de détection de doublons et un taux de duplication.","tasks":["Compter les groupes email en doublon","Calculer un taux de duplication","Traiter le cas des email NULL"],"trap":"Les sociétés ne sont pas orthographiées à l’identique (« Acme Retail » vs « ACME Retail », espaces en trop) — normalise avec LOWER/TRIM avant de conclure à un doublon sur le nom seul.","steps":[{"title":"CTE groupes","detail":"WITH d AS (SELECT lower(trim(email)) AS e, COUNT(*) c FROM clients GROUP BY 1 HAVING COUNT(*) > 1)"},{"title":"Taux","detail":"Taux ≈ (SUM(c) des doublons) / COUNT(*) total — ou % de lignes appartenant à un groupe > 1."},{"title":"NULL","detail":"Exclure email IS NULL du matching, ou les traiter à part (autre règle : SIRET + nom)."}],"questions":[{"id":"s1q1","prompt":"Clause SQL pour ne garder que les groupes avec plus d’une ligne :","kind":"mcq","options":["WHERE COUNT(*) > 1","HAVING COUNT(*) > 1","LIMIT 2","ORDER BY COUNT(*)"],"accept":["HAVING COUNT(*) > 1"],"explanation":"HAVING filtre après agrégation ; WHERE ne peut pas utiliser COUNT(*) ainsi."},{"id":"s1q2","prompt":"Mot-clé pour une sous-requête nommée réutilisable :","kind":"short","accept":["with","cte"],"explanation":"WITH … AS (…) définit une CTE (Common Table Expression)."},{"id":"s1q3","prompt":"Avant de matcher sur email, on applique souvent :","kind":"mcq","options":["LOWER + TRIM","MAX uniquement","DROP TABLE","FULL OUTER JOIN systématique"],"accept":["LOWER + TRIM"],"explanation":"Normaliser (casse, espaces) évite les faux « uniques »."}],"modelSolution":"WITH norm AS (\n  SELECT id, NULLIF(LOWER(TRIM(email)), '''') AS email_n\n  FROM clients\n),\ndup AS (\n  SELECT email_n, COUNT(*) AS c\n  FROM norm WHERE email_n IS NOT NULL\n  GROUP BY 1 HAVING COUNT(*) > 1\n)\nSELECT\n  (SELECT SUM(c) FROM dup) * 1.0 / (SELECT COUNT(*) FROM norm) AS duplicate_row_rate;"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-window-2', 'fr', 7, '{"id":"sql-window-2","tool":"sql","level":2,"title":"Window function — dernier statut par contrat","context":"Table `contract_events(contract_id, event_ts, status)`. Tu dois exposer le statut courant de chaque contrat.","description":"Tu utilises une fonction de fenêtrage pour dédupliquer sur le dernier événement.","tasks":["Écrire une requête avec ROW_NUMBER() PARTITION BY contract_id","Filtrer rn = 1","Expliquer pourquoi ORDER BY event_ts DESC"],"trap":"Sans ORDER BY event_ts DESC dans la fenêtre, ROW_NUMBER() te donne une ligne arbitraire — pas forcément le dernier statut.","steps":[{"title":"Partition","detail":"ROW_NUMBER() OVER (PARTITION BY contract_id ORDER BY event_ts DESC) AS rn"},{"title":"Filtre","detail":"Envelopper en CTE/sous-requête puis WHERE rn = 1."},{"title":"Égalité de timestamps","detail":"Ajouter une clé de tie-break (event_id) si deux events ont le même ts."}],"questions":[{"id":"s2q1","prompt":"Pour le « dernier » événement, ORDER BY event_ts doit être :","kind":"mcq","options":["ASC","DESC","Inutile","RANDOM"],"accept":["DESC"],"explanation":"DESC met le plus récent en rn = 1."},{"id":"s2q2","prompt":"Nom de la fonction qui numérote les lignes dans une partition :","kind":"short","accept":["row_number","row_number()","row number"],"explanation":"ROW_NUMBER() attribue 1..n dans chaque PARTITION."}],"modelSolution":"WITH ranked AS (\n  SELECT *, ROW_NUMBER() OVER (\n    PARTITION BY contract_id ORDER BY event_ts DESC, event_id DESC\n  ) AS rn\n  FROM contract_events\n)\nSELECT * FROM ranked WHERE rn = 1;"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-etl-1', 'fr', 8, '{"id":"py-etl-1","tool":"python","level":1,"title":"Script CSV → clean → Parquet","context":"Fichiers CSV quotidiens « landing » à nettoyer avant chargement BigQuery. Pas encore d’orchestrateur lourd.","description":"Tu conçois un script Python idempotent : lecture, validation schéma, écriture Parquet, logs d’erreur.","tasks":["Valider les colonnes attendues","Logger les lignes invalides sans faire planter tout le run","Écrire un output déterministe (même input → même output)"],"trap":"Un append aveugle sur le même fichier/partition du jour crée des doublons au rejeu — overwrite de la partition, pas append.","steps":[{"title":"Schéma","detail":"Définis EXPECTED_COLS ; si manquantes → fail fast. Types : parse dates, coerce numériques."},{"title":"Lignes sales","detail":"Sépare valid vs reject (fichier _rejects.csv + compteur). Ne silence pas les erreurs."},{"title":"Idempotence","detail":"Écris sous un chemin daté/partitionné ; overwrite de la partition du jour, pas append aveugle."}],"questions":[{"id":"p1q1","prompt":"Comportement sain si une colonne obligatoire manque :","kind":"mcq","options":["Ignorer et continuer","Fail fast avec message clair","Créer la colonne à null sans log","Supprimer le fichier source"],"accept":["Fail fast avec message clair"],"explanation":"Un schéma cassé = incident data. Mieux vaut échouer tôt que charger n’importe quoi."},{"id":"p1q2","prompt":"Mot décrivant « même input ⇒ même output / rejouable » :","kind":"short","accept":["idempotent","idempotence","déterministe","deterministe"],"explanation":"Idempotence / déterminisme : rejouer le job du jour ne duplique pas ni n’altère au hasard."}],"modelSolution":"read_csv → validate columns → type coerce → split rejects → to_parquet(partition date) overwrite → log metrics (rows_in, rows_out, rejects)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-test-2', 'fr', 9, '{"id":"py-test-2","tool":"python","level":2,"title":"Tests unitaires data (pandas)","context":"Une fonction `normalize_iban` est utilisée dans 3 pipelines. Un bug silencieux a corrompu des IBAN.","description":"Tu poses des tests unitaires ciblés sur les cas limites (espaces, casse, longueur).","tasks":["Lister 4 cas de test (happy path + edge)","Choisir assert sur sortie attendue","Décider fail vs reject pour entrée irrécupérable"],"trap":"Normaliser un IBAN invalide « pour que ça passe » corrompt 3 pipelines — better reject/raise que inventer.","steps":[{"title":"Cas","detail":"OK ; espaces internes ; lowercase ; trop court ; None/NaN ; caractères interdits."},{"title":"Policy","detail":"Normalisable → clean ; irrécupérable → raise ou flag reject selon contrat (ne pas « inventer »)."},{"title":"CI","detail":"pytest dans le pipeline ; bloquer le merge si tests data red."}],"questions":[{"id":"p2q1","prompt":"Un test unitaire data doit surtout vérifier :","kind":"mcq","options":["La couleur du dashboard","Des cas limites et la politique d’erreur","Le salaire de l’équipe","Le nom du bucket uniquement"],"accept":["Des cas limites et la politique d’erreur"],"explanation":"Les bugs data vivent dans les edge cases et le traitement des entrées invalides."},{"id":"p2q2","prompt":"Framework de test Python le plus courant ici :","kind":"short","accept":["pytest"],"explanation":"pytest est le standard de fait pour les tests unitaires Python."}],"modelSolution":"Tests : IBAN valide ; avec espaces → compacté ; lower → upper ; length != attendu → reject/raise ; None → reject. Branch CI rouge = pas de merge."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'gcs-layout-1', 'fr', 10, '{"id":"gcs-layout-1","tool":"gcs","level":1,"title":"Arborescence landing / raw / curated","context":"Nouveau projet GCP : fichiers partenaires quotidiens. Personne n’a standardisé les préfixes ni la rétention.","description":"Tu proposes une organisation de buckets/préfixes et une politique de lifecycle.","tasks":["Définir préfixes landing, raw, curated","Proposer rétention par zone","Appliquer le principe du moindre privilège IAM"],"trap":"Mélanger landing et curated dans le même préfixe sans dt= rend les sensors Airflow et la rétention impossibles à industrialiser.","steps":[{"title":"Zones","detail":"landing/ (drop tel quel) → raw/ (archivage immuable) → curated/ (fichiers prêts modèle)."},{"title":"Préfixe daté","detail":"…/dt=YYYY-MM-DD/… pour partitionner et rejouer un jour."},{"title":"Lifecycle","detail":"Landing courte (ex. 7–14 j) ; raw longue ; curated selon besoin mart. Nearline/Coldline si besoin."}],"questions":[{"id":"g1q1","prompt":"Zone où l’on dépose le fichier partenaire sans transformation :","kind":"mcq","options":["curated","landing","mart","serving"],"accept":["landing"],"explanation":"Landing = drop zone brute ; raw archive ; curated = prêt conso."},{"id":"g1q2","prompt":"Pattern de préfixe pour rejouer un jour (mot-clé) :","kind":"short","accept":["dt=","partition","date","dt","yyyy-mm-dd"],"explanation":"Un préfixe daté (ex. dt=2026-07-22/) permet rejeu et lifecycle ciblés."}],"modelSolution":"gs://proj-landing/partner/dt=… · gs://proj-raw/… rétention longue · gs://proj-curated/… IAM : writers landing ≠ readers BI curated."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'csql-incr-1', 'fr', 11, '{"id":"csql-incr-1","tool":"cloudsql","level":1,"title":"Extraction incrémentale (watermark)","context":"Une table OLTP `orders` (updated_at) doit être extraite chaque nuit vers GCS puis BigQuery, sans full scan quotidien.","description":"Tu conçois une extraction incrémentale basée sur un watermark, avec fenêtre de rejeu.","tasks":["Définir le watermark updated_at","Prévoir une fenêtre de lookback (late arriving)","Estimer l’impact charge sur l’instance"],"trap":"Sans fenêtre de lookback, les updates tardives (updated_at après le watermark) ne remontent jamais dans BigQuery.","steps":[{"title":"Watermark","detail":"Stocker last_success_ts ; SELECT * WHERE updated_at >= last_success_ts - lookback."},{"title":"Lookback","detail":"Ex. 2–3 jours pour rattraper les updates tardives ; fusion (merge) en aval sur clé primaire."},{"title":"Charge","detail":"Index sur updated_at ; extractions hors pic ; éviter SELECT * massif sans filtre."}],"questions":[{"id":"cs1q1","prompt":"Colonne typique pour l’incrémental :","kind":"mcq","options":["updated_at","couleur_ui","nom_fichier_pdf","random_uuid uniquement"],"accept":["updated_at"],"explanation":"updated_at (ou équivalent) permet de ne lire que le delta depuis le dernier succès."},{"id":"cs1q2","prompt":"Nom de la borne temporelle mémorisée entre deux runs :","kind":"short","accept":["watermark","curseur","cursor","high water mark","highwatermark"],"explanation":"Le watermark (high-water mark) mémorise jusqu’où l’extraction a progressé."}],"modelSolution":"Watermark last_ts + lookback 48–72h → extract → fichiers dt= → merge BQ sur order_id. Index(updated_at). Monitor rows_extracted vs baseline."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'bq-part-1', 'fr', 12, '{"id":"bq-part-1","tool":"bigquery","level":1,"title":"Partitionner et clustériser events","context":"Table `events` (event_date, user_id, event_name) coûte trop cher : les requêtes scannent toute l’historique.","description":"Tu choisis partitionnement et clustering pour réduire les bytes scannés.","tasks":["Choisir la partition (DAY sur event_date)","Choisir le clustering (user_id / event_name)","Estimer l’effet sur le coût d’une requête filtrée sur 7 jours"],"trap":"Un CAST/FORMAT sur la colonne de partition dans le WHERE empêche le pruning → tu rescannes toute l’historique.","steps":[{"title":"Partition","detail":"PARTITION BY DATE(event_date) ou colonne DATE — filtre date = partition prune."},{"title":"Cluster","detail":"CLUSTER BY user_id, event_name pour accélérer les filtres/joins fréquents intra-partition."},{"title":"Coût","detail":"Requêter 7 jours sur 2 ans ≪ full table si le filtre date est bien poussé (pas de wrap qui empêche le prune)."}],"questions":[{"id":"b1q1","prompt":"Pour des events temporels, partition typique :","kind":"mcq","options":["DAY sur la date d’événement","Par nom de dashboard","Par couleur","Aucune"],"accept":["DAY sur la date d’événement"],"explanation":"Partition DAY + filtre date = prune = moins de bytes facturés."},{"id":"b1q2","prompt":"Mot pour « n’ouvrir que les partitions utiles » :","kind":"short","accept":["prune","pruning","partition prune","partition pruning"],"explanation":"Le partition pruning évite de scanner les partitions hors filtre."}],"modelSolution":"CREATE TABLE … PARTITION BY event_date CLUSTER BY user_id, event_name. Toujours filtrer event_date. Vérifier bytes processed dans Job History."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'bq-cost-2', 'fr', 13, '{"id":"bq-cost-2","tool":"bigquery","level":2,"title":"Maîtriser le coût d’une requête","context":"Un dashboard Looker lance un SELECT * sur 3 ans à chaque ouverture. Facture BQ en hausse.","description":"Tu proposes 3 leviers concrets pour réduire le coût sans perdre le besoin métier.","tasks":["Remplacer SELECT *","Matérialiser un agrégat / table summary","Restreindre la fenêtre temporelle par défaut"],"trap":"Un SELECT * sur 3 ans à chaque ouverture de dashboard Looker fait exploser la facture — filtre date + agrégat d’abord.","steps":[{"title":"Colonnes","detail":"Projeter uniquement les colonnes utiles ; éviter SELECT *."},{"title":"Pré-agrégation","detail":"Table daily_stats mise à jour par dbt ; le dashboard lit l’agrégat."},{"title":"Défaut UI","detail":"Filtre date = 30 derniers jours par défaut ; 3 ans en opt-in."}],"questions":[{"id":"b2q1","prompt":"Levier n°1 anti-coût sur un dashboard :","kind":"mcq","options":["SELECT * sur tout l’historique","Filtre date + colonnes utiles / agrégat","Désactiver le partitionnement","Dupliquer la table 10 fois"],"accept":["Filtre date + colonnes utiles / agrégat"],"explanation":"Moins de bytes scannés = moins de coût on-demand (et moins de latence)."},{"id":"b2q2","prompt":"Ce que BigQuery facture principalement en on-demand (idée) :","kind":"short","accept":["bytes","données scannées","data scanned","scan","octets","tb"],"explanation":"Modèle on-demand ≈ volume de données scannées (bytes processed)."}],"modelSolution":"Stop SELECT * · partition prune · table agrégée dbt · filtre 30j défaut · monitorer slots/bytes dans INFORMATION_SCHEMA / Job history."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'dbt-layers-1', 'fr', 14, '{"id":"dbt-layers-1","tool":"dbt","level":1,"title":"Staging → intermediate → mart (active_users)","context":"Besoin d’un mart `active_users` pour la rétention. Aujourd’hui des SQL ad hoc non versionnés.","description":"Tu poses les couches dbt, naming, tests et documentation minimale.","tasks":["Nommer staging / intermediate / mart","Ajouter tests unique / not_null sur la clé","Documenter le modèle mart"],"trap":"Mettre la logique métier directement dans le staging casse la règle 1:1 source et rend les tests/reuse impossibles.","steps":[{"title":"Couches","detail":"stg_app__users (clean 1:1 source) → int_users_activity → mart_active_users (conso BI)."},{"title":"Tests","detail":"unique + not_null sur user_id dans le mart ; relations si FK."},{"title":"Docs","detail":"description + columns dans schema.yml ; dbt docs generate."}],"questions":[{"id":"d1q1","prompt":"Couche 1:1 avec la source, nettoyage léger :","kind":"mcq","options":["mart","staging","exposition Power BI","landing GCS"],"accept":["staging"],"explanation":"Staging = miroir propre de la source ; mart = modèle métier conso."},{"id":"d1q2","prompt":"Deux tests dbt de base sur une clé primaire (séparés par /) :","kind":"short","accept":["unique/not_null","not_null/unique","unique / not_null"],"explanation":"unique et not_null sont le socle de confiance sur une PK."}],"modelSolution":"stg_ → int_ → fct_/dim_ ou mart_ · tests unique/not_null · schema.yml documenté · CI dbt build sur PR."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'dbt-tests-2', 'fr', 15, '{"id":"dbt-tests-2","tool":"dbt","level":2,"title":"Tests de qualité et seuils","context":"Le mart finance a passé un `dbt run` vert mais le KPI CA est faux (doublons de factures).","description":"Tu renforces les tests au-delà du simple not_null pour capturer les régressions métier.","tasks":["Ajouter un test d’unicité composite (invoice_id + line_id)","Proposer un test de volumétrie (row count vs J-1)","Décider warn vs error sur le seuil"],"trap":"Un `dbt run` vert ne garantit rien sur le KPI : sans test d’unicité métier, les doublons de factures passent inaperçus.","steps":[{"title":"Unicité métier","detail":"unique combination of columns — pas seulement une colonne technique."},{"title":"Volumétrie","detail":"dbt_utils / custom test : |rows_today - rows_yesterday| / rows_yesterday < 20%."},{"title":"Sévérité","detail":"Error bloque le merge/prod ; warn alerte sans stopper si bruit connu."}],"questions":[{"id":"d2q1","prompt":"Un `dbt run` réussi garantit-il la justesse du KPI métier ?","kind":"mcq","options":["Oui toujours","Non — il faut des tests/assertions métier","Oui si SQL compile","Oui si pas de warning"],"accept":["Non — il faut des tests/assertions métier"],"explanation":"Run = modèles construits. La justesse KPI demande tests d’unicité, seuils, réconciliations."},{"id":"d2q2","prompt":"Sévérité qui doit bloquer la prod sur doublons de factures :","kind":"short","accept":["error","erreur","fail"],"explanation":"Doublons finance = error, pas un simple warn cosmétique."}],"modelSolution":"unique(invoice_id, line_id) error · réconciliation CA vs source · volumétrie warn/error selon contrat · CI dbt test obligatoire."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'spark-skew-1', 'fr', 16, '{"id":"spark-skew-1","tool":"spark","level":2,"title":"Join skew — stratégie de repartition","context":"Un join clients×transactions timeout : une clé « client_id = 0 / unknown » concentre 40 % des lignes (data skew).","description":"Tu choisis une stratégie anti-skew (salting ou broadcast) et tu justifie le choix.","tasks":["Diagnostiquer le skew (skew hint / Spark UI)","Proposer salting OU broadcast selon tailles","Fixer un nombre de partitions cohérent"],"trap":"La clé « client_id = 0 / unknown » peut concentrer 40 % des lignes — un join naïf timeout alors que le reste du cluster a l’air idle.","steps":[{"title":"Diag","detail":"Spark UI : tâches très longues sur peu de partitions ; compter top clés."},{"title":"Broadcast","detail":"Si une table est petite → broadcast join (évite shuffle massif)."},{"title":"Salting","detail":"Sinon : ajouter un sel sur les hot keys pour éclater la partition, puis agrégation finale."}],"questions":[{"id":"sp1q1","prompt":"Si la table dimension est petite, stratégie préférée :","kind":"mcq","options":["Broadcast join","Cross join cartésien","Collect sur le driver de tout","Désactiver le parallélisme"],"accept":["Broadcast join"],"explanation":"Broadcast évite de shuffler la grande table quand la petite tient en mémoire."},{"id":"sp1q2","prompt":"Technique pour éclater une clé trop chaude :","kind":"short","accept":["salting","salt","salage","repartition"],"explanation":"Le salting (sel) disperse les hot keys sur plusieurs partitions."}],"modelSolution":"Diag UI → si dim petite : broadcast → sinon salt hot keys → repartition(n) raisonnable → re-test runtime + shuffle bytes."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'dbs-job-1', 'fr', 17, '{"id":"dbs-job-1","tool":"databricks","level":2,"title":"Job multi-task : ingest → transform → DQ gate","context":"Passage d’un notebook manuel à un Job Databricks industriel pour le lac transactions.","description":"Tu conçois un job multi-task avec dépendances, policy cluster et chemin d’échec.","tasks":["Enchaîner ingest → transform → DQ","Bloquer l’aval si DQ échoue","Définir cluster policy / retry"],"trap":"Publier en gold alors que la DQ gate a échoué empoisonne tous les dashboards aval — le job doit stopper et alerter.","steps":[{"title":"Tasks","detail":"Task A ingest bronze → B silver transform depends_on A → C DQ gate depends_on B."},{"title":"DQ gate","detail":"Si checks fail → fail job (pas de publish gold) + alerte."},{"title":"Ops","detail":"Cluster policy (coût), retries sur A/B, timeout, run_if pour branches."}],"questions":[{"id":"db1q1","prompt":"Si le DQ gate échoue, le comportement attendu est :","kind":"mcq","options":["Publier quand même en gold","Stopper / ne pas publier et alerter","Ignorer silencieusement","Supprimer le bronze"],"accept":["Stopper / ne pas publier et alerter"],"explanation":"La gate DQ protège les consommateurs : pas de gold pourri."},{"id":"db1q2","prompt":"Mot pour la couche « données brutes ingérées » en lakehouse :","kind":"short","accept":["bronze","raw"],"explanation":"Medallion : Bronze (raw) → Silver → Gold."}],"modelSolution":"Job : Bronze ingest → Silver transform → DQ task (fail = stop) → Gold. Policy cluster, retries, alerte Slack/email sur fail."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'af-dag-1', 'fr', 18, '{"id":"af-dag-1","tool":"airflow","level":1,"title":"DAG quotidien : sensor → dbt → alerte","context":"Fichier partenaire attendu chaque matin 6h sur GCS ; puis dbt run ; alerte si SLA 8h dépassée.","description":"Tu conçois le squelette du DAG : schedule, sensor, dbt, retries, SLA.","tasks":["Choisir un schedule_interval","Ajouter un FileSensor (ou équivalent)","Configurer retries + alerte on_failure"],"trap":"Lancer dbt sans FileSensor sur le fichier 6h = run à vide ou sur J-1, puis fausse alerte SLA à 8h.","steps":[{"title":"Schedule","detail":"Ex. 0 6 * * * (cron) ou timetable ; timezone explicite."},{"title":"Sensor","detail":"Sensor GCS avec timeout/poke ; en échec → pas de dbt aval."},{"title":"Résilience","detail":"retries=2, retry_delay, email/Slack on_failure, sla_miss_callback si besoin."}],"questions":[{"id":"a1q1","prompt":"Rôle du FileSensor avant dbt :","kind":"mcq","options":["Remplacer dbt","Attendre la disponibilité du fichier source","Créer le dashboard","Gérer DataGalaxy"],"accept":["Attendre la disponibilité du fichier source"],"explanation":"Le sensor évite de lancer dbt sur une absence de fichier."},{"id":"a1q2","prompt":"Paramètre Airflow pour rejouer une tâche en échec (nom) :","kind":"short","accept":["retries","retry"],"explanation":"retries (+ retry_delay) gère les erreurs transitoires."}],"modelSolution":"DAG 06:00 → GCS sensor (timeout) → dbt build → notify success. on_failure alerte. SLA 08:00 métier. Retries sur tâches I/O."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'col-kpi-1', 'fr', 19, '{"id":"col-kpi-1","tool":"datagalaxy","level":1,"title":"Fiche asset KPI « churn »","context":"Deux départements calculent le churn différemment. Le COMEX veut une définition certifiée.","description":"Tu crées / complètes l’asset DataGalaxy du KPI churn : définition, owner, lien technique.","tasks":["Rédiger une définition métier non ambiguë","Nommer owner et steward","Lier l’asset au modèle technique (table/colonne)"],"trap":"Deux churns « certifiés » sans la même fenêtre (30j vs 90j) et sans lien table = COMEX qui compare des choux et des carottes.","steps":[{"title":"Définition","detail":"Formule, population, fenêtre temporelle, exclusions. Ex. « % clients actifs J-90 sans renouvellement sur 30j »."},{"title":"Ownership","detail":"Business owner (métier) + technical steward (data)."},{"title":"Lien technique","detail":"Pointer mart + colonne / rapport certifié ; statut « Certified » après validation."}],"questions":[{"id":"co1q1","prompt":"Sans lien technique, le risque DataGalaxy est :","kind":"mcq","options":["Définition orpheline / non implémentable","Trop de performance SQL","Trop de partitions BQ","Aucun"],"accept":["Définition orpheline / non implémentable"],"explanation":"Le glossaire doit pointer vers l’implémentation, sinon chacun recalcule « à sa façon »."},{"id":"co1q2","prompt":"Rôle métier responsable du sens du KPI (mot) :","kind":"short","accept":["owner","business owner","propriétaire"],"explanation":"Le business owner valide la définition ; le steward gère le cycle de vie data."}],"modelSolution":"Asset KPI churn : définition datée + population + formule · Owner métier · Steward data · Lien mart_churn.churn_rate · Statut Certified après comité."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'pbi-star-1', 'fr', 20, '{"id":"pbi-star-1","tool":"powerbi","level":1,"title":"Star schema ventes + mesure Marge %","context":"Le métier veut un rapport ventes. Aujourd’hui un export plat Excel à 40 colonnes est importé tel quel dans Power BI.","description":"Tu poses un modèle en étoile (fait + dimensions) et une mesure DAX de marge.","tasks":["Identifier table de faits et dimensions","Poser les relations (* → 1)","Écrire la mesure Marge %"],"trap":"Importer l’Excel plat à 40 colonnes tel quel crée des relations many-to-many et des totaux doublés — pose un vrai schéma en étoile.","steps":[{"title":"Faits","detail":"FactVentes : date_key, produit_key, client_key, montant_ht, coût."},{"title":"Dimensions","detail":"DimDate, DimProduit, DimClient — relations many-to-one vers le fait."},{"title":"Mesure","detail":"Marge % = DIVIDE( SUM(montant_ht - coût), SUM(montant_ht) )."}],"questions":[{"id":"pb1q1","prompt":"Dans un star schema, la table centrale des mesures est :","kind":"mcq","options":["Dimension","Fait (fact)","Glossaire DataGalaxy","Bucket GCS"],"accept":["Fait (fact)"],"explanation":"La table de faits porte les métriques ; les dimensions contextualisent."},{"id":"pb1q2","prompt":"Fonction DAX sûre pour une division (évite div/0) :","kind":"short","accept":["divide","divide()"],"explanation":"DIVIDE(num, den) gère le dénominateur nul proprement."}],"modelSolution":"FactVentes + DimDate/Produit/Client · relations *→1 · Marge% = DIVIDE(SUM(HT-coût), SUM(HT)) · pas de table plate Excel."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'looker-report-1', 'fr', 21, '{"id":"looker-report-1","tool":"looker","level":1,"title":"Rapport hebdo ops branché BigQuery","context":"Les ops veulent chaque lundi un rapport simple : volume pipelines, retard SLA, top erreurs — sans installer Power BI.","description":"Tu branches Looker Studio sur BigQuery avec filtre date et partage viewer.","tasks":["Connecter une table/vue BQ agrégée","Ajouter un filtre période (semaine)","Partager en mode lecteur"],"trap":"Brancher Looker sur la table brute non agrégée rescane BigQuery à chaque ouverture — préfère une vue daily déjà résumée.","steps":[{"title":"Source","detail":"Préférer une vue/table déjà agrégée (coût) ; connecteur BigQuery dans Looker Studio."},{"title":"Filtre","detail":"Contrôle date range ; défaut = semaine glissante."},{"title":"Partage","detail":"Viewer pour ops ; édition limitée aux data owners."}],"questions":[{"id":"l1q1","prompt":"Pour limiter le coût BQ depuis Looker Studio :","kind":"mcq","options":["Pointer une table/vue agrégée + filtre date","SELECT * sur 5 ans à chaque refresh","Désactiver les filtres","Dupliquer les sources"],"accept":["Pointer une table/vue agrégée + filtre date"],"explanation":"Looker Studio déclenche des jobs BQ : agrégats + filtres = moins de scan."},{"id":"l1q2","prompt":"Mode de partage pour lecture seule ops :","kind":"short","accept":["viewer","lecteur","reader","view"],"explanation":"Partage viewer / lecteur = consultation sans modifier le rapport."}],"modelSolution":"Source = vue BQ hebdo agrégée · filtre date défaut 7j · graphiques volume/SLA/erreurs · partage Viewer ops · owner data en Editor."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-cte-3', 'fr', 22, '{"id":"sql-cte-3","tool":"sql","level":3,"title":"CTE — CA livré puis top magasins","context":"Mutualis veut un top 3 magasins sur le CA livré (ventes_semaine) sans sous-requête illisible.","description":"Tu écris une CTE qui agrège le CA, puis tu filtres le top.","tasks":["WITH ca AS (SUM montant_ht WHERE livree GROUP BY magasin)","SELECT top 3 ORDER BY ca DESC","Commenter le grain"],"trap":"ORDER BY sans LIMIT (ou QUALIFY) renvoie tout — le « top » n’est pas garanti côté conso.","steps":[{"title":"CTE","detail":"WITH ca AS (SELECT magasin, SUM(montant_ht) AS ca_ht FROM ventes WHERE statut = ''livree'' GROUP BY 1)"},{"title":"Top","detail":"SELECT * FROM ca ORDER BY ca_ht DESC LIMIT 3"}],"questions":[{"id":"s3q1","prompt":"Mot-clé SQL pour factoriser une sous-requête nommée :","kind":"short","accept":["with","cte"],"explanation":"WITH … AS (…) = Common Table Expression."},{"id":"s3q2","prompt":"Filtrer statut livree se fait avec :","kind":"mcq","options":["WHERE","HAVING uniquement","ORDER BY","UNION"],"accept":["WHERE"],"explanation":"WHERE filtre les lignes avant agrégation ; HAVING après."}],"modelSolution":"```sql\nWITH ca AS (\n  SELECT magasin, SUM(montant_ht) AS ca_ht\n  FROM ventes_semaine\n  WHERE statut = ''livree''\n  GROUP BY magasin\n)\nSELECT * FROM ca ORDER BY ca_ht DESC LIMIT 3;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-null-4', 'fr', 23, '{"id":"sql-null-4","tool":"sql","level":2,"title":"NULL-safe — COALESCE / NULLIF emails","context":"Le CRM Mutualis mélange NULL, chaînes vides et « unknown ».","description":"Tu normalises les emails en SQL avant dédoublonnage.","tasks":["NULLIF(TRIM(email), '''')","COALESCE / filtre unknown","GROUP BY email normalisé"],"trap":"TRIM seul ne transforme pas NULL — et '''' <> NULL en SQL.","steps":[{"title":"Normaliser","detail":"LOWER(TRIM(email)) puis NULLIF(..., '''')"},{"title":"Exclure","detail":"WHERE email_n IS NOT NULL AND email_n <> ''unknown''"}],"questions":[{"id":"s4q1","prompt":"NULLIF(x, '''') renvoie NULL si x est :","kind":"mcq","options":["chaîne vide","toujours NULL","0","unknown"],"accept":["chaîne vide"],"explanation":"NULLIF(a,b) → NULL quand a = b."}],"modelSolution":"```sql\nSELECT LOWER(TRIM(email)) AS email_n, COUNT(*)\nFROM clients_doublons\nWHERE NULLIF(LOWER(TRIM(email)), '''') IS NOT NULL\n  AND LOWER(TRIM(email)) <> ''unknown''\nGROUP BY 1\nHAVING COUNT(*) > 1;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-groupby-3', 'fr', 24, '{"id":"py-groupby-3","tool":"python","level":2,"title":"pandas groupby — CA par magasin","context":"Même KPI que le SQL ventes, en pandas pour un notebook d’exploration.","description":"Tu filtres statut livree puis groupby magasin sum montant_ht.","tasks":["read_csv ventes_semaine","filtre statut == livree","groupby magasin montant_ht sum"],"trap":"groupby sans filtre inclut les annulations et surestime le CA.","steps":[{"title":"Load","detail":"pd.read_csv(\"ventes_semaine.csv\")"},{"title":"Agg","detail":"df[df.statut==\"livree\"].groupby(\"magasin\")[\"montant_ht\"].sum()"}],"questions":[{"id":"p3q1","prompt":"Méthode pandas pour agréger après groupby :","kind":"short","accept":["sum",".sum","agg"],"explanation":"SeriesGroupBy.sum() ou .agg(\"sum\")."}],"modelSolution":"```python\nimport pandas as pd\ndf = pd.read_csv(\"ventes_semaine.csv\")\nprint(df[df[\"statut\"] == \"livree\"].groupby(\"magasin\")[\"montant_ht\"].sum().sort_values(ascending=False))\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-json-normalize-4', 'fr', 25, '{"id":"py-json-normalize-4","tool":"python","level":3,"title":"json + pandas — aplatir une fiche machine","context":"drill_machine.json arrive brut ; le mart attend des colonnes plates.","description":"Tu charges le JSON et produis un DataFrame 1 ligne (machine_id, status, region).","tasks":["json.load","Construire un dict plat (location.region)","pd.DataFrame([row])"],"trap":"pd.read_json sur un objet unique (pas un array) peut surprendre — json.load + DataFrame est plus sûr ici.","steps":[{"title":"Parse","detail":"data = json.load(f)"},{"title":"Flat","detail":"row = {\"machine_id\": data[\"machine_id\"], \"region\": data[\"location\"][\"region\"]}"}],"questions":[{"id":"p4q1","prompt":"Accès à la région imbriquée :","kind":"short","accept":["location","[\"location\"]","[''location'']"],"explanation":"data[\"location\"][\"region\"]."}],"modelSolution":"```python\nimport json, pandas as pd\nwith open(\"drill_machine.json\", encoding=\"utf-8\") as f:\n    data = json.load(f)\nrow = {\n  \"machine_id\": data[\"machine_id\"],\n  \"status\": data[\"status\"],\n  \"region\": data[\"location\"][\"region\"],\n}\nprint(pd.DataFrame([row]))\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-anti-join-5', 'fr', 26, '{"id":"sql-anti-join-5","tool":"sql","level":3,"title":"Anti-join — clients sans commande","context":"Le CRM a des clients jamais présents dans ventes_semaine.","description":"Tu listes les client_id du référentiel absents des ventes (LEFT JOIN … IS NULL).","tasks":["LEFT JOIN ventes ON client_id","WHERE v.client_id IS NULL","Compter les orphelins"],"trap":"NOT IN avec des NULL côté ventes peut tout masquer — préfère LEFT JOIN / NOT EXISTS.","steps":[{"title":"Join","detail":"FROM clients_ref c LEFT JOIN ventes_semaine v ON c.client_id = v.client_id"},{"title":"Filtre","detail":"WHERE v.client_id IS NULL"}],"questions":[{"id":"s5q1","prompt":"Pattern anti-join courant :","kind":"mcq","options":["LEFT JOIN + IS NULL","INNER JOIN seul","CROSS JOIN","UNION ALL"],"accept":["LEFT JOIN + IS NULL"],"explanation":"LEFT JOIN puis IS NULL sur la clé droite = absents."}],"modelSolution":"```sql\nSELECT c.client_id, c.segment\nFROM clients_ref c\nLEFT JOIN ventes_semaine v ON c.client_id = v.client_id\nWHERE v.client_id IS NULL;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-assert-5', 'fr', 27, '{"id":"py-assert-5","tool":"python","level":3,"title":"Assertions data — garde-fous pandas","context":"Avant to_csv / load mart, tu veux faire échouer le job si la qualité casse.","description":"Tu ajoutes assert / raise sur schéma, nulls email, et effectif min.","tasks":["assert set(colonnes attendues) <= set(df.columns)","assert df[\"email\"].isna().mean() < 0.05","raise ValueError si len(actifs) < 100"],"trap":"Un assert désactivé avec python -O disparaît — en prod préfère raise ValueError explicite.","steps":[{"title":"Schéma","detail":"required = {\"email\",\"client_id\"}; assert required <= set(df.columns)"},{"title":"Volume","detail":"if len(actifs) < 100: raise ValueError(\"effectif trop bas\")"}],"questions":[{"id":"p5q1","prompt":"Pour un contrôle qualité fiable en prod, préférer :","kind":"mcq","options":["raise ValueError","print seulement","pass","input()"],"accept":["raise ValueError"],"explanation":"raise fait échouer le job ; print est silencieux pour l’orchestrateur."}],"modelSolution":"```python\nimport pandas as pd\ndf = pd.read_csv(\"clients_doublons.csv\")\nrequired = {\"email\"}\nif not required <= set(df.columns):\n    raise ValueError(\"colonnes manquantes\")\nif df[\"email\"].isna().mean() > 0.2:\n    raise ValueError(\"trop de NULL email\")\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-basics-filter-0', 'fr', 28, '{"id":"sql-basics-filter-0","tool":"sql","level":1,"title":"SELECT / WHERE — employés actifs SALES","context":"Mutualis RH veut l’effectif actif du département SALES à partir de retail_employees (SCD).","description":"Tu poses une requête de fondation : projection, filtres combinés, DISTINCT, COUNT.","tasks":["SELECT des colonnes utiles (pas SELECT *)","WHERE active_record = 1 AND department = …","COUNT + DISTINCT sur une clé métier si besoin"],"trap":"Oublier active_record = 1 mélange historique et actif — les effectifs explosent.","steps":[{"title":"Filtre","detail":"WHERE active_record = 1 AND UPPER(TRIM(department)) = ''SALES''"},{"title":"Comptage","detail":"COUNT(*) pour l’effectif ; COUNT(DISTINCT employee_id) si doute sur la grain."}],"questions":[{"id":"sb0q1","prompt":"Pour filtrer des lignes avant agrégation, on utilise :","kind":"mcq","options":["WHERE","HAVING","QUALIFY","LIMIT"],"accept":["WHERE"],"explanation":"WHERE filtre les lignes ; HAVING filtre les groupes."},{"id":"sb0q2","prompt":"Mot-clé pour supprimer les doublons de projection :","kind":"short","accept":["distinct"],"explanation":"SELECT DISTINCT … déduplique le résultat projeté."}],"modelSolution":"```sql\nSELECT employee_id, employee_name, department\nFROM retail_employees\nWHERE active_record = 1\n  AND UPPER(TRIM(department)) = ''SALES'';\n-- Effectif :\nSELECT COUNT(*) AS effectif_sales\nFROM retail_employees\nWHERE active_record = 1 AND UPPER(TRIM(department)) = ''SALES'';\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-case-having-1', 'fr', 29, '{"id":"sql-case-having-1","tool":"sql","level":2,"title":"CASE WHEN + HAVING — paniers moyens","context":"Le COMEX veut classer les magasins : panier moyen HT élevé / moyen / bas sur ventes livrées.","description":"Tu agrèges, filtres les groupes, et labels avec CASE WHEN.","tasks":["AVG(montant_ht) GROUP BY magasin","HAVING AVG(...) >= seuil métier","CASE WHEN pour bucketiser le panier"],"trap":"Mettre le filtre AVG dans WHERE échoue — l’agrégat vit après GROUP BY → HAVING (ou sous-requête).","steps":[{"title":"Agg","detail":"SELECT magasin, AVG(montant_ht) AS panier FROM ventes WHERE statut=''livree'' GROUP BY 1"},{"title":"Label","detail":"CASE WHEN panier >= 80 THEN ''élevé'' WHEN panier >= 40 THEN ''moyen'' ELSE ''bas'' END"}],"questions":[{"id":"sc1q1","prompt":"Filtrer sur AVG(montant) après GROUP BY :","kind":"mcq","options":["HAVING","WHERE AVG","ORDER BY seul","DISTINCT"],"accept":["HAVING"],"explanation":"HAVING s’applique aux agrégats / groupes."},{"id":"sc1q2","prompt":"Expression SQL pour des branches conditionnelles dans le SELECT :","kind":"short","accept":["case","case when"],"explanation":"CASE WHEN … THEN … ELSE … END."}],"modelSolution":"```sql\nSELECT\n  magasin,\n  AVG(montant_ht) AS panier,\n  CASE\n    WHEN AVG(montant_ht) >= 80 THEN ''eleve''\n    WHEN AVG(montant_ht) >= 40 THEN ''moyen''\n    ELSE ''bas''\n  END AS bucket\nFROM ventes_semaine\nWHERE statut = ''livree''\nGROUP BY magasin\nHAVING AVG(montant_ht) >= 20;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-joins-family-2', 'fr', 30, '{"id":"sql-joins-family-2","tool":"sql","level":2,"title":"INNER / LEFT / FULL — ventes × référentiel","context":"Tu réconcilies ventes_semaine avec un référentiel magasins (certains codes absents d’un côté).","description":"Tu choisis la bonne jointure selon la question métier (intersection, orphelins, couverture totale).","tasks":["INNER JOIN pour le CA des magasins connus","LEFT JOIN pour lister les ventes sans magasin référencé","Expliquer quand un FULL OUTER JOIN aide le DQ"],"trap":"CROSS JOIN sans filtre = produit cartésien explosif — jamais « pour voir ».","steps":[{"title":"INNER","detail":"v INNER JOIN dim_magasin m ON v.magasin = m.code → lignes appariées seulement."},{"title":"LEFT","detail":"v LEFT JOIN m … WHERE m.code IS NULL → ventes orphelines."},{"title":"FULL","detail":"FULL OUTER JOIN pour voir les deux côtés non matchés (DQ référentiel)."}],"questions":[{"id":"sj2q1","prompt":"Jointure qui ne garde que les clés présentes des deux côtés :","kind":"mcq","options":["INNER JOIN","LEFT JOIN","CROSS JOIN","UNION"],"accept":["INNER JOIN"],"explanation":"INNER = intersection des clés."},{"id":"sj2q2","prompt":"Jointure dangereuse sans prédicat (produit cartésien) :","kind":"short","accept":["cross","cross join"],"explanation":"CROSS JOIN multiplie toutes les lignes."}],"modelSolution":"```sql\n-- CA magasins connus\nSELECT m.code, SUM(v.montant_ht) AS ca\nFROM ventes_semaine v\nINNER JOIN dim_magasin m ON v.magasin = m.code\nWHERE v.statut = ''livree''\nGROUP BY 1;\n\n-- Ventes orphelines\nSELECT v.*\nFROM ventes_semaine v\nLEFT JOIN dim_magasin m ON v.magasin = m.code\nWHERE m.code IS NULL;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-window-lag-rank-3', 'fr', 31, '{"id":"sql-window-lag-rank-3","tool":"sql","level":3,"title":"LAG + RANK — évolution trafic capteur","context":"capteur_a_retail : tu compares visiteurs_count au jour précédent et tu ranks les jours les plus chargés.","description":"Tu combines LAG et RANK/DENSE_RANK sur une fenêtre temporelle.","tasks":["LAG(visiteurs_count) OVER (ORDER BY date)","Écart vs J-1","RANK ou DENSE_RANK des jours par trafic"],"trap":"RANK laisse des trous après égalité ; DENSE_RANK non — choisis selon le reporting COMEX.","steps":[{"title":"LAG","detail":"LAG(visiteurs_count) OVER (ORDER BY date) AS prev_j"},{"title":"Rank","detail":"DENSE_RANK() OVER (ORDER BY visiteurs_count DESC) AS rk"}],"questions":[{"id":"sw3q1","prompt":"Fonction window qui lit la valeur de la ligne précédente :","kind":"short","accept":["lag","lag()"],"explanation":"LAG(expr) OVER (ORDER BY …)."},{"id":"sw3q2","prompt":"Après deux 1ers ex æquo, RANK place le suivant à :","kind":"mcq","options":["3","2","1","0"],"accept":["3"],"explanation":"RANK saute : 1,1,3… ; DENSE_RANK ferait 1,1,2."}],"modelSolution":"```sql\nSELECT\n  date,\n  visiteurs_count,\n  LAG(visiteurs_count) OVER (ORDER BY date) AS prev_visiteurs,\n  visiteurs_count - LAG(visiteurs_count) OVER (ORDER BY date) AS delta,\n  DENSE_RANK() OVER (ORDER BY visiteurs_count DESC) AS rk\nFROM capteur_a_retail;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'sql-rollup-4', 'fr', 32, '{"id":"sql-rollup-4","tool":"sql","level":4,"title":"ROLLUP — sous-totaux magasin / semaine","context":"Finance veut un extract CA livré avec sous-totaux par magasin et un total général.","description":"Tu utilises ROLLUP (ou GROUPING SETS) pour éviter plusieurs UNION de totaux.","tasks":["SUM(montant_ht) GROUP BY ROLLUP (magasin, semaine)","Interpréter les lignes NULL = sous-total / total","Documenter le grain pour le lecteur BI"],"trap":"Sans expliquer les NULL de ROLLUP, le métier croit à des magasins « vides » — documente GROUPING() / labels.","steps":[{"title":"ROLLUP","detail":"GROUP BY ROLLUP (magasin, semaine) → détail + sous-totaux + total."},{"title":"Lecture","detail":"semaine NULL + magasin non NULL = total magasin ; les deux NULL = grand total."}],"questions":[{"id":"sr4q1","prompt":"ROLLUP sert surtout à produire :","kind":"mcq","options":["Des sous-totaux hiérarchiques","Des jointures","Des index","Des triggers"],"accept":["Des sous-totaux hiérarchiques"],"explanation":"ROLLUP / CUBE / GROUPING SETS = agrégats multi-niveaux."}],"modelSolution":"```sql\nSELECT\n  magasin,\n  semaine,\n  SUM(montant_ht) AS ca_ht\nFROM ventes_semaine\nWHERE statut = ''livree''\nGROUP BY ROLLUP (magasin, semaine)\nORDER BY magasin NULLS LAST, semaine NULLS LAST;\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-fundamentals-0', 'fr', 33, '{"id":"py-fundamentals-0","tool":"python","level":1,"title":"Types & f-strings — log d’un run Mutualis","context":"Tu journalises un run d’extract : magasin, nb lignes, durée en secondes.","description":"Tu manipules int/float/str, variables, et un message clair en f-string.","tasks":["Typer mentalement nb_lignes (int) vs duree_s (float)","Construire un message f\"…\" lisible ops","Normaliser un libellé magasin (strip / upper)"],"trap":"Concaténer avec + et des types mélangés plante (int+str) — f-strings ou str() explicite.","steps":[{"title":"Vars","detail":"magasin = \" lille \".strip().upper(); n = 1204; duree = 3.5"},{"title":"Log","detail":"print(f\"[{magasin}] rows={n} duration_s={duree:.1f}\")"}],"questions":[{"id":"pf0q1","prompt":"Syntaxe moderne de formatage de chaînes Python :","kind":"short","accept":["f-string","fstring","f-strings","f\""],"explanation":"Les f-strings (f\"…{var}…\") sont le standard lisible."},{"id":"pf0q2","prompt":"Type de 3.5 en Python :","kind":"mcq","options":["float","int","str","bool"],"accept":["float"],"explanation":"Un littéral avec point décimal est un float."}],"modelSolution":"```python\nmagasin = \" lille \".strip().upper()\nnb_lignes = 1204\nduree_s = 3.5\nprint(f\"[{magasin}] rows={nb_lignes} duration_s={duree_s:.1f}\")\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-collections-1', 'fr', 34, '{"id":"py-collections-1","tool":"python","level":1,"title":"Listes & dicts — mapping KPI Mutualis","context":"Le PO te donne une liste de magasins et un dict de objectifs CA.","description":"Tu structures les données en list/dict (et set pour dédoublonner).","tasks":["Liste ordonnée des magasins du lot","Dict magasin → objectif_ca","Set pour détecter un magasin en double dans la liste"],"trap":"Un dict avec clé dupliquée écrase silencieusement — détecte les doublons via set(len) vs len(list).","steps":[{"title":"Structures","detail":"magasins = [\"LILLE\", \"LYON\"]; objectifs = {\"LILLE\": 100_000}"},{"title":"DQ","detail":"if len(magasins) != len(set(magasins)): raise ValueError(\"doublon\")"}],"questions":[{"id":"pc1q1","prompt":"Structure clé → valeur idéale pour un mapping magasin/objectif :","kind":"mcq","options":["dict","tuple seul","set ordonné garanti","int"],"accept":["dict"],"explanation":"dict = association clé/valeur."},{"id":"pc1q2","prompt":"Collection sans doublons (ordre non garanti historiquement) :","kind":"short","accept":["set","ensemble"],"explanation":"set déduplique les éléments hashables."}],"modelSolution":"```python\nmagasins = [\"LILLE\", \"LYON\", \"LILLE\"]\nif len(magasins) != len(set(magasins)):\n    raise ValueError(\"magasin en double\")\nobjectifs = {\"LILLE\": 100_000, \"LYON\": 80_000}\nprint(objectifs.get(\"LILLE\"))\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-functions-hints-2', 'fr', 35, '{"id":"py-functions-hints-2","tool":"python","level":2,"title":"Fonctions + type hints — normalize_email","context":"Trois notebooks Mutualis recopient la même normalisation d’email. Tu industrialises.","description":"Tu crées une fonction typée, réutilisable, avec politique NULL / vide.","tasks":["def normalize_email(raw: str | None) -> str | None","strip / lower ; \"\" → None","Documenter en une ligne le contrat"],"trap":"Retourner \"\" et None selon l’humeur casse les jointures — un seul sens du manquant (None).","steps":[{"title":"Signature","detail":"Utilise type hints pour clarifier entrée/sortie (str | None)."},{"title":"Corps","detail":"if raw is None: return None; s = raw.strip().lower(); return s or None"}],"questions":[{"id":"ph2q1","prompt":"Les annotations de types Python s’appellent souvent :","kind":"short","accept":["type hints","type hint","hints","annotations"],"explanation":"Type hints = annotations de types (PEP 484)."},{"id":"ph2q2","prompt":"Mot-clé pour définir une fonction :","kind":"mcq","options":["def","func","lambda uniquement","class"],"accept":["def"],"explanation":"def nom(...): crée une fonction."}],"modelSolution":"```python\ndef normalize_email(raw: str | None) -> str | None:\n    \"\"\"Retourne un email normalisé ou None si manquant/vide.\"\"\"\n    if raw is None:\n        return None\n    s = raw.strip().lower()\n    return s or None\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-control-except-2', 'fr', 36, '{"id":"py-control-except-2","tool":"python","level":2,"title":"if / for / try — parse montant HT","context":"Un CSV ventes contient des montants parfois invalides (\"N/A\", None, \"12,5\").","description":"Tu boucles, branches, et captures les erreurs de conversion sans tuer tout le run.","tasks":["for row in rows","try/except ValueError sur float()","isinstance pour écarter les non-str / non-num déjà OK"],"trap":"except Exception trop large masque les bugs — except ValueError (ou TypeError) ciblé.","steps":[{"title":"Boucle","detail":"for raw in montants: …"},{"title":"Parse","detail":"try: float(str(raw).replace(\",\", \".\")) except ValueError: rejects.append(raw)"}],"questions":[{"id":"pe2q1","prompt":"Bloc pour intercepter une erreur de conversion :","kind":"mcq","options":["try / except","if / else seul","with / as","class / self"],"accept":["try / except"],"explanation":"try/except gère les exceptions runtime."},{"id":"pe2q2","prompt":"Fonction pour vérifier le type d’un objet :","kind":"short","accept":["isinstance","isinstance()"],"explanation":"isinstance(x, typ) → bool."}],"modelSolution":"```python\nparsed, rejects = [], []\nfor raw in montants:\n    if raw is None:\n        rejects.append(raw)\n        continue\n    try:\n        parsed.append(float(str(raw).replace(\",\", \".\")))\n    except ValueError:\n        rejects.append(raw)\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-comprehension-3', 'fr', 37, '{"id":"py-comprehension-3","tool":"python","level":3,"title":"List comprehension — IDs actifs","context":"À partir d’une liste de dicts employés, tu veux les employee_id actifs (active_record == 1).","description":"Tu remplaces une boucle verbose par une compréhension lisible.","tasks":["Comprehension avec if","Produire une list[int]","Comparer lisibilité vs boucle for"],"trap":"Une compréhension de 4 niveaux est illisible — repars sur une boucle / fonction nommée.","steps":[{"title":"Forme","detail":"[e[\"employee_id\"] for e in rows if e.get(\"active_record\") == 1]"}],"questions":[{"id":"pp3q1","prompt":"Constructeur compact [expr for x in it if cond] :","kind":"short","accept":["comprehension","list comprehension","listcomp"],"explanation":"List comprehension = forme compacte de boucle + filtre."}],"modelSolution":"```python\nactifs = [e[\"employee_id\"] for e in rows if e.get(\"active_record\") == 1]\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('practice_exercise', 'py-oop-light-3', 'fr', 38, '{"id":"py-oop-light-3","tool":"python","level":3,"title":"Classe légère — CsvCleaner","context":"Tu veux encapsuler schéma attendu + clean + compteur de rejects pour plusieurs fichiers Mutualis.","description":"Tu poses une petite classe (état + méthodes) sans sur-ingénierie.","tasks":["__init__ avec expected_cols","méthode clean(df) → df_ok","attribut rejects_count"],"trap":"Une hiérarchie ABC à 5 niveaux pour un CSV daily = overkill — classe simple d’abord.","steps":[{"title":"Classe","detail":"class CsvCleaner: def __init__(self, expected: set[str]): …"},{"title":"Méthode","detail":"def clean(self, df): vérifie colonnes, compte nulls, retourne df"}],"questions":[{"id":"po3q1","prompt":"Mot-clé pour définir une classe :","kind":"short","accept":["class"],"explanation":"class Nom: …"},{"id":"po3q2","prompt":"Premier argument conventionnel des méthodes d’instance :","kind":"mcq","options":["self","this","cls uniquement","cls obligatoire partout"],"accept":["self"],"explanation":"self référence l’instance (cls pour les classmethods)."}],"modelSolution":"```python\nclass CsvCleaner:\n    def __init__(self, expected: set[str]):\n        self.expected = expected\n        self.rejects_count = 0\n\n    def clean(self, df):\n        missing = self.expected - set(df.columns)\n        if missing:\n            raise ValueError(f\"missing {missing}\")\n        ok = df.dropna(subset=list(self.expected))\n        self.rejects_count = len(df) - len(ok)\n        return ok\n```"}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'jira', 'fr', 0, '{"toolId":"jira","platformLabel":"Atlassian Jira (Cloud Free)","freePath":true,"signupUrl":"https://www.atlassian.com/software/jira/free","signupLabel":"Créer un site Jira Free","accountSteps":["Ouvre la page Jira Free Atlassian et clique sur « Try it free » / « Get it free ».","Crée un compte Atlassian (e-mail) ou connecte-toi avec Google.","Choisis un nom de site (ex. mutualis-tonprenom) et le plan Free.","Crée un projet de type « Kanban » ou « Scrum » nommé Mutualis Retail."],"firstUseSteps":["Dans le projet, ouvre le board (Board / Backlog).","Crée une Epic « Lot data Mutualis » puis 2–3 Stories.","Renseigne Summary, Description, Acceptance Criteria sur une Story.","Déplace une carte de To Do → In Progress → Done pour voir le flux."],"taskSteps":["Crée le ticket demandé par la consigne (Epic/Story) avec AC testables.","Copie l’URL du ticket ou un export texte (clé + titre + AC) dans le livrable du jeu.","Note le lien Confluence si tu documentes aussi (sinon laisse vide)."],"withoutAccount":"Sans compte : rédige quand même la Story au format texte (Titre / AC / DoD) dans le pad du jeu — tu créeras le ticket Jira dès que le site Free est prêt."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'confluence', 'fr', 0, '{"toolId":"confluence","platformLabel":"Atlassian Confluence (Cloud Free)","freePath":true,"signupUrl":"https://www.atlassian.com/software/confluence/free","signupLabel":"Créer Confluence Free","accountSteps":["Si tu as déjà Jira Free, ajoute Confluence depuis ton site Atlassian (Apps).","Sinon inscris-toi sur Confluence Free avec le même e-mail Atlassian.","Crée un espace « Mutualis Data » (type Team ou Documentation)."],"firstUseSteps":["Crée une page « ADR — définition KPI » à partir d’un template vide.","Ajoute titres H1/H2, une table Owner / Steward, un lien vers un ticket Jira.","Publie la page (Publish) et copie l’URL."],"taskSteps":["Rédige la page demandée (ADR, runbook ou glossaire court).","Colle l’URL Confluence + un extrait (définition + Owner) dans le livrable."],"withoutAccount":"Sans compte : rédige la page en Markdown dans le pad (titres, Owner, définition). Tu la reporteras dans Confluence dès l’espace créé."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'sql', 'fr', 0, '{"toolId":"sql","platformLabel":"Databricks Free Edition (SQL) ou éditeur SQL local","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Créer Databricks Free Edition","accountSteps":["Va sur l’inscription Databricks Free Edition (plus de Community Edition).","Inscris-toi avec e-mail ou SSO (Google/Microsoft) — pas besoin de carte bancaire pour Free Edition.","Attends la création du workspace, puis connecte-toi."],"firstUseSteps":["Dans le workspace : New → Notebook (language SQL) ou SQL Editor.","Upload le CSV du jeu (Catalog / Volume / Upload) ou colle les données en table temporaire.","Exécute un `SELECT * FROM … LIMIT 10` pour vérifier que tu vois les lignes."],"taskSteps":["Écris et exécute la requête demandée dans Databricks (ou SQLite/DBeaver en local).","Quand le résultat est correct, copie le SQL dans le pad du jeu (livrable).","Ajoute en commentaire le grain et un contrôle COUNT si la consigne le demande."],"withoutAccount":"Sans Databricks : installe VS Code + extension SQL, ou utilise https://sqliteonline.com — télécharge le CSV du jeu, écris la requête, colle-la ici."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'python', 'fr', 0, '{"toolId":"python","platformLabel":"Databricks Free Edition (Python) ou Python local","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Créer Databricks Free Edition","accountSteps":["Crée un compte Databricks Free Edition (même compte que pour SQL si déjà fait).","Ouvre New → Notebook, language Python."],"firstUseSteps":["Dans une cellule : `print(\"hello\")` puis Run pour vérifier l’exécution.","Upload le fichier CSV du jeu ou utilise `spark.read.csv` / pandas selon la consigne.","Familiarise-toi avec Run All / Clear state."],"taskSteps":["Code le script demandé (lecture → transform → contrôle).","Exécute-le jusqu’à obtenir le résultat attendu.","Colle le code Python complet dans le pad du jeu."],"withoutAccount":"Sans Databricks : installe Python 3 + pandas (`pip install pandas`) ou Google Colab (compte Google). Colle ensuite le script ici."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'spark', 'fr', 0, '{"toolId":"spark","platformLabel":"Databricks Free Edition (PySpark)","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Créer Databricks Free Edition","accountSteps":["Inscris-toi à Databricks Free Edition si ce n’est pas déjà fait.","Crée un notebook Python — le runtime fournit Spark."],"firstUseSteps":["Vérifie Spark : `spark.version` dans une cellule.","Charge un petit CSV en DataFrame : `spark.read.option(\"header\", True).csv(...)`.","Utilise `.show()` et `.printSchema()` pour inspecter."],"taskSteps":["Implémente les transformations Spark demandées (filter, groupBy, join…).","Vérifie le résultat avec `.show()` / count.","Colle le code PySpark dans le pad du jeu."],"withoutAccount":"Sans compte cloud : tu peux écrire le code PySpark dans le pad (le jeu valide le livrable texte). Pour l’exécuter plus tard, Free Edition reste le chemin le plus simple."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'databricks', 'fr', 0, '{"toolId":"databricks","platformLabel":"Databricks Free Edition","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Créer Databricks Free Edition","accountSteps":["Inscris-toi sur Databricks Free Edition (signup Free Tier).","Valide ton e-mail et ouvre le workspace fourni.","Parcours le menu : Workspace, Catalog, Jobs (selon disponibilités Free Edition)."],"firstUseSteps":["Crée un dossier Mutualis dans Workspace.","Crée un notebook SQL et un notebook Python liés au même dataset d’essai.","Si Jobs est disponible : schedule un run simple du notebook."],"taskSteps":["Réalise la manip demandée (notebook, job, Delta / catalog selon consigne).","Documente en 3 lignes ce que tu as cliqué + colle le code / config dans le pad."],"withoutAccount":"Le jeu accepte un livrable texte décrivant l’enchaînement (screenshots optionnels). Crée le compte Free Edition dès que possible pour pratiquer vraiment."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'gcs', 'fr', 0, '{"toolId":"gcs","platformLabel":"Google Cloud Storage (essai GCP)","freePath":true,"signupUrl":"https://console.cloud.google.com/freetrial","signupLabel":"Ouvrir Google Cloud (essai / Free Tier)","accountSteps":["Crée un compte Google si besoin, puis ouvre Google Cloud Console.","Active l’essai gratuit (carte souvent demandée ; crédits offerts — surveille la facturation).","Crée un projet « mutualis-data-tonprenom ».","Active l’API Cloud Storage."],"firstUseSteps":["Menu Storage → Buckets → Create (région EU, nom unique).","Crée un préfixe `landing/dt=YYYY-MM-DD/`.","Upload un petit CSV de test et vérifie les permissions (pas public)."],"taskSteps":["Reproduis le path / upload demandé par la consigne.","Dans le livrable : chemin gs://… + classification + qui a accès."],"withoutAccount":"Sans GCP : simule le path (`gs://mutualis-landing/dt=2026-07-24/file.csv`) et décris IAM/rétention dans le pad. Tu le matérialiseras dès le projet GCP créé."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'cloudsql', 'fr', 0, '{"toolId":"cloudsql","platformLabel":"Google Cloud SQL (ou Postgres local)","freePath":true,"signupUrl":"https://console.cloud.google.com/sql","signupLabel":"Console Cloud SQL","accountSteps":["Avec un projet GCP actif, ouvre SQL → Create instance (Postgres, petite machine).","Attention coûts : arrête/supprime l’instance après l’exercice si tu n’en as plus besoin.","Alternative gratuite long terme : installe PostgreSQL en local (pas de carte bancaire)."],"firstUseSteps":["Note host, user, database après création (ou localhost en local).","Connecte-toi avec Cloud Shell / DBeaver / psql.","Crée une table et un `SELECT 1`."],"taskSteps":["Exécute le SQL demandé, exporte le script.","Colle le SQL + 1 ligne sur comment tu t’es connecté (Cloud SQL ou local)."],"withoutAccount":"Préfère Postgres local ou SQLite pour pratiquer sans facturation. Le livrable reste le script SQL collé ici."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'bigquery', 'fr', 0, '{"toolId":"bigquery","platformLabel":"BigQuery (sandbox / essai GCP)","freePath":true,"signupUrl":"https://console.cloud.google.com/bigquery","signupLabel":"Ouvrir BigQuery","accountSteps":["Dans ton projet GCP, ouvre BigQuery (sandbox possible avec quotas gratuits).","Crée un dataset `mutualis` (location EU)."],"firstUseSteps":["Crée une table depuis CSV (Upload) ou requête sur un public dataset pour tester.","Lance `SELECT current_date()` pour valider.","Regarde l’onglet Job history / estimation de bytes processed."],"taskSteps":["Écris la requête BigQuery demandée (STANDARD SQL).","Colle-la dans le pad ; mentionne dataset.table utilisés."],"withoutAccount":"Sans GCP : écris quand même le SQL BigQuery (syntaxe STANDARD) dans le pad. Tu l’exécuteras dès le dataset créé."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'looker', 'fr', 0, '{"toolId":"looker","platformLabel":"Looker Studio (gratuit, compte Google)","freePath":true,"signupUrl":"https://lookerstudio.google.com/","signupLabel":"Ouvrir Looker Studio","accountSteps":["Connecte-toi avec un compte Google sur lookerstudio.google.com.","Accepte les conditions — aucun paiement pour les rapports de base."],"firstUseSteps":["Create → Blank report.","Ajoute une source (Google Sheets upload CSV, ou BigQuery si déjà branché).","Pose un scorecard et un bar chart simples."],"taskSteps":["Construis la viz demandée, aligne le calcul sur ta définition KPI.","Partage en « Restricted » (pas public web) et colle le lien + description dans le pad."],"withoutAccount":"Sans Google : décris la viz (mesures, dimensions, filtres) et joins une maquette/screenshot locale si tu en as une."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'dbt', 'fr', 0, '{"toolId":"dbt","platformLabel":"dbt Cloud (Developer / trial) ou dbt Core local","freePath":true,"signupUrl":"https://www.getdbt.com/signup","signupLabel":"Créer un compte dbt","accountSteps":["Inscris-toi sur getdbt.com (Developer / trial selon l’offre du moment).","Alternative 100 % local : `pip install dbt-core dbt-bigquery` (ou dbt-duckdb) — pas de compte SaaS.","Crée un projet « mutualis » et branche une destination (BigQuery ou DuckDB)."],"firstUseSteps":["Initialise le projet (`dbt init` en local, ou wizard Cloud).","Crée `models/staging/stg_example.sql` avec un SELECT simple.","Lance `dbt run` puis `dbt test` sur un test not_null."],"taskSteps":["Écris le modèle + tests demandés.","Colle le SQL du modèle et la config YAML des tests dans le pad."],"withoutAccount":"Sans dbt Cloud : installe dbt Core + DuckDB en local, ou rédige le modèle SQL + tests YAML dans le pad (le jeu valide le texte)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'airflow', 'fr', 0, '{"toolId":"airflow","platformLabel":"Astro CLI / Airflow local (Docker) ou Astronomer trial","freePath":true,"signupUrl":"https://www.astronomer.io/docs/astro/cli/install-cli","signupLabel":"Doc Astro CLI (Airflow local)","accountSteps":["Option A (recommandée débutant) : installe Docker Desktop, puis Astro CLI, `astro dev init` + `astro dev start`.","Option B : compte Astronomer trial si proposé.","Option C : Composer GCP (plus lourd, coûts) — évite en premier essai."],"firstUseSteps":["Ouvre l’UI Airflow locale (souvent http://localhost:8080).","Repère DAGs, Graph, Logs.","Active le DAG exemple et regarde un run Success/Failed."],"taskSteps":["Écris le DAG Python demandé (schedule, task, sensor ou retry).","Colle le fichier DAG complet dans le pad du jeu.","Décris en 2 lignes ce que tu vois dans l’UI après un run (ou « non exécuté — code seul »)."],"withoutAccount":"Sans Docker : rédige quand même le DAG dans le pad. Tu l’exécuteras dès qu’Airflow local tourne."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'datagalaxy', 'fr', 0, '{"toolId":"datagalaxy","platformLabel":"DataGalaxy (essai) ou simulation catalogue","freePath":false,"signupUrl":"https://www.datagalaxy.com/","signupLabel":"Site DataGalaxy","accountSteps":["Crée un compte / demande une démo DataGalaxy (catalogue & glossaire data).","Sans accès immédiat : on simule le catalogue dans Confluence ou un tableur gouverné (même structure de fiche)."],"firstUseSteps":["Si tu as un environnement : crée un objet / terme « Employé actif ».","Renseigne définition, domaine, Owner, lien vers un asset technique.","Sinon : crée une page Confluence « Catalogue Mutualis » avec les mêmes champs."],"taskSteps":["Produis la fiche (terme, définition, Owner, lien technique).","Colle le contenu (ou URL DataGalaxy/Confluence) dans le pad."],"withoutAccount":"Cas normal en solo : simule DataGalaxy dans Confluence Free ou un Google Sheet « glossaire » avec colonnes Terme | Définition | Owner | Table. Le jeu valide ce livrable."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'powerbi', 'fr', 0, '{"toolId":"powerbi","platformLabel":"Power BI Desktop (gratuit) + compte Microsoft","freePath":true,"signupUrl":"https://www.microsoft.com/en-us/download/details.aspx?id=58494","signupLabel":"Télécharger Power BI Desktop","accountSteps":["Crée / utilise un compte Microsoft.","Installe Power BI Desktop (Windows) — gratuit pour créer des rapports.","Optionnel : Power BI Service (app.powerbi.com) pour publier (licence Free limitée)."],"firstUseSteps":["Ouvre Power BI Desktop → Get data → Text/CSV avec le fichier du jeu.","Passe en Model view : relations, types de colonnes.","Crée une page Report avec 1 carte KPI et 1 graphique."],"taskSteps":["Construis la viz demandée ; aligne la mesure sur la définition SQL/mart.","Exporte un PDF/PNG ou décris le modèle + joins une capture dans le livrable fichier du jeu."],"withoutAccount":"Sans Windows/Desktop : maquette la viz (mesure, filtres, grain) dans le pad + capture si tu utilises Looker Studio en remplacement temporaire."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'jira', 'en', 0, '{"toolId":"jira","platformLabel":"Atlassian Jira (Cloud Free)","freePath":true,"signupUrl":"https://www.atlassian.com/software/jira/free","signupLabel":"Create a Jira Free site","accountSteps":["Open Atlassian Jira Free and click “Try it free” / “Get it free”.","Create an Atlassian account (email) or sign in with Google.","Choose a site name (e.g. mutualis-yourname) and the Free plan.","Create a Kanban or Scrum project named Mutualis Retail."],"firstUseSteps":["Open the board (Board / Backlog).","Create an Epic “Mutualis data batch” then 2–3 Stories.","Fill Summary, Description, Acceptance Criteria on one Story.","Move a card To Do → In Progress → Done to see the flow."],"taskSteps":["Create the ticket required by the brief (Epic/Story) with testable AC.","Paste the ticket URL or a text export (key + title + AC) into the game deliverable.","Note the Confluence link if you also document (otherwise leave blank)."],"withoutAccount":"No account yet: still write the Story in text form (Title / AC / DoD) in the game pad — create the Jira ticket once Free is ready."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'confluence', 'en', 0, '{"toolId":"confluence","platformLabel":"Atlassian Confluence (Cloud Free)","freePath":true,"signupUrl":"https://www.atlassian.com/software/confluence/free","signupLabel":"Create Confluence Free","accountSteps":["If you already have Jira Free, add Confluence from your Atlassian site (Apps).","Otherwise sign up for Confluence Free with the same Atlassian email.","Create a “Mutualis Data” space (Team or Documentation)."],"firstUseSteps":["Create a page “ADR — KPI definition” from a blank template.","Add H1/H2 headings, an Owner / Steward table, a link to a Jira ticket.","Publish the page and copy the URL."],"taskSteps":["Write the requested page (ADR, runbook or short glossary).","Paste the Confluence URL + an excerpt (definition + Owner) into the deliverable."],"withoutAccount":"No account yet: write the page in Markdown in the pad (headings, Owner, definition). You will move it to Confluence once the space exists."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'sql', 'en', 0, '{"toolId":"sql","platformLabel":"Databricks Free Edition (SQL) or local SQL editor","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Create Databricks Free Edition","accountSteps":["Go to Databricks Free Edition sign-up (Community Edition is retired).","Sign up with email or SSO (Google/Microsoft) — no credit card for Free Edition.","Wait for the workspace, then sign in."],"firstUseSteps":["In the workspace: New → Notebook (SQL) or SQL Editor.","Upload the game CSV (Catalog / Volume / Upload) or load data into a temp table.","Run `SELECT * FROM … LIMIT 10` to confirm you see rows."],"taskSteps":["Write and run the requested query in Databricks (or SQLite/DBeaver locally).","When the result is correct, paste the SQL into the game pad.","Comment the grain and a COUNT check if the brief asks for it."],"withoutAccount":"No Databricks yet: install VS Code + SQL extension, or use https://sqliteonline.com — download the game CSV, write the query, paste it here."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'python', 'en', 0, '{"toolId":"python","platformLabel":"Databricks Free Edition (Python) or local Python","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Create Databricks Free Edition","accountSteps":["Create a Databricks Free Edition account (reuse the SQL one if already done).","Open New → Notebook, language Python."],"firstUseSteps":["In a cell: `print(\"hello\")` then Run to verify execution.","Upload the game CSV or use spark.read.csv / pandas as required.","Learn Run All / Clear state."],"taskSteps":["Code the requested script (read → transform → check).","Run it until you get the expected result.","Paste the full Python code into the game pad."],"withoutAccount":"No Databricks: install Python 3 + pandas (`pip install pandas`) or Google Colab. Then paste the script here."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'spark', 'en', 0, '{"toolId":"spark","platformLabel":"Databricks Free Edition (PySpark)","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Create Databricks Free Edition","accountSteps":["Sign up for Databricks Free Edition if not already done.","Create a Python notebook — the runtime provides Spark."],"firstUseSteps":["Check Spark: `spark.version` in a cell.","Load a small CSV into a DataFrame: `spark.read.option(\"header\", True).csv(...)`.","Use `.show()` and `.printSchema()` to inspect."],"taskSteps":["Implement the Spark transforms (filter, groupBy, join…).","Verify with `.show()` / count.","Paste the PySpark code into the game pad."],"withoutAccount":"No cloud account: write PySpark in the pad (the game validates the text). Free Edition is the easiest path to run it later."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'databricks', 'en', 0, '{"toolId":"databricks","platformLabel":"Databricks Free Edition","freePath":true,"signupUrl":"https://login.databricks.com/signup?provider=DB_FREE_TIER","signupLabel":"Create Databricks Free Edition","accountSteps":["Sign up for Databricks Free Edition.","Confirm your email and open the provided workspace.","Browse Workspace, Catalog, Jobs (as available on Free Edition)."],"firstUseSteps":["Create a Mutualis folder in Workspace.","Create one SQL and one Python notebook on the same sample dataset.","If Jobs is available: schedule a simple notebook run."],"taskSteps":["Perform the requested action (notebook, job, Delta / catalog as briefed).","Document in 3 lines what you clicked + paste code / config into the pad."],"withoutAccount":"The game accepts a text deliverable describing the flow (optional screenshots). Create Free Edition as soon as you can for real practice."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'gcs', 'en', 0, '{"toolId":"gcs","platformLabel":"Google Cloud Storage (GCP trial)","freePath":true,"signupUrl":"https://console.cloud.google.com/freetrial","signupLabel":"Open Google Cloud (trial / Free Tier)","accountSteps":["Create a Google account if needed, then open Google Cloud Console.","Start the free trial (card often required; watch billing).","Create a project “mutualis-data-yourname”.","Enable the Cloud Storage API."],"firstUseSteps":["Storage → Buckets → Create (EU region, unique name).","Create prefix `landing/dt=YYYY-MM-DD/`.","Upload a small test CSV and check permissions (not public)."],"taskSteps":["Reproduce the path / upload from the brief.","In the deliverable: gs://… path + classification + who has access."],"withoutAccount":"No GCP yet: simulate the path (`gs://mutualis-landing/dt=2026-07-24/file.csv`) and describe IAM/retention in the pad."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'cloudsql', 'en', 0, '{"toolId":"cloudsql","platformLabel":"Google Cloud SQL (or local Postgres)","freePath":true,"signupUrl":"https://console.cloud.google.com/sql","signupLabel":"Cloud SQL console","accountSteps":["With an active GCP project, open SQL → Create instance (Postgres, small machine).","Watch costs: stop/delete the instance after the exercise if unused.","Long-term free alternative: install PostgreSQL locally (no card)."],"firstUseSteps":["Note host, user, database after creation (or localhost).","Connect with Cloud Shell / DBeaver / psql.","Create a table and run `SELECT 1`."],"taskSteps":["Run the requested SQL, export the script.","Paste the SQL + one line on how you connected (Cloud SQL or local)."],"withoutAccount":"Prefer local Postgres or SQLite to practice without billing. The deliverable is still the SQL script pasted here."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'bigquery', 'en', 0, '{"toolId":"bigquery","platformLabel":"BigQuery (sandbox / GCP trial)","freePath":true,"signupUrl":"https://console.cloud.google.com/bigquery","signupLabel":"Open BigQuery","accountSteps":["In your GCP project, open BigQuery (sandbox may offer free quotas).","Create a `mutualis` dataset (EU location)."],"firstUseSteps":["Create a table from CSV (Upload) or query a public dataset to test.","Run `SELECT current_date()` to validate.","Check Job history / bytes processed estimate."],"taskSteps":["Write the requested BigQuery query (STANDARD SQL).","Paste it into the pad; mention dataset.table used."],"withoutAccount":"No GCP yet: still write BigQuery STANDARD SQL in the pad. You will run it once the dataset exists."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'looker', 'en', 0, '{"toolId":"looker","platformLabel":"Looker Studio (free, Google account)","freePath":true,"signupUrl":"https://lookerstudio.google.com/","signupLabel":"Open Looker Studio","accountSteps":["Sign in with a Google account on lookerstudio.google.com.","Accept the terms — no payment for basic reports."],"firstUseSteps":["Create → Blank report.","Add a source (Google Sheets CSV upload, or BigQuery if connected).","Add a simple scorecard and bar chart."],"taskSteps":["Build the requested viz; align the calculation with your KPI definition.","Share as Restricted (not public web) and paste the link + description into the pad."],"withoutAccount":"No Google account: describe the viz (measures, dimensions, filters) and attach a local mock/screenshot if you have one."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'dbt', 'en', 0, '{"toolId":"dbt","platformLabel":"dbt Cloud (Developer / trial) or local dbt Core","freePath":true,"signupUrl":"https://www.getdbt.com/signup","signupLabel":"Create a dbt account","accountSteps":["Sign up at getdbt.com (Developer / trial as offered).","Fully local alternative: `pip install dbt-core dbt-bigquery` (or dbt-duckdb).","Create a “mutualis” project and connect a destination (BigQuery or DuckDB)."],"firstUseSteps":["Init the project (`dbt init` locally, or Cloud wizard).","Create `models/staging/stg_example.sql` with a simple SELECT.","Run `dbt run` then `dbt test` with a not_null test."],"taskSteps":["Write the requested model + tests.","Paste the model SQL and test YAML into the pad."],"withoutAccount":"No dbt Cloud: install dbt Core + DuckDB locally, or write model SQL + test YAML in the pad (the game validates the text)."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'airflow', 'en', 0, '{"toolId":"airflow","platformLabel":"Astro CLI / local Airflow (Docker) or Astronomer trial","freePath":true,"signupUrl":"https://www.astronomer.io/docs/astro/cli/install-cli","signupLabel":"Astro CLI docs (local Airflow)","accountSteps":["Option A (beginner): install Docker Desktop, then Astro CLI, `astro dev init` + `astro dev start`.","Option B: Astronomer trial if available.","Option C: GCP Composer (heavier, costly) — avoid for first try."],"firstUseSteps":["Open local Airflow UI (often http://localhost:8080).","Find DAGs, Graph, Logs.","Enable the sample DAG and watch a Success/Failed run."],"taskSteps":["Write the requested Python DAG (schedule, task, sensor or retry).","Paste the full DAG file into the game pad.","Describe in 2 lines what you see in the UI after a run (or “not run — code only”)."],"withoutAccount":"No Docker yet: still write the DAG in the pad. You will run it once local Airflow is up."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'datagalaxy', 'en', 0, '{"toolId":"datagalaxy","platformLabel":"DataGalaxy (trial) or catalog simulation","freePath":false,"signupUrl":"https://www.datagalaxy.com/","signupLabel":"DataGalaxy website","accountSteps":["Create an account / request a DataGalaxy demo (catalog & glossary).","Without immediate access: simulate the catalog in Confluence or a governed spreadsheet (same field structure)."],"firstUseSteps":["If you have an environment: create an object / term “Active employee”.","Fill definition, domain, Owner, link to a technical asset.","Otherwise: create a Confluence page “Mutualis Catalog” with the same fields."],"taskSteps":["Produce the entry (term, definition, Owner, technical link).","Paste the content (or DataGalaxy/Confluence URL) into the pad."],"withoutAccount":"Normal solo path: simulate DataGalaxy in Confluence Free or a Google Sheet glossary with columns Term | Definition | Owner | Table."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
INSERT INTO content_packs (pack_type, item_key, locale, sort_order, payload) VALUES ('tool_onboarding', 'powerbi', 'en', 0, '{"toolId":"powerbi","platformLabel":"Power BI Desktop (free) + Microsoft account","freePath":true,"signupUrl":"https://www.microsoft.com/en-us/download/details.aspx?id=58494","signupLabel":"Download Power BI Desktop","accountSteps":["Create / use a Microsoft account.","Install Power BI Desktop (Windows) — free to author reports.","Optional: Power BI Service (app.powerbi.com) to publish (limited Free license)."],"firstUseSteps":["Open Power BI Desktop → Get data → Text/CSV with the game file.","Model view: relationships, column types.","Create a Report page with 1 KPI card and 1 chart."],"taskSteps":["Build the requested viz; align the measure with the SQL/mart definition.","Export PDF/PNG or describe the model + attach a screenshot in the game file deliverable."],"withoutAccount":"No Windows/Desktop: mock the viz (measure, filters, grain) in the pad + screenshot if you temporarily use Looker Studio."}'::jsonb) ON CONFLICT (pack_type, item_key, locale) DO UPDATE SET payload=EXCLUDED.payload, sort_order=EXCLUDED.sort_order;
