INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('coproj-1', 'coproj', 'COPROJ #1 — Point d''avancement Sprint 1', 'COPROJ #1 — Point d''avancement Sprint 1', 'L''équipe se réunit en salle Kilimandjaro. Rania (dev back), Hugo (data engineer) et Léa (QA) sont présents. Tu animes le COPROJ. Le Sprint est à mi-parcours.', 'L''équipe se réunit en salle Kilimandjaro. Rania (dev back), Hugo (data engineer) et Léa (QA) sont présents. Tu animes le COPROJ. Le Sprint est à mi-parcours.', 'COPROJ conclu. Les actions sont tracées. L''équipe repart avec de la clarté sur les prochaines 24 h.', 'COPROJ conclu. Les actions sont tracées. L''équipe repart avec de la clarté sur les prochaines 24 h.', '{"kind":"coproj","title":"COPROJ #1 — Point d''avancement Sprint 1","opening":"L''équipe se réunit en salle Kilimandjaro. Rania (dev back), Hugo (data engineer) et Léa (QA) sont présents. Tu animes le COPROJ. Le Sprint est à mi-parcours.","questions":[{"npcLine":"Rania : « On a un blocage sur l''API de remontée des stocks — le endpoint renvoie du XML alors qu''on attendait du JSON. Hugo et moi on bloque depuis hier. »","question":"Comment tu gères ce blocage d''équipe en COPROJ ?","options":["Tu notes le blocage dans ton RAID log, tu identifies un owner pour la résolution et tu fixes un point de suivi à 24 h.","Tu renvoies Rania et Hugo résoudre ça entre eux — ce n''est pas le sujet du COPROJ.","Tu escalades immédiatement au COMEX pour décision urgente."],"correctIndex":0,"correction":"Un COPROJ efficace = actions concrètes avec owner et deadline. Le RAID log (Risques, Actions, Issues, Décisions) est l''outil clé. Escalader au COMEX sans tentative de résolution interne est prématuré."},{"npcLine":"Hugo : « On a 3 User Stories fermées sur 8 prévues. Le vélocité réelle est 40 % en dessous de l''estimation. »","question":"Quelle est ta réaction face à cet écart de vélocité ?","options":["Tu analyses les causes (sous-estimation, blocages, scope creep) et tu proposes d''ajuster le Sprint backlog avec le PO.","Tu demandes à l''équipe de faire des heures supplémentaires pour rattraper.","Tu signales un retard général sans chercher la cause ni proposer d''ajustement."],"correctIndex":0,"correction":"L''écart de vélocité est normal — l''important est l''inspection honnête (Scrum Pilier Inspection) et l''adaptation rapide. Les heures sup ne résolvent pas un problème de scope ou d''estimation."},{"npcLine":"Léa : « Le pipeline de tests automatisés est cassé depuis la merge d''avant-hier. Les 3 dernières User Stories ne sont pas testées. »","question":"Comment traites-tu ce risque qualité ?","options":["Tu bloque la livraison des US non testées et tu ouvres un ticket critique sur le pipeline — c''est une Dette Technique prioritaire.","Tu livres quand même les US — les tests peuvent attendre la prochaine sprint review.","Tu demandes à Léa de tester manuellement toutes les US en urgence."],"correctIndex":0,"correction":"La Définition of Done inclut les tests automatisés. Une US non testée n''est pas \"Done\". Livrer du code non testé accumule de la dette et compromet la qualité produit."},{"npcLine":"Le client (représenté par le PO) vient d''ajouter 2 nouvelles US en milieu de Sprint via un message Teams. Il veut les voir dans la prochaine Sprint Review.","question":"Comment tu gères cet ajout de scope en cours de Sprint ?","options":["Tu expliques que le Sprint backlog est figé — les nouvelles US entrent dans le Product Backlog et seront arbitrées en Sprint Planning.","Tu acceptes les 2 US pour satisfaire le client, quitte à sacrifier d''autres items.","Tu ignores la demande et tu n''en parles pas en COPROJ."],"correctIndex":0,"correction":"En Scrum, le Sprint backlog est protégé. Le Scrum Master (ou PM) protège l''équipe du scope creep en renvoyant les nouvelles demandes au Product Backlog pour priorisation lors du prochain Sprint Planning."},{"npcLine":"Le COPROJ se termine. Il reste 10 minutes. Tout le monde attend que tu conclues.","question":"Comment tu clôtures un COPROJ de façon professionnelle ?","options":["Tu récapitules les décisions prises, les actions identifiées (qui fait quoi, pour quand) et tu envoies le compte-rendu dans l''heure.","Tu dis « C''est bon, on se voit à la prochaine réunion » et tu fermes la salle.","Tu demandes à chacun d''envoyer leur propre compte-rendu de ce qu''ils ont à faire."],"correctIndex":0,"correction":"Un COPROJ sans compte-rendu = une réunion sans mémoire. Les 3 livrables : décisions documentées, actions tracées avec owner + deadline, diffusion immédiate."}],"closing":"COPROJ conclu. Les actions sont tracées. L''équipe repart avec de la clarté sur les prochaines 24 h."}'::jsonb, '{"kind":"coproj","title":"COPROJ #1 — Point d''avancement Sprint 1","opening":"L''équipe se réunit en salle Kilimandjaro. Rania (dev back), Hugo (data engineer) et Léa (QA) sont présents. Tu animes le COPROJ. Le Sprint est à mi-parcours.","questions":[{"npcLine":"Rania : « On a un blocage sur l''API de remontée des stocks — le endpoint renvoie du XML alors qu''on attendait du JSON. Hugo et moi on bloque depuis hier. »","question":"Comment tu gères ce blocage d''équipe en COPROJ ?","options":["Tu notes le blocage dans ton RAID log, tu identifies un owner pour la résolution et tu fixes un point de suivi à 24 h.","Tu renvoies Rania et Hugo résoudre ça entre eux — ce n''est pas le sujet du COPROJ.","Tu escalades immédiatement au COMEX pour décision urgente."],"correctIndex":0,"correction":"Un COPROJ efficace = actions concrètes avec owner et deadline. Le RAID log (Risques, Actions, Issues, Décisions) est l''outil clé. Escalader au COMEX sans tentative de résolution interne est prématuré."},{"npcLine":"Hugo : « On a 3 User Stories fermées sur 8 prévues. Le vélocité réelle est 40 % en dessous de l''estimation. »","question":"Quelle est ta réaction face à cet écart de vélocité ?","options":["Tu analyses les causes (sous-estimation, blocages, scope creep) et tu proposes d''ajuster le Sprint backlog avec le PO.","Tu demandes à l''équipe de faire des heures supplémentaires pour rattraper.","Tu signales un retard général sans chercher la cause ni proposer d''ajustement."],"correctIndex":0,"correction":"L''écart de vélocité est normal — l''important est l''inspection honnête (Scrum Pilier Inspection) et l''adaptation rapide. Les heures sup ne résolvent pas un problème de scope ou d''estimation."},{"npcLine":"Léa : « Le pipeline de tests automatisés est cassé depuis la merge d''avant-hier. Les 3 dernières User Stories ne sont pas testées. »","question":"Comment traites-tu ce risque qualité ?","options":["Tu bloque la livraison des US non testées et tu ouvres un ticket critique sur le pipeline — c''est une Dette Technique prioritaire.","Tu livres quand même les US — les tests peuvent attendre la prochaine sprint review.","Tu demandes à Léa de tester manuellement toutes les US en urgence."],"correctIndex":0,"correction":"La Définition of Done inclut les tests automatisés. Une US non testée n''est pas \"Done\". Livrer du code non testé accumule de la dette et compromet la qualité produit."},{"npcLine":"Le client (représenté par le PO) vient d''ajouter 2 nouvelles US en milieu de Sprint via un message Teams. Il veut les voir dans la prochaine Sprint Review.","question":"Comment tu gères cet ajout de scope en cours de Sprint ?","options":["Tu expliques que le Sprint backlog est figé — les nouvelles US entrent dans le Product Backlog et seront arbitrées en Sprint Planning.","Tu acceptes les 2 US pour satisfaire le client, quitte à sacrifier d''autres items.","Tu ignores la demande et tu n''en parles pas en COPROJ."],"correctIndex":0,"correction":"En Scrum, le Sprint backlog est protégé. Le Scrum Master (ou PM) protège l''équipe du scope creep en renvoyant les nouvelles demandes au Product Backlog pour priorisation lors du prochain Sprint Planning."},{"npcLine":"Le COPROJ se termine. Il reste 10 minutes. Tout le monde attend que tu conclues.","question":"Comment tu clôtures un COPROJ de façon professionnelle ?","options":["Tu récapitules les décisions prises, les actions identifiées (qui fait quoi, pour quand) et tu envoies le compte-rendu dans l''heure.","Tu dis « C''est bon, on se voit à la prochaine réunion » et tu fermes la salle.","Tu demandes à chacun d''envoyer leur propre compte-rendu de ce qu''ils ont à faire."],"correctIndex":0,"correction":"Un COPROJ sans compte-rendu = une réunion sans mémoire. Les 3 livrables : décisions documentées, actions tracées avec owner + deadline, diffusion immédiate."}],"closing":"COPROJ conclu. Les actions sont tracées. L''équipe repart avec de la clarté sur les prochaines 24 h."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-1', 0, 'Rania : « On a un blocage sur l''API de remontée des stocks — le endpoint renvoie du XML alors qu''on attendait du JSON. Hugo et moi on bloque depuis hier. »', 'Rania : « On a un blocage sur l''API de remontée des stocks — le endpoint renvoie du XML alors qu''on attendait du JSON. Hugo et moi on bloque depuis hier. »', 'Comment tu gères ce blocage d''équipe en COPROJ ?', 'Comment tu gères ce blocage d''équipe en COPROJ ?', 'Tu notes le blocage dans ton RAID log, tu identifies un owner pour la résolution et tu fixes un point de suivi à 24 h.', 'Tu notes le blocage dans ton RAID log, tu identifies un owner pour la résolution et tu fixes un point de suivi à 24 h.', 'Tu renvoies Rania et Hugo résoudre ça entre eux — ce n''est pas le sujet du COPROJ.', 'Tu renvoies Rania et Hugo résoudre ça entre eux — ce n''est pas le sujet du COPROJ.', 'Tu escalades immédiatement au COMEX pour décision urgente.', 'Tu escalades immédiatement au COMEX pour décision urgente.', 0, 'Un COPROJ efficace = actions concrètes avec owner et deadline. Le RAID log (Risques, Actions, Issues, Décisions) est l''outil clé. Escalader au COMEX sans tentative de résolution interne est prématuré.', 'Un COPROJ efficace = actions concrètes avec owner et deadline. Le RAID log (Risques, Actions, Issues, Décisions) est l''outil clé. Escalader au COMEX sans tentative de résolution interne est prématuré.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
