INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-1', 2, 'Léa : « Le pipeline de tests automatisés est cassé depuis la merge d''avant-hier. Les 3 dernières User Stories ne sont pas testées. »', 'Léa : « Le pipeline de tests automatisés est cassé depuis la merge d''avant-hier. Les 3 dernières User Stories ne sont pas testées. »', 'Comment traites-tu ce risque qualité ?', 'Comment traites-tu ce risque qualité ?', 'Tu bloque la livraison des US non testées et tu ouvres un ticket critique sur le pipeline — c''est une Dette Technique prioritaire.', 'Tu bloque la livraison des US non testées et tu ouvres un ticket critique sur le pipeline — c''est une Dette Technique prioritaire.', 'Tu livres quand même les US — les tests peuvent attendre la prochaine sprint review.', 'Tu livres quand même les US — les tests peuvent attendre la prochaine sprint review.', 'Tu demandes à Léa de tester manuellement toutes les US en urgence.', 'Tu demandes à Léa de tester manuellement toutes les US en urgence.', 0, 'La Définition of Done inclut les tests automatisés. Une US non testée n''est pas "Done". Livrer du code non testé accumule de la dette et compromet la qualité produit.', 'La Définition of Done inclut les tests automatisés. Une US non testée n''est pas "Done". Livrer du code non testé accumule de la dette et compromet la qualité produit.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
