INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-1', 4, 'Le COPROJ se termine. Il reste 10 minutes. Tout le monde attend que tu conclues.', 'Le COPROJ se termine. Il reste 10 minutes. Tout le monde attend que tu conclues.', 'Comment tu clôtures un COPROJ de façon professionnelle ?', 'Comment tu clôtures un COPROJ de façon professionnelle ?', 'Tu récapitules les décisions prises, les actions identifiées (qui fait quoi, pour quand) et tu envoies le compte-rendu dans l''heure.', 'Tu récapitules les décisions prises, les actions identifiées (qui fait quoi, pour quand) et tu envoies le compte-rendu dans l''heure.', 'Tu dis « C''est bon, on se voit à la prochaine réunion » et tu fermes la salle.', 'Tu dis « C''est bon, on se voit à la prochaine réunion » et tu fermes la salle.', 'Tu demandes à chacun d''envoyer leur propre compte-rendu de ce qu''ils ont à faire.', 'Tu demandes à chacun d''envoyer leur propre compte-rendu de ce qu''ils ont à faire.', 0, 'Un COPROJ sans compte-rendu = une réunion sans mémoire. Les 3 livrables : décisions documentées, actions tracées avec owner + deadline, diffusion immédiate.', 'Un COPROJ sans compte-rendu = une réunion sans mémoire. Les 3 livrables : décisions documentées, actions tracées avec owner + deadline, diffusion immédiate.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('coproj-2', 'coproj', 'COPROJ #2 — Démo intermédiaire & risques', 'COPROJ #2 — Démo intermédiaire & risques', 'Mi-projet. L''équipe présente une démo intermédiaire des fonctionnalités livrées. Des risques techniques nouveaux sont remontés.', 'Mi-projet. L''équipe présente une démo intermédiaire des fonctionnalités livrées. Des risques techniques nouveaux sont remontés.', 'Les risques sont documentés et les actions assignées. Le COPIL sera informé des ajustements de plan.', 'Les risques sont documentés et les actions assignées. Le COPIL sera informé des ajustements de plan.', '{"kind":"coproj","title":"COPROJ #2 — Démo intermédiaire & risques","opening":"Mi-projet. L''équipe présente une démo intermédiaire des fonctionnalités livrées. Des risques techniques nouveaux sont remontés.","questions":[{"npcLine":"Hugo : « La migration de la base legacy vers BigQuery prend 3 fois plus de temps que prévu à cause du volume de données non structurées. »","question":"Comment tu traites ce risque de délai en COPROJ ?","options":["Tu mets à jour le registre des risques, tu révises l''estimation avec l''équipe et tu proposes un plan de contingence au COPIL.","Tu minimises l''impact pour ne pas alarmer l''équipe.","Tu attends que le retard soit confirmé avant d''agir."],"correctIndex":0,"correction":"La gestion proactive des risques est clé en PM. Identifier tôt, quantifier l''impact, proposer une mitigation — et communiquer vers le COPIL avant que le risque devienne un incident."},{"npcLine":"Rania : « On a découvert une faille de sécurité potentielle dans le module d''authentification. Ce n''est pas dans notre périmètre mais ça nous bloque. »","question":"Comment gères-tu ce blocage hors périmètre ?","options":["Tu identifies l''équipe responsable, tu crées une dépendance documentée dans le plan projet et tu escalades si pas de réponse sous 48 h.","Tu demandes à Rania de corriger elle-même la faille pour débloquer.","Tu continues sans attendre — la sécurité est un sujet pour plus tard."],"correctIndex":0,"correction":"Les dépendances inter-équipes doivent être documentées et trackées. Le PM est le gardien du chemin critique — escalader vite sur les dépendances bloquantes."},{"npcLine":"La démo intermédiaire montre que 2 fonctionnalités clés ne correspondent pas aux attentes du métier.","question":"Quelle est la bonne réaction face à ce désalignement métier ?","options":["Tu organises un atelier de recadrage avec le PO et les utilisateurs clés pour clarifier le besoin réel avant de continuer.","Tu corriges rapidement selon ta propre interprétation pour avancer.","Tu livres quand même — le métier ajustera ses attentes."],"correctIndex":0,"correction":"La démo intermédiaire sert précisément à détecter les désalignements tôt (Build-Measure-Learn). Un atelier de recadrage immédiat évite des semaines de rework coûteux."},{"npcLine":"Léa soulève que la documentation technique est absente sur 60 % des modules livrés.","question":"Comment tu traites ce déficit de documentation ?","options":["Tu intègres la documentation dans la Définition of Done à partir du prochain Sprint — une US sans doc n''est pas \"Done\".","Tu demandes à Léa de rédiger la doc elle-même après les livraisons.","Tu juges que la doc peut attendre la fin du projet."],"correctIndex":0,"correction":"La documentation est un livrable au même titre que le code. L''intégrer dans la DoD dès maintenant évite une dette documentaire incontrôlable en fin de projet."},{"npcLine":"L''équipe est fatigante. Deux personnes ont mentionné un sentiment de surcharge.","question":"Comment tu gères la surcharge d''équipe en tant que PM ?","options":["Tu identifies les causes (trop de parallelisme, manque de priorité), tu ajustes le WIP limit et tu prévois un sprint de stabilisation si nécessaire.","Tu rappelles à l''équipe que les deadlines ne bougent pas — la fatigue est normale.","Tu ignores le signal — chacun gère son rythme."],"correctIndex":0,"correction":"La soutenabilité du rythme (sustainable pace) est une valeur Agile fondamentale. Une équipe épuisée produit de la dette et fait des erreurs. Le PM ajuste la charge proactivement."}],"closing":"Les risques sont documentés et les actions assignées. Le COPIL sera informé des ajustements de plan."}'::jsonb, '{"kind":"coproj","title":"COPROJ #2 — Démo intermédiaire & risques","opening":"Mi-projet. L''équipe présente une démo intermédiaire des fonctionnalités livrées. Des risques techniques nouveaux sont remontés.","questions":[{"npcLine":"Hugo : « La migration de la base legacy vers BigQuery prend 3 fois plus de temps que prévu à cause du volume de données non structurées. »","question":"Comment tu traites ce risque de délai en COPROJ ?","options":["Tu mets à jour le registre des risques, tu révises l''estimation avec l''équipe et tu proposes un plan de contingence au COPIL.","Tu minimises l''impact pour ne pas alarmer l''équipe.","Tu attends que le retard soit confirmé avant d''agir."],"correctIndex":0,"correction":"La gestion proactive des risques est clé en PM. Identifier tôt, quantifier l''impact, proposer une mitigation — et communiquer vers le COPIL avant que le risque devienne un incident."},{"npcLine":"Rania : « On a découvert une faille de sécurité potentielle dans le module d''authentification. Ce n''est pas dans notre périmètre mais ça nous bloque. »","question":"Comment gères-tu ce blocage hors périmètre ?","options":["Tu identifies l''équipe responsable, tu crées une dépendance documentée dans le plan projet et tu escalades si pas de réponse sous 48 h.","Tu demandes à Rania de corriger elle-même la faille pour débloquer.","Tu continues sans attendre — la sécurité est un sujet pour plus tard."],"correctIndex":0,"correction":"Les dépendances inter-équipes doivent être documentées et trackées. Le PM est le gardien du chemin critique — escalader vite sur les dépendances bloquantes."},{"npcLine":"La démo intermédiaire montre que 2 fonctionnalités clés ne correspondent pas aux attentes du métier.","question":"Quelle est la bonne réaction face à ce désalignement métier ?","options":["Tu organises un atelier de recadrage avec le PO et les utilisateurs clés pour clarifier le besoin réel avant de continuer.","Tu corriges rapidement selon ta propre interprétation pour avancer.","Tu livres quand même — le métier ajustera ses attentes."],"correctIndex":0,"correction":"La démo intermédiaire sert précisément à détecter les désalignements tôt (Build-Measure-Learn). Un atelier de recadrage immédiat évite des semaines de rework coûteux."},{"npcLine":"Léa soulève que la documentation technique est absente sur 60 % des modules livrés.","question":"Comment tu traites ce déficit de documentation ?","options":["Tu intègres la documentation dans la Définition of Done à partir du prochain Sprint — une US sans doc n''est pas \"Done\".","Tu demandes à Léa de rédiger la doc elle-même après les livraisons.","Tu juges que la doc peut attendre la fin du projet."],"correctIndex":0,"correction":"La documentation est un livrable au même titre que le code. L''intégrer dans la DoD dès maintenant évite une dette documentaire incontrôlable en fin de projet."},{"npcLine":"L''équipe est fatigante. Deux personnes ont mentionné un sentiment de surcharge.","question":"Comment tu gères la surcharge d''équipe en tant que PM ?","options":["Tu identifies les causes (trop de parallelisme, manque de priorité), tu ajustes le WIP limit et tu prévois un sprint de stabilisation si nécessaire.","Tu rappelles à l''équipe que les deadlines ne bougent pas — la fatigue est normale.","Tu ignores le signal — chacun gère son rythme."],"correctIndex":0,"correction":"La soutenabilité du rythme (sustainable pace) est une valeur Agile fondamentale. Une équipe épuisée produit de la dette et fait des erreurs. Le PM ajuste la charge proactivement."}],"closing":"Les risques sont documentés et les actions assignées. Le COPIL sera informé des ajustements de plan."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
