INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-2', 1, 'Rania : « On a découvert une faille de sécurité potentielle dans le module d''authentification. Ce n''est pas dans notre périmètre mais ça nous bloque. »', 'Rania : « On a découvert une faille de sécurité potentielle dans le module d''authentification. Ce n''est pas dans notre périmètre mais ça nous bloque. »', 'Comment gères-tu ce blocage hors périmètre ?', 'Comment gères-tu ce blocage hors périmètre ?', 'Tu identifies l''équipe responsable, tu crées une dépendance documentée dans le plan projet et tu escalades si pas de réponse sous 48 h.', 'Tu identifies l''équipe responsable, tu crées une dépendance documentée dans le plan projet et tu escalades si pas de réponse sous 48 h.', 'Tu demandes à Rania de corriger elle-même la faille pour débloquer.', 'Tu demandes à Rania de corriger elle-même la faille pour débloquer.', 'Tu continues sans attendre — la sécurité est un sujet pour plus tard.', 'Tu continues sans attendre — la sécurité est un sujet pour plus tard.', 0, 'Les dépendances inter-équipes doivent être documentées et trackées. Le PM est le gardien du chemin critique — escalader vite sur les dépendances bloquantes.', 'Les dépendances inter-équipes doivent être documentées et trackées. Le PM est le gardien du chemin critique — escalader vite sur les dépendances bloquantes.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-2', 2, 'La démo intermédiaire montre que 2 fonctionnalités clés ne correspondent pas aux attentes du métier.', 'La démo intermédiaire montre que 2 fonctionnalités clés ne correspondent pas aux attentes du métier.', 'Quelle est la bonne réaction face à ce désalignement métier ?', 'Quelle est la bonne réaction face à ce désalignement métier ?', 'Tu organises un atelier de recadrage avec le PO et les utilisateurs clés pour clarifier le besoin réel avant de continuer.', 'Tu organises un atelier de recadrage avec le PO et les utilisateurs clés pour clarifier le besoin réel avant de continuer.', 'Tu corriges rapidement selon ta propre interprétation pour avancer.', 'Tu corriges rapidement selon ta propre interprétation pour avancer.', 'Tu livres quand même — le métier ajustera ses attentes.', 'Tu livres quand même — le métier ajustera ses attentes.', 0, 'La démo intermédiaire sert précisément à détecter les désalignements tôt (Build-Measure-Learn). Un atelier de recadrage immédiat évite des semaines de rework coûteux.', 'La démo intermédiaire sert précisément à détecter les désalignements tôt (Build-Measure-Learn). Un atelier de recadrage immédiat évite des semaines de rework coûteux.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
