INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-2', 4, 'L''équipe est fatigante. Deux personnes ont mentionné un sentiment de surcharge.', 'L''équipe est fatigante. Deux personnes ont mentionné un sentiment de surcharge.', 'Comment tu gères la surcharge d''équipe en tant que PM ?', 'Comment tu gères la surcharge d''équipe en tant que PM ?', 'Tu identifies les causes (trop de parallelisme, manque de priorité), tu ajustes le WIP limit et tu prévois un sprint de stabilisation si nécessaire.', 'Tu identifies les causes (trop de parallelisme, manque de priorité), tu ajustes le WIP limit et tu prévois un sprint de stabilisation si nécessaire.', 'Tu rappelles à l''équipe que les deadlines ne bougent pas — la fatigue est normale.', 'Tu rappelles à l''équipe que les deadlines ne bougent pas — la fatigue est normale.', 'Tu ignores le signal — chacun gère son rythme.', 'Tu ignores le signal — chacun gère son rythme.', 0, 'La soutenabilité du rythme (sustainable pace) est une valeur Agile fondamentale. Une équipe épuisée produit de la dette et fait des erreurs. Le PM ajuste la charge proactivement.', 'La soutenabilité du rythme (sustainable pace) est une valeur Agile fondamentale. Une équipe épuisée produit de la dette et fait des erreurs. Le PM ajuste la charge proactivement.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('coproj-3', 'coproj', 'COPROJ #3 — Clôture de projet', 'COPROJ #3 — Clôture de projet', 'Dernier COPROJ avant la livraison finale. L''équipe fait le bilan. Le projet touche à sa fin.', 'Dernier COPROJ avant la livraison finale. L''équipe fait le bilan. Le projet touche à sa fin.', 'Projet officiellement clôturé. La rétrospective est planifiée. L''équipe est libre.', 'Projet officiellement clôturé. La rétrospective est planifiée. L''équipe est libre.', '{"kind":"coproj","title":"COPROJ #3 — Clôture de projet","opening":"Dernier COPROJ avant la livraison finale. L''équipe fait le bilan. Le projet touche à sa fin.","questions":[{"npcLine":"Hugo : « On a livré 87 % du scope prévu. Les 13 % restants sont des fonctionnalités de reporting avancé non critiques. »","question":"Comment tu présentes ce résultat au COPIL ?","options":["Tu présentes la livraison honnêtement : scope livré vs prévu, critères de succès atteints, et plan pour les 13 % restants (backlog ou abandon).","Tu annonces 100 % de livraison — les 13 % n''étaient pas vraiment dans le scope initial.","Tu caches les 13 % manquants pour éviter les questions difficiles."],"correctIndex":0,"correction":"La transparence est une valeur non négociable en PM. Présenter honnêtement le périmètre livré construit la confiance long terme — même si le résultat est imparfait."},{"npcLine":"Rania : « On devrait documenter les leçons apprises — on a fait beaucoup d''erreurs sur l''estimation. »","question":"Comment tu organises les leçons apprises en clôture ?","options":["Tu facilites une rétrospective de projet structurée (went well / to improve / actions) et tu archives les leçons dans la base de connaissance.","Tu notes mentalement les erreurs pour le prochain projet.","Tu évites le sujet — revenir sur les erreurs démotive l''équipe."],"correctIndex":0,"correction":"Les leçons apprises documentées sont le seul moyen d''améliorer les estimations futures. Une rétrospective de clôture structurée est une pratique PM et Scrum fondamentale."},{"npcLine":"Le client demande des modifications de dernière minute juste avant la recette finale.","question":"Comment tu gères ces demandes de dernière minute ?","options":["Tu appliques le processus de gestion des changements : analyse d''impact, décision formelle du sponsor, report en post-livraison si nécessaire.","Tu acceptes pour satisfaire le client — quelques modifications ça ne coûte rien.","Tu refuses catégoriquement sans analyse d''impact."],"correctIndex":0,"correction":"Toute modification en phase de recette doit passer par le Change Management. Une acceptation sans analyse d''impact peut introduire des régressions et retarder la livraison."},{"npcLine":"Léa : « Les tests de recette ont révélé 3 bugs critiques non détectés plus tôt. »","question":"Comment tu arbitres la livraison avec des bugs critiques ouverts ?","options":["Tu bloques la livraison jusqu''à correction des bugs critiques — livrer du logiciel défaillant crée plus de problèmes qu''un court délai.","Tu livres quand même en documentant les bugs pour correction future.","Tu minimises l''impact des bugs devant le client pour ne pas retarder."],"correctIndex":0,"correction":"Un bug \"critique\" par définition impacte la valeur métier ou la sécurité. Livrer en connaissance de cause sans correction est une faute professionnelle PM et contractuelle."},{"npcLine":"Le projet est terminé. L''équipe se disperse. Tu dois officialiser la clôture.","question":"Quelles sont les étapes formelles de clôture d''un projet ?","options":["Recette formelle signée par le client, archivage des livrables, libération des ressources, rapport de clôture avec indicateurs finaux et leçons apprises.","Envoyer un email de remerciement à l''équipe et fermer les tickets Jira.","Attendre que le client signale des problèmes avant de clôturer officiellement."],"correctIndex":0,"correction":"La clôture formelle protège juridiquement et marque la fin contractuelle. Elle inclut la recette signée, l''archivage documentaire et la capitalisation des enseignements."}],"closing":"Projet officiellement clôturé. La rétrospective est planifiée. L''équipe est libre."}'::jsonb, '{"kind":"coproj","title":"COPROJ #3 — Clôture de projet","opening":"Dernier COPROJ avant la livraison finale. L''équipe fait le bilan. Le projet touche à sa fin.","questions":[{"npcLine":"Hugo : « On a livré 87 % du scope prévu. Les 13 % restants sont des fonctionnalités de reporting avancé non critiques. »","question":"Comment tu présentes ce résultat au COPIL ?","options":["Tu présentes la livraison honnêtement : scope livré vs prévu, critères de succès atteints, et plan pour les 13 % restants (backlog ou abandon).","Tu annonces 100 % de livraison — les 13 % n''étaient pas vraiment dans le scope initial.","Tu caches les 13 % manquants pour éviter les questions difficiles."],"correctIndex":0,"correction":"La transparence est une valeur non négociable en PM. Présenter honnêtement le périmètre livré construit la confiance long terme — même si le résultat est imparfait."},{"npcLine":"Rania : « On devrait documenter les leçons apprises — on a fait beaucoup d''erreurs sur l''estimation. »","question":"Comment tu organises les leçons apprises en clôture ?","options":["Tu facilites une rétrospective de projet structurée (went well / to improve / actions) et tu archives les leçons dans la base de connaissance.","Tu notes mentalement les erreurs pour le prochain projet.","Tu évites le sujet — revenir sur les erreurs démotive l''équipe."],"correctIndex":0,"correction":"Les leçons apprises documentées sont le seul moyen d''améliorer les estimations futures. Une rétrospective de clôture structurée est une pratique PM et Scrum fondamentale."},{"npcLine":"Le client demande des modifications de dernière minute juste avant la recette finale.","question":"Comment tu gères ces demandes de dernière minute ?","options":["Tu appliques le processus de gestion des changements : analyse d''impact, décision formelle du sponsor, report en post-livraison si nécessaire.","Tu acceptes pour satisfaire le client — quelques modifications ça ne coûte rien.","Tu refuses catégoriquement sans analyse d''impact."],"correctIndex":0,"correction":"Toute modification en phase de recette doit passer par le Change Management. Une acceptation sans analyse d''impact peut introduire des régressions et retarder la livraison."},{"npcLine":"Léa : « Les tests de recette ont révélé 3 bugs critiques non détectés plus tôt. »","question":"Comment tu arbitres la livraison avec des bugs critiques ouverts ?","options":["Tu bloques la livraison jusqu''à correction des bugs critiques — livrer du logiciel défaillant crée plus de problèmes qu''un court délai.","Tu livres quand même en documentant les bugs pour correction future.","Tu minimises l''impact des bugs devant le client pour ne pas retarder."],"correctIndex":0,"correction":"Un bug \"critique\" par définition impacte la valeur métier ou la sécurité. Livrer en connaissance de cause sans correction est une faute professionnelle PM et contractuelle."},{"npcLine":"Le projet est terminé. L''équipe se disperse. Tu dois officialiser la clôture.","question":"Quelles sont les étapes formelles de clôture d''un projet ?","options":["Recette formelle signée par le client, archivage des livrables, libération des ressources, rapport de clôture avec indicateurs finaux et leçons apprises.","Envoyer un email de remerciement à l''équipe et fermer les tickets Jira.","Attendre que le client signale des problèmes avant de clôturer officiellement."],"correctIndex":0,"correction":"La clôture formelle protège juridiquement et marque la fin contractuelle. Elle inclut la recette signée, l''archivage documentaire et la capitalisation des enseignements."}],"closing":"Projet officiellement clôturé. La rétrospective est planifiée. L''équipe est libre."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
