INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('coproj-3', 4, 'Le projet est terminé. L''équipe se disperse. Tu dois officialiser la clôture.', 'Le projet est terminé. L''équipe se disperse. Tu dois officialiser la clôture.', 'Quelles sont les étapes formelles de clôture d''un projet ?', 'Quelles sont les étapes formelles de clôture d''un projet ?', 'Recette formelle signée par le client, archivage des livrables, libération des ressources, rapport de clôture avec indicateurs finaux et leçons apprises.', 'Recette formelle signée par le client, archivage des livrables, libération des ressources, rapport de clôture avec indicateurs finaux et leçons apprises.', 'Envoyer un email de remerciement à l''équipe et fermer les tickets Jira.', 'Envoyer un email de remerciement à l''équipe et fermer les tickets Jira.', 'Attendre que le client signale des problèmes avant de clôturer officiellement.', 'Attendre que le client signale des problèmes avant de clôturer officiellement.', 0, 'La clôture formelle protège juridiquement et marque la fin contractuelle. Elle inclut la recette signée, l''archivage documentaire et la capitalisation des enseignements.', 'La clôture formelle protège juridiquement et marque la fin contractuelle. Elle inclut la recette signée, l''archivage documentaire et la capitalisation des enseignements.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('copil-1', 'copil', 'COPIL #1 — Point mensuel avec le COMEX', 'COPIL #1 — Point mensuel avec le COMEX', 'Tu présentes l''avancement du projet au COMEX Mutualis Group. La DSI, le CFO et le CPO sont présents. Ils attendent clarté, chiffres et décisions.', 'Tu présentes l''avancement du projet au COMEX Mutualis Group. La DSI, le CFO et le CPO sont présents. Ils attendent clarté, chiffres et décisions.', 'COPIL conclu. Les décisions sont enregistrées. Le COMEX repart avec de la visibilité.', 'COPIL conclu. Les décisions sont enregistrées. Le COMEX repart avec de la visibilité.', '{"kind":"copil","title":"COPIL #1 — Point mensuel avec le COMEX","opening":"Tu présentes l''avancement du projet au COMEX Mutualis Group. La DSI, le CFO et le CPO sont présents. Ils attendent clarté, chiffres et décisions.","questions":[{"npcLine":"Le CFO : « Vous êtes à 60 % du budget consommé pour 45 % du scope livré. Comment vous l''expliquez ? »","question":"Comment tu réponds à cette question sur le budget en COPIL ?","options":["Tu présentes l''analyse des écarts (complexité technique imprévue, dette legacy), la CPI (Cost Performance Index) et le plan correctif avec jalons révisés.","Tu accuses l''équipe de mauvaise gestion pour protéger ta crédibilité.","Tu minimises l''écart en disant que c''est \"dans les normes du marché\"."],"correctIndex":0,"correction":"En COPIL, les sponsors attendent des données factuelles et un plan d''action — pas des excuses. La CPI et le SPI (Schedule Performance Index) sont les indicateurs standards du management de projet (PMBOK)."},{"npcLine":"Le CPO : « Le planning prévoyait une mise en prod en septembre. On est en octobre. Quand livrez-vous vraiment ? »","question":"Comment tu communiques une nouvelle date de livraison révisée ?","options":["Tu présentes la date révisée fondée sur la vélocité réelle mesurée, avec les hypothèses et les marges de risque clairement explicitées.","Tu donnes une date optimiste pour calmer les inquiétudes.","Tu dis que la date sera communiquée la semaine prochaine pour gagner du temps."],"correctIndex":0,"correction":"Une date révisée crédible repose sur des données réelles (vélocité, burn-down). Donner une date sans base solide détruit la confiance au prochain COPIL."},{"npcLine":"La DSI : « On envisage de couper le budget de 20 % sur ce projet pour financer une initiative stratégique urgente. »","question":"Comment tu réagis à cette décision de réduction budgétaire ?","options":["Tu présentes immédiatement l''analyse d''impact sur le scope et les délais — et tu demandes une décision formelle sur ce qu''on sacrifie.","Tu acceptes sans broncher pour ne pas créer de tension avec la direction.","Tu refuses catégoriquement et tu quittes la réunion."],"correctIndex":0,"correction":"Une réduction budgétaire impose un arbitrage scope/délai/qualité. Le PM est là pour présenter les impacts objectivement et obtenir une décision formelle — pas pour absorber silencieusement la contrainte."},{"npcLine":"Le COMEX veut un dashboard de suivi en temps réel accessible depuis leur mobile.","question":"Comment tu traites cette nouvelle demande du COMEX ?","options":["Tu notes la demande comme un nouveau besoin, tu analyses l''impact sur le backlog existant et tu proposes un arbitrage au prochain COPIL.","Tu promets de livrer le dashboard pour le prochain COPIL sans analyser l''impact.","Tu expliques que ce n''est pas dans le scope et tu refuses d''en discuter."],"correctIndex":0,"correction":"Toute nouvelle demande COMEX doit passer par la gouvernance du changement. Promettre sans analyser crée des attentes non maîtrisées et compromet le planning."},{"npcLine":"Fin du COPIL. Le COMEX attend un résumé décisionnel avant de partir.","question":"Quel format adoptes-tu pour conclure le COPIL ?","options":["Un résumé exécutif de 2 minutes : statut RAG, 3 décisions prises, 3 actions avec owners, prochain COPIL daté.","Tu demandes à chaque membre de l''équipe de présenter son bilan.","Tu distribues un rapport de 20 pages et tu pars sans résumé oral."],"correctIndex":0,"correction":"Le COMEX raisonne en synthèse, pas en détail. Un résumé RAG (Rouge-Ambre-Vert) + décisions + actions est le standard du reporting exécutif."}],"closing":"COPIL conclu. Les décisions sont enregistrées. Le COMEX repart avec de la visibilité."}'::jsonb, '{"kind":"copil","title":"COPIL #1 — Point mensuel avec le COMEX","opening":"Tu présentes l''avancement du projet au COMEX Mutualis Group. La DSI, le CFO et le CPO sont présents. Ils attendent clarté, chiffres et décisions.","questions":[{"npcLine":"Le CFO : « Vous êtes à 60 % du budget consommé pour 45 % du scope livré. Comment vous l''expliquez ? »","question":"Comment tu réponds à cette question sur le budget en COPIL ?","options":["Tu présentes l''analyse des écarts (complexité technique imprévue, dette legacy), la CPI (Cost Performance Index) et le plan correctif avec jalons révisés.","Tu accuses l''équipe de mauvaise gestion pour protéger ta crédibilité.","Tu minimises l''écart en disant que c''est \"dans les normes du marché\"."],"correctIndex":0,"correction":"En COPIL, les sponsors attendent des données factuelles et un plan d''action — pas des excuses. La CPI et le SPI (Schedule Performance Index) sont les indicateurs standards du management de projet (PMBOK)."},{"npcLine":"Le CPO : « Le planning prévoyait une mise en prod en septembre. On est en octobre. Quand livrez-vous vraiment ? »","question":"Comment tu communiques une nouvelle date de livraison révisée ?","options":["Tu présentes la date révisée fondée sur la vélocité réelle mesurée, avec les hypothèses et les marges de risque clairement explicitées.","Tu donnes une date optimiste pour calmer les inquiétudes.","Tu dis que la date sera communiquée la semaine prochaine pour gagner du temps."],"correctIndex":0,"correction":"Une date révisée crédible repose sur des données réelles (vélocité, burn-down). Donner une date sans base solide détruit la confiance au prochain COPIL."},{"npcLine":"La DSI : « On envisage de couper le budget de 20 % sur ce projet pour financer une initiative stratégique urgente. »","question":"Comment tu réagis à cette décision de réduction budgétaire ?","options":["Tu présentes immédiatement l''analyse d''impact sur le scope et les délais — et tu demandes une décision formelle sur ce qu''on sacrifie.","Tu acceptes sans broncher pour ne pas créer de tension avec la direction.","Tu refuses catégoriquement et tu quittes la réunion."],"correctIndex":0,"correction":"Une réduction budgétaire impose un arbitrage scope/délai/qualité. Le PM est là pour présenter les impacts objectivement et obtenir une décision formelle — pas pour absorber silencieusement la contrainte."},{"npcLine":"Le COMEX veut un dashboard de suivi en temps réel accessible depuis leur mobile.","question":"Comment tu traites cette nouvelle demande du COMEX ?","options":["Tu notes la demande comme un nouveau besoin, tu analyses l''impact sur le backlog existant et tu proposes un arbitrage au prochain COPIL.","Tu promets de livrer le dashboard pour le prochain COPIL sans analyser l''impact.","Tu expliques que ce n''est pas dans le scope et tu refuses d''en discuter."],"correctIndex":0,"correction":"Toute nouvelle demande COMEX doit passer par la gouvernance du changement. Promettre sans analyser crée des attentes non maîtrisées et compromet le planning."},{"npcLine":"Fin du COPIL. Le COMEX attend un résumé décisionnel avant de partir.","question":"Quel format adoptes-tu pour conclure le COPIL ?","options":["Un résumé exécutif de 2 minutes : statut RAG, 3 décisions prises, 3 actions avec owners, prochain COPIL daté.","Tu demandes à chaque membre de l''équipe de présenter son bilan.","Tu distribues un rapport de 20 pages et tu pars sans résumé oral."],"correctIndex":0,"correction":"Le COMEX raisonne en synthèse, pas en détail. Un résumé RAG (Rouge-Ambre-Vert) + décisions + actions est le standard du reporting exécutif."}],"closing":"COPIL conclu. Les décisions sont enregistrées. Le COMEX repart avec de la visibilité."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-1', 0, 'Le CFO : « Vous êtes à 60 % du budget consommé pour 45 % du scope livré. Comment vous l''expliquez ? »', 'Le CFO : « Vous êtes à 60 % du budget consommé pour 45 % du scope livré. Comment vous l''expliquez ? »', 'Comment tu réponds à cette question sur le budget en COPIL ?', 'Comment tu réponds à cette question sur le budget en COPIL ?', 'Tu présentes l''analyse des écarts (complexité technique imprévue, dette legacy), la CPI (Cost Performance Index) et le plan correctif avec jalons révisés.', 'Tu présentes l''analyse des écarts (complexité technique imprévue, dette legacy), la CPI (Cost Performance Index) et le plan correctif avec jalons révisés.', 'Tu accuses l''équipe de mauvaise gestion pour protéger ta crédibilité.', 'Tu accuses l''équipe de mauvaise gestion pour protéger ta crédibilité.', 'Tu minimises l''écart en disant que c''est "dans les normes du marché".', 'Tu minimises l''écart en disant que c''est "dans les normes du marché".', 0, 'En COPIL, les sponsors attendent des données factuelles et un plan d''action — pas des excuses. La CPI et le SPI (Schedule Performance Index) sont les indicateurs standards du management de projet (PMBOK).', 'En COPIL, les sponsors attendent des données factuelles et un plan d''action — pas des excuses. La CPI et le SPI (Schedule Performance Index) sont les indicateurs standards du management de projet (PMBOK).', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-1', 1, 'Le CPO : « Le planning prévoyait une mise en prod en septembre. On est en octobre. Quand livrez-vous vraiment ? »', 'Le CPO : « Le planning prévoyait une mise en prod en septembre. On est en octobre. Quand livrez-vous vraiment ? »', 'Comment tu communiques une nouvelle date de livraison révisée ?', 'Comment tu communiques une nouvelle date de livraison révisée ?', 'Tu présentes la date révisée fondée sur la vélocité réelle mesurée, avec les hypothèses et les marges de risque clairement explicitées.', 'Tu présentes la date révisée fondée sur la vélocité réelle mesurée, avec les hypothèses et les marges de risque clairement explicitées.', 'Tu donnes une date optimiste pour calmer les inquiétudes.', 'Tu donnes une date optimiste pour calmer les inquiétudes.', 'Tu dis que la date sera communiquée la semaine prochaine pour gagner du temps.', 'Tu dis que la date sera communiquée la semaine prochaine pour gagner du temps.', 0, 'Une date révisée crédible repose sur des données réelles (vélocité, burn-down). Donner une date sans base solide détruit la confiance au prochain COPIL.', 'Une date révisée crédible repose sur des données réelles (vélocité, burn-down). Donner une date sans base solide détruit la confiance au prochain COPIL.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-1', 2, 'La DSI : « On envisage de couper le budget de 20 % sur ce projet pour financer une initiative stratégique urgente. »', 'La DSI : « On envisage de couper le budget de 20 % sur ce projet pour financer une initiative stratégique urgente. »', 'Comment tu réagis à cette décision de réduction budgétaire ?', 'Comment tu réagis à cette décision de réduction budgétaire ?', 'Tu présentes immédiatement l''analyse d''impact sur le scope et les délais — et tu demandes une décision formelle sur ce qu''on sacrifie.', 'Tu présentes immédiatement l''analyse d''impact sur le scope et les délais — et tu demandes une décision formelle sur ce qu''on sacrifie.', 'Tu acceptes sans broncher pour ne pas créer de tension avec la direction.', 'Tu acceptes sans broncher pour ne pas créer de tension avec la direction.', 'Tu refuses catégoriquement et tu quittes la réunion.', 'Tu refuses catégoriquement et tu quittes la réunion.', 0, 'Une réduction budgétaire impose un arbitrage scope/délai/qualité. Le PM est là pour présenter les impacts objectivement et obtenir une décision formelle — pas pour absorber silencieusement la contrainte.', 'Une réduction budgétaire impose un arbitrage scope/délai/qualité. Le PM est là pour présenter les impacts objectivement et obtenir une décision formelle — pas pour absorber silencieusement la contrainte.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-1', 3, 'Le COMEX veut un dashboard de suivi en temps réel accessible depuis leur mobile.', 'Le COMEX veut un dashboard de suivi en temps réel accessible depuis leur mobile.', 'Comment tu traites cette nouvelle demande du COMEX ?', 'Comment tu traites cette nouvelle demande du COMEX ?', 'Tu notes la demande comme un nouveau besoin, tu analyses l''impact sur le backlog existant et tu proposes un arbitrage au prochain COPIL.', 'Tu notes la demande comme un nouveau besoin, tu analyses l''impact sur le backlog existant et tu proposes un arbitrage au prochain COPIL.', 'Tu promets de livrer le dashboard pour le prochain COPIL sans analyser l''impact.', 'Tu promets de livrer le dashboard pour le prochain COPIL sans analyser l''impact.', 'Tu expliques que ce n''est pas dans le scope et tu refuses d''en discuter.', 'Tu expliques que ce n''est pas dans le scope et tu refuses d''en discuter.', 0, 'Toute nouvelle demande COMEX doit passer par la gouvernance du changement. Promettre sans analyser crée des attentes non maîtrisées et compromet le planning.', 'Toute nouvelle demande COMEX doit passer par la gouvernance du changement. Promettre sans analyser crée des attentes non maîtrisées et compromet le planning.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-1', 4, 'Fin du COPIL. Le COMEX attend un résumé décisionnel avant de partir.', 'Fin du COPIL. Le COMEX attend un résumé décisionnel avant de partir.', 'Quel format adoptes-tu pour conclure le COPIL ?', 'Quel format adoptes-tu pour conclure le COPIL ?', 'Un résumé exécutif de 2 minutes : statut RAG, 3 décisions prises, 3 actions avec owners, prochain COPIL daté.', 'Un résumé exécutif de 2 minutes : statut RAG, 3 décisions prises, 3 actions avec owners, prochain COPIL daté.', 'Tu demandes à chaque membre de l''équipe de présenter son bilan.', 'Tu demandes à chaque membre de l''équipe de présenter son bilan.', 'Tu distribues un rapport de 20 pages et tu pars sans résumé oral.', 'Tu distribues un rapport de 20 pages et tu pars sans résumé oral.', 0, 'Le COMEX raisonne en synthèse, pas en détail. Un résumé RAG (Rouge-Ambre-Vert) + décisions + actions est le standard du reporting exécutif.', 'Le COMEX raisonne en synthèse, pas en détail. Un résumé RAG (Rouge-Ambre-Vert) + décisions + actions est le standard du reporting exécutif.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('copil-2', 'copil', 'COPIL #2 — Revue de risques stratégiques', 'COPIL #2 — Revue de risques stratégiques', 'Ce COPIL exceptionnel est convoqué suite à des signaux d''alerte sur la sécurité des données et une pression concurrentielle accrue.', 'Ce COPIL exceptionnel est convoqué suite à des signaux d''alerte sur la sécurité des données et une pression concurrentielle accrue.', 'Les risques stratégiques sont arbitrés. Le projet repart sur des bases sécurisées.', 'Les risques stratégiques sont arbitrés. Le projet repart sur des bases sécurisées.', '{"kind":"copil","title":"COPIL #2 — Revue de risques stratégiques","opening":"Ce COPIL exceptionnel est convoqué suite à des signaux d''alerte sur la sécurité des données et une pression concurrentielle accrue.","questions":[{"npcLine":"La DSI : « Notre audit de sécurité a relevé des failles dans la gestion des accès sur le projet. Le RSSI demande une pause du projet. »","question":"Comment tu gères cette demande de pause sécurité ?","options":["Tu appuies la décision d''audit complet, tu identifies les composants à risque et tu proposes un plan de remédiation avec timeline.","Tu t''opposes à la pause — ça va retarder le planning.","Tu minimises les failles pour éviter d''alarmer le COMEX."],"correctIndex":0,"correction":"La sécurité n''est jamais négociable. Appuyer une pause ciblée et proposer un plan de remédiation rapide démontre de la maturité PM et protège l''entreprise."},{"npcLine":"Le CPO : « Un concurrent vient de lancer une feature similaire à la nôtre. Doit-on accélérer ou pivoter ? »","question":"Comment tu arbitres cette décision stratégique en COPIL ?","options":["Tu présentes une analyse rapide (time-to-market vs qualité, différenciation possible) et tu demandes une décision formelle du COMEX sur la direction.","Tu décides seul d''accélérer pour montrer de la réactivité.","Tu proposes d''abandonner le projet et de copier la solution concurrente."],"correctIndex":0,"correction":"Les décisions stratégiques appartiennent au COMEX. Le PM apporte l''analyse factuelle et les options, pas la décision finale. C''est la gouvernance de projet."},{"npcLine":"Le CFO : « On a une opportunité de financement externe si on démontre une MVP en 6 semaines. »","question":"Comment tu évalues la faisabilité d''une MVP en 6 semaines ?","options":["Tu identifies le scope minimal viable avec l''équipe, tu estimes honnêtement sur la vélocité réelle et tu présentes les conditions de succès et les risques.","Tu dis oui immédiatement pour ne pas rater l''opportunité.","Tu dis que c''est impossible sans même analyser."],"correctIndex":0,"correction":"Un engagement MVP doit être fondé sur une estimation honnête. Un \"oui\" sans analyse crée un engagement que tu ne peux pas tenir — ce qui détruit la confiance plus que de dire non."},{"npcLine":"Un membre du COMEX propose de changer l''architecture technique en cours de projet.","question":"Comment tu traites cette proposition d''architecture en COPIL ?","options":["Tu documentes la proposition, tu demandes une analyse d''impact technique à l''équipe et tu planifies une décision formelle dans les 5 jours ouvrés.","Tu acceptes immédiatement pour satisfaire le COMEX.","Tu rejettes la proposition sans analyse — changer d''architecture c''est trop risqué."],"correctIndex":0,"correction":"Un changement d''architecture en cours de projet a un impact majeur. Il requiert une analyse d''impact structurée avant toute décision — ni acceptation aveugle ni refus réflexe."},{"npcLine":"Le COMEX demande à augmenter l''équipe de 3 personnes pour accélérer.","question":"Quelle est ta réponse sur l''ajout de ressources en cours de projet ?","options":["Tu rappelles la Loi de Brooks (ajouter des personnes en retard aggrave le retard à court terme) et tu proposes une intégration progressive avec un plan d''onboarding.","Tu acceptes les 3 personnes avec enthousiasme — plus de ressources = plus de productivité.","Tu refuses — l''équipe actuelle n''a pas envie de nouveaux arrivants."],"correctIndex":0,"correction":"La Loi de Brooks est réelle : les nouveaux arrivants coûtent du temps d''intégration à l''équipe existante. Un plan d''onboarding progressif est indispensable."}],"closing":"Les risques stratégiques sont arbitrés. Le projet repart sur des bases sécurisées."}'::jsonb, '{"kind":"copil","title":"COPIL #2 — Revue de risques stratégiques","opening":"Ce COPIL exceptionnel est convoqué suite à des signaux d''alerte sur la sécurité des données et une pression concurrentielle accrue.","questions":[{"npcLine":"La DSI : « Notre audit de sécurité a relevé des failles dans la gestion des accès sur le projet. Le RSSI demande une pause du projet. »","question":"Comment tu gères cette demande de pause sécurité ?","options":["Tu appuies la décision d''audit complet, tu identifies les composants à risque et tu proposes un plan de remédiation avec timeline.","Tu t''opposes à la pause — ça va retarder le planning.","Tu minimises les failles pour éviter d''alarmer le COMEX."],"correctIndex":0,"correction":"La sécurité n''est jamais négociable. Appuyer une pause ciblée et proposer un plan de remédiation rapide démontre de la maturité PM et protège l''entreprise."},{"npcLine":"Le CPO : « Un concurrent vient de lancer une feature similaire à la nôtre. Doit-on accélérer ou pivoter ? »","question":"Comment tu arbitres cette décision stratégique en COPIL ?","options":["Tu présentes une analyse rapide (time-to-market vs qualité, différenciation possible) et tu demandes une décision formelle du COMEX sur la direction.","Tu décides seul d''accélérer pour montrer de la réactivité.","Tu proposes d''abandonner le projet et de copier la solution concurrente."],"correctIndex":0,"correction":"Les décisions stratégiques appartiennent au COMEX. Le PM apporte l''analyse factuelle et les options, pas la décision finale. C''est la gouvernance de projet."},{"npcLine":"Le CFO : « On a une opportunité de financement externe si on démontre une MVP en 6 semaines. »","question":"Comment tu évalues la faisabilité d''une MVP en 6 semaines ?","options":["Tu identifies le scope minimal viable avec l''équipe, tu estimes honnêtement sur la vélocité réelle et tu présentes les conditions de succès et les risques.","Tu dis oui immédiatement pour ne pas rater l''opportunité.","Tu dis que c''est impossible sans même analyser."],"correctIndex":0,"correction":"Un engagement MVP doit être fondé sur une estimation honnête. Un \"oui\" sans analyse crée un engagement que tu ne peux pas tenir — ce qui détruit la confiance plus que de dire non."},{"npcLine":"Un membre du COMEX propose de changer l''architecture technique en cours de projet.","question":"Comment tu traites cette proposition d''architecture en COPIL ?","options":["Tu documentes la proposition, tu demandes une analyse d''impact technique à l''équipe et tu planifies une décision formelle dans les 5 jours ouvrés.","Tu acceptes immédiatement pour satisfaire le COMEX.","Tu rejettes la proposition sans analyse — changer d''architecture c''est trop risqué."],"correctIndex":0,"correction":"Un changement d''architecture en cours de projet a un impact majeur. Il requiert une analyse d''impact structurée avant toute décision — ni acceptation aveugle ni refus réflexe."},{"npcLine":"Le COMEX demande à augmenter l''équipe de 3 personnes pour accélérer.","question":"Quelle est ta réponse sur l''ajout de ressources en cours de projet ?","options":["Tu rappelles la Loi de Brooks (ajouter des personnes en retard aggrave le retard à court terme) et tu proposes une intégration progressive avec un plan d''onboarding.","Tu acceptes les 3 personnes avec enthousiasme — plus de ressources = plus de productivité.","Tu refuses — l''équipe actuelle n''a pas envie de nouveaux arrivants."],"correctIndex":0,"correction":"La Loi de Brooks est réelle : les nouveaux arrivants coûtent du temps d''intégration à l''équipe existante. Un plan d''onboarding progressif est indispensable."}],"closing":"Les risques stratégiques sont arbitrés. Le projet repart sur des bases sécurisées."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-2', 0, 'La DSI : « Notre audit de sécurité a relevé des failles dans la gestion des accès sur le projet. Le RSSI demande une pause du projet. »', 'La DSI : « Notre audit de sécurité a relevé des failles dans la gestion des accès sur le projet. Le RSSI demande une pause du projet. »', 'Comment tu gères cette demande de pause sécurité ?', 'Comment tu gères cette demande de pause sécurité ?', 'Tu appuies la décision d''audit complet, tu identifies les composants à risque et tu proposes un plan de remédiation avec timeline.', 'Tu appuies la décision d''audit complet, tu identifies les composants à risque et tu proposes un plan de remédiation avec timeline.', 'Tu t''opposes à la pause — ça va retarder le planning.', 'Tu t''opposes à la pause — ça va retarder le planning.', 'Tu minimises les failles pour éviter d''alarmer le COMEX.', 'Tu minimises les failles pour éviter d''alarmer le COMEX.', 0, 'La sécurité n''est jamais négociable. Appuyer une pause ciblée et proposer un plan de remédiation rapide démontre de la maturité PM et protège l''entreprise.', 'La sécurité n''est jamais négociable. Appuyer une pause ciblée et proposer un plan de remédiation rapide démontre de la maturité PM et protège l''entreprise.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
