INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-2', 2, 'Le CFO : « On a une opportunité de financement externe si on démontre une MVP en 6 semaines. »', 'Le CFO : « On a une opportunité de financement externe si on démontre une MVP en 6 semaines. »', 'Comment tu évalues la faisabilité d''une MVP en 6 semaines ?', 'Comment tu évalues la faisabilité d''une MVP en 6 semaines ?', 'Tu identifies le scope minimal viable avec l''équipe, tu estimes honnêtement sur la vélocité réelle et tu présentes les conditions de succès et les risques.', 'Tu identifies le scope minimal viable avec l''équipe, tu estimes honnêtement sur la vélocité réelle et tu présentes les conditions de succès et les risques.', 'Tu dis oui immédiatement pour ne pas rater l''opportunité.', 'Tu dis oui immédiatement pour ne pas rater l''opportunité.', 'Tu dis que c''est impossible sans même analyser.', 'Tu dis que c''est impossible sans même analyser.', 0, 'Un engagement MVP doit être fondé sur une estimation honnête. Un "oui" sans analyse crée un engagement que tu ne peux pas tenir — ce qui détruit la confiance plus que de dire non.', 'Un engagement MVP doit être fondé sur une estimation honnête. Un "oui" sans analyse crée un engagement que tu ne peux pas tenir — ce qui détruit la confiance plus que de dire non.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-2', 3, 'Un membre du COMEX propose de changer l''architecture technique en cours de projet.', 'Un membre du COMEX propose de changer l''architecture technique en cours de projet.', 'Comment tu traites cette proposition d''architecture en COPIL ?', 'Comment tu traites cette proposition d''architecture en COPIL ?', 'Tu documentes la proposition, tu demandes une analyse d''impact technique à l''équipe et tu planifies une décision formelle dans les 5 jours ouvrés.', 'Tu documentes la proposition, tu demandes une analyse d''impact technique à l''équipe et tu planifies une décision formelle dans les 5 jours ouvrés.', 'Tu acceptes immédiatement pour satisfaire le COMEX.', 'Tu acceptes immédiatement pour satisfaire le COMEX.', 'Tu rejettes la proposition sans analyse — changer d''architecture c''est trop risqué.', 'Tu rejettes la proposition sans analyse — changer d''architecture c''est trop risqué.', 0, 'Un changement d''architecture en cours de projet a un impact majeur. Il requiert une analyse d''impact structurée avant toute décision — ni acceptation aveugle ni refus réflexe.', 'Un changement d''architecture en cours de projet a un impact majeur. Il requiert une analyse d''impact structurée avant toute décision — ni acceptation aveugle ni refus réflexe.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-2', 4, 'Le COMEX demande à augmenter l''équipe de 3 personnes pour accélérer.', 'Le COMEX demande à augmenter l''équipe de 3 personnes pour accélérer.', 'Quelle est ta réponse sur l''ajout de ressources en cours de projet ?', 'Quelle est ta réponse sur l''ajout de ressources en cours de projet ?', 'Tu rappelles la Loi de Brooks (ajouter des personnes en retard aggrave le retard à court terme) et tu proposes une intégration progressive avec un plan d''onboarding.', 'Tu rappelles la Loi de Brooks (ajouter des personnes en retard aggrave le retard à court terme) et tu proposes une intégration progressive avec un plan d''onboarding.', 'Tu acceptes les 3 personnes avec enthousiasme — plus de ressources = plus de productivité.', 'Tu acceptes les 3 personnes avec enthousiasme — plus de ressources = plus de productivité.', 'Tu refuses — l''équipe actuelle n''a pas envie de nouveaux arrivants.', 'Tu refuses — l''équipe actuelle n''a pas envie de nouveaux arrivants.', 0, 'La Loi de Brooks est réelle : les nouveaux arrivants coûtent du temps d''intégration à l''équipe existante. Un plan d''onboarding progressif est indispensable.', 'La Loi de Brooks est réelle : les nouveaux arrivants coûtent du temps d''intégration à l''équipe existante. Un plan d''onboarding progressif est indispensable.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('copil-3', 'copil', 'COPIL #3 — Bilan annuel & trajectoire', 'COPIL #3 — Bilan annuel & trajectoire', 'COPIL de fin d''année. Le COMEX évalue la performance du portfolio projets data et fixe les orientations pour l''année suivante.', 'COPIL de fin d''année. Le COMEX évalue la performance du portfolio projets data et fixe les orientations pour l''année suivante.', 'La trajectoire annuelle est validée. Les grandes orientations sont fixées pour l''année à venir.', 'La trajectoire annuelle est validée. Les grandes orientations sont fixées pour l''année à venir.', '{"kind":"copil","title":"COPIL #3 — Bilan annuel & trajectoire","opening":"COPIL de fin d''année. Le COMEX évalue la performance du portfolio projets data et fixe les orientations pour l''année suivante.","questions":[{"npcLine":"Le CEO : « Quel est le ROI réel de nos projets data cette année ? »","question":"Comment tu présentes le ROI des projets data au COMEX ?","options":["Tu présentes les indicateurs mesurables : temps de traitement réduit, coûts évités, revenus additionnels, satisfaction utilisateurs — avec les hypothèses clairement exprimées.","Tu présentes uniquement les succès techniques sans mentionner les coûts.","Tu dis que le ROI des projets data ne se mesure pas à court terme."],"correctIndex":0,"correction":"Le COMEX raisonne en valeur business. Présenter le ROI avec des métriques concrètes (temps, coût, revenus) et des hypothèses transparentes est le langage du reporting exécutif."},{"npcLine":"La DSI : « On veut passer 100 % en Agile l''année prochaine. Qu''est-ce que ça implique ? »","question":"Comment tu présentes la transformation Agile au COMEX ?","options":["Tu expliques les prérequis (formation, changement de gouvernance, nouveaux rituels), les bénéfices attendus et les risques de transformation mal conduite.","Tu dis que l''Agile c''est simple — il suffit de faire des Sprints.","Tu t''opposes à la transformation — le mode projet actuel fonctionne bien."],"correctIndex":0,"correction":"Une transformation Agile est un changement organisationnel profond. Le COMEX doit comprendre les implications réelles (gouvernance, culture, compétences) pour prendre une décision éclairée."},{"npcLine":"Le CPO : « On a 12 projets en cours simultanément. Comment on priorise ? »","question":"Quelle méthode proposes-tu pour prioriser le portfolio ?","options":["Une matrice valeur/effort avec critères pondérés (impact business, risque, dépendances), validée par le COMEX et mise à jour trimestriellement.","Chaque directeur garde ses projets — on ne touche à rien.","On arrête 50 % des projets au hasard pour réduire la surcharge."],"correctIndex":0,"correction":"La priorisation de portfolio est un exercice de gouvernance stratégique. Une matrice valeur/effort transparente avec critères explicites est la base de la gestion de programme."},{"npcLine":"Un directeur remet en question la méthodologie Scrum — il préfère un retour au mode cascade.","question":"Comment tu défends le choix méthodologique en COPIL ?","options":["Tu présentes des données concrètes sur les gains apportés par Scrum sur ce projet, et tu proposes d''adapter la méthodologie plutôt que d''en changer.","Tu cèdes immédiatement pour ne pas contrarier le directeur.","Tu attaques le directeur en disant que la cascade est dépassée."],"correctIndex":0,"correction":"Les décisions méthodologiques doivent être fondées sur des données, pas des préférences. Proposer des adaptations est plus constructif qu''une défense rigide ou qu''une capitulation."},{"npcLine":"Le COMEX demande ton plan pour l''année prochaine en 60 secondes.","question":"Comment tu structures un pitch de plan annuel en 60 secondes ?","options":["Objectifs business clés → 3 initiatives prioritaires → ressources nécessaires → premier jalon dans 90 jours.","Tu lis les 15 slides de ton PowerPoint en accéléré.","Tu demandes un report — 60 secondes ce n''est pas assez pour un plan annuel."],"correctIndex":0,"correction":"Le Elevator Pitch d''un plan annuel : objectifs → initiatives → ressources → premier jalon. 60 secondes suffit si la structure est claire. Le COMEX apprécie la concision."}],"closing":"La trajectoire annuelle est validée. Les grandes orientations sont fixées pour l''année à venir."}'::jsonb, '{"kind":"copil","title":"COPIL #3 — Bilan annuel & trajectoire","opening":"COPIL de fin d''année. Le COMEX évalue la performance du portfolio projets data et fixe les orientations pour l''année suivante.","questions":[{"npcLine":"Le CEO : « Quel est le ROI réel de nos projets data cette année ? »","question":"Comment tu présentes le ROI des projets data au COMEX ?","options":["Tu présentes les indicateurs mesurables : temps de traitement réduit, coûts évités, revenus additionnels, satisfaction utilisateurs — avec les hypothèses clairement exprimées.","Tu présentes uniquement les succès techniques sans mentionner les coûts.","Tu dis que le ROI des projets data ne se mesure pas à court terme."],"correctIndex":0,"correction":"Le COMEX raisonne en valeur business. Présenter le ROI avec des métriques concrètes (temps, coût, revenus) et des hypothèses transparentes est le langage du reporting exécutif."},{"npcLine":"La DSI : « On veut passer 100 % en Agile l''année prochaine. Qu''est-ce que ça implique ? »","question":"Comment tu présentes la transformation Agile au COMEX ?","options":["Tu expliques les prérequis (formation, changement de gouvernance, nouveaux rituels), les bénéfices attendus et les risques de transformation mal conduite.","Tu dis que l''Agile c''est simple — il suffit de faire des Sprints.","Tu t''opposes à la transformation — le mode projet actuel fonctionne bien."],"correctIndex":0,"correction":"Une transformation Agile est un changement organisationnel profond. Le COMEX doit comprendre les implications réelles (gouvernance, culture, compétences) pour prendre une décision éclairée."},{"npcLine":"Le CPO : « On a 12 projets en cours simultanément. Comment on priorise ? »","question":"Quelle méthode proposes-tu pour prioriser le portfolio ?","options":["Une matrice valeur/effort avec critères pondérés (impact business, risque, dépendances), validée par le COMEX et mise à jour trimestriellement.","Chaque directeur garde ses projets — on ne touche à rien.","On arrête 50 % des projets au hasard pour réduire la surcharge."],"correctIndex":0,"correction":"La priorisation de portfolio est un exercice de gouvernance stratégique. Une matrice valeur/effort transparente avec critères explicites est la base de la gestion de programme."},{"npcLine":"Un directeur remet en question la méthodologie Scrum — il préfère un retour au mode cascade.","question":"Comment tu défends le choix méthodologique en COPIL ?","options":["Tu présentes des données concrètes sur les gains apportés par Scrum sur ce projet, et tu proposes d''adapter la méthodologie plutôt que d''en changer.","Tu cèdes immédiatement pour ne pas contrarier le directeur.","Tu attaques le directeur en disant que la cascade est dépassée."],"correctIndex":0,"correction":"Les décisions méthodologiques doivent être fondées sur des données, pas des préférences. Proposer des adaptations est plus constructif qu''une défense rigide ou qu''une capitulation."},{"npcLine":"Le COMEX demande ton plan pour l''année prochaine en 60 secondes.","question":"Comment tu structures un pitch de plan annuel en 60 secondes ?","options":["Objectifs business clés → 3 initiatives prioritaires → ressources nécessaires → premier jalon dans 90 jours.","Tu lis les 15 slides de ton PowerPoint en accéléré.","Tu demandes un report — 60 secondes ce n''est pas assez pour un plan annuel."],"correctIndex":0,"correction":"Le Elevator Pitch d''un plan annuel : objectifs → initiatives → ressources → premier jalon. 60 secondes suffit si la structure est claire. Le COMEX apprécie la concision."}],"closing":"La trajectoire annuelle est validée. Les grandes orientations sont fixées pour l''année à venir."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
