INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('copil-3', 4, 'Le COMEX demande ton plan pour l''année prochaine en 60 secondes.', 'Le COMEX demande ton plan pour l''année prochaine en 60 secondes.', 'Comment tu structures un pitch de plan annuel en 60 secondes ?', 'Comment tu structures un pitch de plan annuel en 60 secondes ?', 'Objectifs business clés → 3 initiatives prioritaires → ressources nécessaires → premier jalon dans 90 jours.', 'Objectifs business clés → 3 initiatives prioritaires → ressources nécessaires → premier jalon dans 90 jours.', 'Tu lis les 15 slides de ton PowerPoint en accéléré.', 'Tu lis les 15 slides de ton PowerPoint en accéléré.', 'Tu demandes un report — 60 secondes ce n''est pas assez pour un plan annuel.', 'Tu demandes un report — 60 secondes ce n''est pas assez pour un plan annuel.', 0, 'Le Elevator Pitch d''un plan annuel : objectifs → initiatives → ressources → premier jalon. 60 secondes suffit si la structure est claire. Le COMEX apprécie la concision.', 'Le Elevator Pitch d''un plan annuel : objectifs → initiatives → ressources → premier jalon. 60 secondes suffit si la structure est claire. Le COMEX apprécie la concision.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('scrum-sprint-planning-1', 'sprint-planning', 'Sprint Planning — Sprint 4', 'Sprint Planning — Sprint 4', 'L''équipe se réunit pour planifier le Sprint 4. Product Backlog refiné, vélocité connue (38 points en moyenne sur les 3 derniers sprints). Tu facilites.', 'L''équipe se réunit pour planifier le Sprint 4. Product Backlog refiné, vélocité connue (38 points en moyenne sur les 3 derniers sprints). Tu facilites.', 'Sprint Planning terminé. Le Sprint Goal est validé. L''équipe démarre avec une vision claire.', 'Sprint Planning terminé. Le Sprint Goal est validé. L''équipe démarre avec une vision claire.', '{"kind":"sprint-planning","title":"Sprint Planning — Sprint 4","opening":"L''équipe se réunit pour planifier le Sprint 4. Product Backlog refiné, vélocité connue (38 points en moyenne sur les 3 derniers sprints). Tu facilites.","questions":[{"npcLine":"L''équipe demande : « On prend combien de points ce Sprint ? La deadline de fin de mois approche. »","question":"Comment tu détermines la capacité du Sprint ?","options":["Tu te bases sur la vélocité historique (38 pts) ajustée des congés et absences connues — pas sur les souhaits du management.","Tu prends 60 points pour montrer de l''ambition au COMEX.","Tu laisses le management décider de la capacité."],"correctIndex":0,"correction":"La capacité Sprint est déterminée par la vélocité historique réelle, pas par la pression extérieure. Sur-engager détruit la confiance et la qualité."},{"npcLine":"Le PO veut mettre 2 User Stories vagues (sans critères d''acceptation) dans le Sprint.","question":"Comment tu gères des US sans critères d''acceptation en Sprint Planning ?","options":["Tu bloques ces US jusqu''à ce que les critères d''acceptation soient clairs et acceptés par l''équipe — sinon l''équipe ne sait pas ce qu''elle livre.","Tu acceptes pour ne pas ralentir le planning.","Tu demandes à l''équipe de deviner les critères pendant le Sprint."],"correctIndex":0,"correction":"Une User Story sans critères d''acceptation ne peut pas entrer en Sprint. La Définition of Ready exige des critères clairs, indépendants et estimables (INVEST)."},{"npcLine":"Un développeur identifie une dépendance technique critique avec l''équipe infrastructure qui ne sera pas disponible avant mi-Sprint.","question":"Comment tu gères cette dépendance en Sprint Planning ?","options":["Tu ajustes le Sprint Goal pour exclure les US bloquées par cette dépendance — ou tu commences par les US indépendantes et tu planifies la résolution de la dépendance.","Tu ignores la dépendance et tu espères que l''infra sera disponible à temps.","Tu reportes tout le Sprint pour attendre la disponibilité de l''infra."],"correctIndex":0,"correction":"Les dépendances doivent être identifiées et gérées en Sprint Planning. Un Sprint Goal clair et réaliste exclut les US bloquées par des dépendances non résolues."},{"npcLine":"L''équipe débat pendant 45 minutes sur l''estimation d''une US complexe. Le Planning Poker est bloqué.","question":"Comment tu débloques une estimation bloquée en Planning Poker ?","options":["Tu utilises la technique du « spike » : 2 jours de recherche technique time-boxée pour lever l''incertitude, puis ré-estimation.","Tu imposes l''estimation la plus haute pour être sûr.","Tu retires l''US du Sprint pour ne pas perdre plus de temps."],"correctIndex":0,"correction":"Un spike est une User Story d''exploration time-boxée pour réduire l''incertitude technique. C''est la réponse Scrum appropriée quand l''équipe ne peut pas estimer faute d''information."},{"npcLine":"À la fin du Sprint Planning, le Sprint Goal n''est pas encore formulé.","question":"Pourquoi le Sprint Goal est-il indispensable et comment le formules-tu ?","options":["Le Sprint Goal donne un objectif cohérent à l''équipe : une phrase qui exprime la valeur à livrer ce Sprint, validée par le PO et l''équipe ensemble.","Le Sprint Goal est optionnel — la liste des US suffit.","Tu copies le Sprint Goal du Sprint précédent pour gagner du temps."],"correctIndex":0,"correction":"Le Sprint Goal est le \"pourquoi\" du Sprint. Il permet à l''équipe de prendre des décisions autonomes en cas d''imprévu. Sans lui, l''équipe exécute sans comprendre la valeur créée."}],"closing":"Sprint Planning terminé. Le Sprint Goal est validé. L''équipe démarre avec une vision claire."}'::jsonb, '{"kind":"sprint-planning","title":"Sprint Planning — Sprint 4","opening":"L''équipe se réunit pour planifier le Sprint 4. Product Backlog refiné, vélocité connue (38 points en moyenne sur les 3 derniers sprints). Tu facilites.","questions":[{"npcLine":"L''équipe demande : « On prend combien de points ce Sprint ? La deadline de fin de mois approche. »","question":"Comment tu détermines la capacité du Sprint ?","options":["Tu te bases sur la vélocité historique (38 pts) ajustée des congés et absences connues — pas sur les souhaits du management.","Tu prends 60 points pour montrer de l''ambition au COMEX.","Tu laisses le management décider de la capacité."],"correctIndex":0,"correction":"La capacité Sprint est déterminée par la vélocité historique réelle, pas par la pression extérieure. Sur-engager détruit la confiance et la qualité."},{"npcLine":"Le PO veut mettre 2 User Stories vagues (sans critères d''acceptation) dans le Sprint.","question":"Comment tu gères des US sans critères d''acceptation en Sprint Planning ?","options":["Tu bloques ces US jusqu''à ce que les critères d''acceptation soient clairs et acceptés par l''équipe — sinon l''équipe ne sait pas ce qu''elle livre.","Tu acceptes pour ne pas ralentir le planning.","Tu demandes à l''équipe de deviner les critères pendant le Sprint."],"correctIndex":0,"correction":"Une User Story sans critères d''acceptation ne peut pas entrer en Sprint. La Définition of Ready exige des critères clairs, indépendants et estimables (INVEST)."},{"npcLine":"Un développeur identifie une dépendance technique critique avec l''équipe infrastructure qui ne sera pas disponible avant mi-Sprint.","question":"Comment tu gères cette dépendance en Sprint Planning ?","options":["Tu ajustes le Sprint Goal pour exclure les US bloquées par cette dépendance — ou tu commences par les US indépendantes et tu planifies la résolution de la dépendance.","Tu ignores la dépendance et tu espères que l''infra sera disponible à temps.","Tu reportes tout le Sprint pour attendre la disponibilité de l''infra."],"correctIndex":0,"correction":"Les dépendances doivent être identifiées et gérées en Sprint Planning. Un Sprint Goal clair et réaliste exclut les US bloquées par des dépendances non résolues."},{"npcLine":"L''équipe débat pendant 45 minutes sur l''estimation d''une US complexe. Le Planning Poker est bloqué.","question":"Comment tu débloques une estimation bloquée en Planning Poker ?","options":["Tu utilises la technique du « spike » : 2 jours de recherche technique time-boxée pour lever l''incertitude, puis ré-estimation.","Tu imposes l''estimation la plus haute pour être sûr.","Tu retires l''US du Sprint pour ne pas perdre plus de temps."],"correctIndex":0,"correction":"Un spike est une User Story d''exploration time-boxée pour réduire l''incertitude technique. C''est la réponse Scrum appropriée quand l''équipe ne peut pas estimer faute d''information."},{"npcLine":"À la fin du Sprint Planning, le Sprint Goal n''est pas encore formulé.","question":"Pourquoi le Sprint Goal est-il indispensable et comment le formules-tu ?","options":["Le Sprint Goal donne un objectif cohérent à l''équipe : une phrase qui exprime la valeur à livrer ce Sprint, validée par le PO et l''équipe ensemble.","Le Sprint Goal est optionnel — la liste des US suffit.","Tu copies le Sprint Goal du Sprint précédent pour gagner du temps."],"correctIndex":0,"correction":"Le Sprint Goal est le \"pourquoi\" du Sprint. Il permet à l''équipe de prendre des décisions autonomes en cas d''imprévu. Sans lui, l''équipe exécute sans comprendre la valeur créée."}],"closing":"Sprint Planning terminé. Le Sprint Goal est validé. L''équipe démarre avec une vision claire."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
