INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-planning-1', 4, 'À la fin du Sprint Planning, le Sprint Goal n''est pas encore formulé.', 'À la fin du Sprint Planning, le Sprint Goal n''est pas encore formulé.', 'Pourquoi le Sprint Goal est-il indispensable et comment le formules-tu ?', 'Pourquoi le Sprint Goal est-il indispensable et comment le formules-tu ?', 'Le Sprint Goal donne un objectif cohérent à l''équipe : une phrase qui exprime la valeur à livrer ce Sprint, validée par le PO et l''équipe ensemble.', 'Le Sprint Goal donne un objectif cohérent à l''équipe : une phrase qui exprime la valeur à livrer ce Sprint, validée par le PO et l''équipe ensemble.', 'Le Sprint Goal est optionnel — la liste des US suffit.', 'Le Sprint Goal est optionnel — la liste des US suffit.', 'Tu copies le Sprint Goal du Sprint précédent pour gagner du temps.', 'Tu copies le Sprint Goal du Sprint précédent pour gagner du temps.', 0, 'Le Sprint Goal est le "pourquoi" du Sprint. Il permet à l''équipe de prendre des décisions autonomes en cas d''imprévu. Sans lui, l''équipe exécute sans comprendre la valeur créée.', 'Le Sprint Goal est le "pourquoi" du Sprint. Il permet à l''équipe de prendre des décisions autonomes en cas d''imprévu. Sans lui, l''équipe exécute sans comprendre la valeur créée.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('scrum-daily-2', 'daily', 'Daily Scrum — Sprint 4, Jour 5', 'Daily Scrum — Sprint 4, Jour 5', 'Daily Scrum de 15 minutes. L''équipe se synchronise. Hugo semble bloqué depuis hier.', 'Daily Scrum de 15 minutes. L''équipe se synchronise. Hugo semble bloqué depuis hier.', 'Daily terminé en 14 minutes. L''équipe est synchronisée. Les blocages ont un owner.', 'Daily terminé en 14 minutes. L''équipe est synchronisée. Les blocages ont un owner.', '{"kind":"daily","title":"Daily Scrum — Sprint 4, Jour 5","opening":"Daily Scrum de 15 minutes. L''équipe se synchronise. Hugo semble bloqué depuis hier.","questions":[{"npcLine":"Hugo : « Hier j''ai travaillé sur la migration, aujourd''hui je continue. Rien de bloquant. » — mais son visage dit le contraire.","question":"Comment tu gères un signal de blocage non verbal en Daily ?","options":["Tu notes le signal, tu laisses le Daily se terminer en 15 min et tu invites Hugo à un point rapide en bilatéral juste après.","Tu interroges Hugo longuement pendant le Daily devant toute l''équipe.","Tu ignores — si Hugo ne dit rien c''est que tout va bien."],"correctIndex":0,"correction":"Le Daily n''est pas un lieu de résolution de problèmes — c''est un lieu de synchronisation. Les blocages se traitent en bilatéral ou en sous-groupe après le Daily (« After-party »)."},{"npcLine":"Rania : « Le Daily prend 30 minutes chaque matin — les gens parlent de tout et de rien. »","question":"Comment tu recadres un Daily qui dépasse son time-box ?","options":["Tu rappelles les 3 questions Scrum (hier / aujourd''hui / blocage), tu time-boxes chaque personne à 2 min et tu renvois les discussions hors sujet après le Daily.","Tu annules le Daily — il ne sert à rien.","Tu laisses faire — la liberté d''expression est importante."],"correctIndex":0,"correction":"Le Daily de 15 min est un time-box strict. Les 3 questions focalisent sur la synchronisation vers le Sprint Goal — pas sur les statuts détaillés. Le Scrum Master est garant du format."},{"npcLine":"Léa : « Je suis bloquée depuis hier soir sur un bug de build. J''ai essayé 3 solutions différentes. »","question":"Comment tu traites ce blocage technique en Daily ?","options":["Tu identifies qui peut aider Léa (dev expert ou archi), tu organises un mob-debugging de 30 min après le Daily et tu mets le blocage dans le Scrum Board.","Tu demandes à Léa de continuer à chercher seule jusqu''à midi.","Tu escalades immédiatement le bug au COMEX."],"correctIndex":0,"correction":"Les blocages doivent être résolus rapidement. Le Scrum Master (ou PM) facilite la résolution en identifiant la bonne ressource et en time-boxant la résolution."},{"npcLine":"Le management assiste au Daily et commence à poser des questions détaillées sur l''avancement.","question":"Comment tu gères la présence intrusive du management en Daily ?","options":["Tu expliques poliment que le Daily est un événement pour l''équipe de développement — le management peut observer silencieusement mais pas intervenir.","Tu cèdes et tu laisses le management dominer le Daily.","Tu demandes au management de quitter la réunion."],"correctIndex":0,"correction":"Le Daily Scrum est réservé aux développeurs. Le management peut être « poulet » (observateur) mais pas « cochon » (participant décisionnel). C''est une règle Scrum fondamentale."},{"npcLine":"Fin du Daily. Le Sprint Burndown montre un retard de 30 % sur les 3 premiers jours.","question":"Comment tu interprètes et réagis à ce retard sur le Burndown ?","options":["Tu organises un point d''équipe rapide pour identifier la cause (mauvaise estimation, complexité imprévue, blocage) et tu ajustes le plan de Sprint si nécessaire.","Tu paniques et tu envoies un email d''alarme au COMEX.","Tu ignores — 3 jours c''est trop tôt pour s''inquiéter."],"correctIndex":0,"correction":"Un retard de 30 % en J3 est un signal d''alerte à inspecter sans dramatiser. L''adaptation rapide (Scrum Pilier Adaptation) évite que la situation empire jusqu''à la Sprint Review."}],"closing":"Daily terminé en 14 minutes. L''équipe est synchronisée. Les blocages ont un owner."}'::jsonb, '{"kind":"daily","title":"Daily Scrum — Sprint 4, Jour 5","opening":"Daily Scrum de 15 minutes. L''équipe se synchronise. Hugo semble bloqué depuis hier.","questions":[{"npcLine":"Hugo : « Hier j''ai travaillé sur la migration, aujourd''hui je continue. Rien de bloquant. » — mais son visage dit le contraire.","question":"Comment tu gères un signal de blocage non verbal en Daily ?","options":["Tu notes le signal, tu laisses le Daily se terminer en 15 min et tu invites Hugo à un point rapide en bilatéral juste après.","Tu interroges Hugo longuement pendant le Daily devant toute l''équipe.","Tu ignores — si Hugo ne dit rien c''est que tout va bien."],"correctIndex":0,"correction":"Le Daily n''est pas un lieu de résolution de problèmes — c''est un lieu de synchronisation. Les blocages se traitent en bilatéral ou en sous-groupe après le Daily (« After-party »)."},{"npcLine":"Rania : « Le Daily prend 30 minutes chaque matin — les gens parlent de tout et de rien. »","question":"Comment tu recadres un Daily qui dépasse son time-box ?","options":["Tu rappelles les 3 questions Scrum (hier / aujourd''hui / blocage), tu time-boxes chaque personne à 2 min et tu renvois les discussions hors sujet après le Daily.","Tu annules le Daily — il ne sert à rien.","Tu laisses faire — la liberté d''expression est importante."],"correctIndex":0,"correction":"Le Daily de 15 min est un time-box strict. Les 3 questions focalisent sur la synchronisation vers le Sprint Goal — pas sur les statuts détaillés. Le Scrum Master est garant du format."},{"npcLine":"Léa : « Je suis bloquée depuis hier soir sur un bug de build. J''ai essayé 3 solutions différentes. »","question":"Comment tu traites ce blocage technique en Daily ?","options":["Tu identifies qui peut aider Léa (dev expert ou archi), tu organises un mob-debugging de 30 min après le Daily et tu mets le blocage dans le Scrum Board.","Tu demandes à Léa de continuer à chercher seule jusqu''à midi.","Tu escalades immédiatement le bug au COMEX."],"correctIndex":0,"correction":"Les blocages doivent être résolus rapidement. Le Scrum Master (ou PM) facilite la résolution en identifiant la bonne ressource et en time-boxant la résolution."},{"npcLine":"Le management assiste au Daily et commence à poser des questions détaillées sur l''avancement.","question":"Comment tu gères la présence intrusive du management en Daily ?","options":["Tu expliques poliment que le Daily est un événement pour l''équipe de développement — le management peut observer silencieusement mais pas intervenir.","Tu cèdes et tu laisses le management dominer le Daily.","Tu demandes au management de quitter la réunion."],"correctIndex":0,"correction":"Le Daily Scrum est réservé aux développeurs. Le management peut être « poulet » (observateur) mais pas « cochon » (participant décisionnel). C''est une règle Scrum fondamentale."},{"npcLine":"Fin du Daily. Le Sprint Burndown montre un retard de 30 % sur les 3 premiers jours.","question":"Comment tu interprètes et réagis à ce retard sur le Burndown ?","options":["Tu organises un point d''équipe rapide pour identifier la cause (mauvaise estimation, complexité imprévue, blocage) et tu ajustes le plan de Sprint si nécessaire.","Tu paniques et tu envoies un email d''alarme au COMEX.","Tu ignores — 3 jours c''est trop tôt pour s''inquiéter."],"correctIndex":0,"correction":"Un retard de 30 % en J3 est un signal d''alerte à inspecter sans dramatiser. L''adaptation rapide (Scrum Pilier Adaptation) évite que la situation empire jusqu''à la Sprint Review."}],"closing":"Daily terminé en 14 minutes. L''équipe est synchronisée. Les blocages ont un owner."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-daily-2', 0, 'Hugo : « Hier j''ai travaillé sur la migration, aujourd''hui je continue. Rien de bloquant. » — mais son visage dit le contraire.', 'Hugo : « Hier j''ai travaillé sur la migration, aujourd''hui je continue. Rien de bloquant. » — mais son visage dit le contraire.', 'Comment tu gères un signal de blocage non verbal en Daily ?', 'Comment tu gères un signal de blocage non verbal en Daily ?', 'Tu notes le signal, tu laisses le Daily se terminer en 15 min et tu invites Hugo à un point rapide en bilatéral juste après.', 'Tu notes le signal, tu laisses le Daily se terminer en 15 min et tu invites Hugo à un point rapide en bilatéral juste après.', 'Tu interroges Hugo longuement pendant le Daily devant toute l''équipe.', 'Tu interroges Hugo longuement pendant le Daily devant toute l''équipe.', 'Tu ignores — si Hugo ne dit rien c''est que tout va bien.', 'Tu ignores — si Hugo ne dit rien c''est que tout va bien.', 0, 'Le Daily n''est pas un lieu de résolution de problèmes — c''est un lieu de synchronisation. Les blocages se traitent en bilatéral ou en sous-groupe après le Daily (« After-party »).', 'Le Daily n''est pas un lieu de résolution de problèmes — c''est un lieu de synchronisation. Les blocages se traitent en bilatéral ou en sous-groupe après le Daily (« After-party »).', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-daily-2', 1, 'Rania : « Le Daily prend 30 minutes chaque matin — les gens parlent de tout et de rien. »', 'Rania : « Le Daily prend 30 minutes chaque matin — les gens parlent de tout et de rien. »', 'Comment tu recadres un Daily qui dépasse son time-box ?', 'Comment tu recadres un Daily qui dépasse son time-box ?', 'Tu rappelles les 3 questions Scrum (hier / aujourd''hui / blocage), tu time-boxes chaque personne à 2 min et tu renvois les discussions hors sujet après le Daily.', 'Tu rappelles les 3 questions Scrum (hier / aujourd''hui / blocage), tu time-boxes chaque personne à 2 min et tu renvois les discussions hors sujet après le Daily.', 'Tu annules le Daily — il ne sert à rien.', 'Tu annules le Daily — il ne sert à rien.', 'Tu laisses faire — la liberté d''expression est importante.', 'Tu laisses faire — la liberté d''expression est importante.', 0, 'Le Daily de 15 min est un time-box strict. Les 3 questions focalisent sur la synchronisation vers le Sprint Goal — pas sur les statuts détaillés. Le Scrum Master est garant du format.', 'Le Daily de 15 min est un time-box strict. Les 3 questions focalisent sur la synchronisation vers le Sprint Goal — pas sur les statuts détaillés. Le Scrum Master est garant du format.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-daily-2', 2, 'Léa : « Je suis bloquée depuis hier soir sur un bug de build. J''ai essayé 3 solutions différentes. »', 'Léa : « Je suis bloquée depuis hier soir sur un bug de build. J''ai essayé 3 solutions différentes. »', 'Comment tu traites ce blocage technique en Daily ?', 'Comment tu traites ce blocage technique en Daily ?', 'Tu identifies qui peut aider Léa (dev expert ou archi), tu organises un mob-debugging de 30 min après le Daily et tu mets le blocage dans le Scrum Board.', 'Tu identifies qui peut aider Léa (dev expert ou archi), tu organises un mob-debugging de 30 min après le Daily et tu mets le blocage dans le Scrum Board.', 'Tu demandes à Léa de continuer à chercher seule jusqu''à midi.', 'Tu demandes à Léa de continuer à chercher seule jusqu''à midi.', 'Tu escalades immédiatement le bug au COMEX.', 'Tu escalades immédiatement le bug au COMEX.', 0, 'Les blocages doivent être résolus rapidement. Le Scrum Master (ou PM) facilite la résolution en identifiant la bonne ressource et en time-boxant la résolution.', 'Les blocages doivent être résolus rapidement. Le Scrum Master (ou PM) facilite la résolution en identifiant la bonne ressource et en time-boxant la résolution.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-daily-2', 3, 'Le management assiste au Daily et commence à poser des questions détaillées sur l''avancement.', 'Le management assiste au Daily et commence à poser des questions détaillées sur l''avancement.', 'Comment tu gères la présence intrusive du management en Daily ?', 'Comment tu gères la présence intrusive du management en Daily ?', 'Tu expliques poliment que le Daily est un événement pour l''équipe de développement — le management peut observer silencieusement mais pas intervenir.', 'Tu expliques poliment que le Daily est un événement pour l''équipe de développement — le management peut observer silencieusement mais pas intervenir.', 'Tu cèdes et tu laisses le management dominer le Daily.', 'Tu cèdes et tu laisses le management dominer le Daily.', 'Tu demandes au management de quitter la réunion.', 'Tu demandes au management de quitter la réunion.', 0, 'Le Daily Scrum est réservé aux développeurs. Le management peut être « poulet » (observateur) mais pas « cochon » (participant décisionnel). C''est une règle Scrum fondamentale.', 'Le Daily Scrum est réservé aux développeurs. Le management peut être « poulet » (observateur) mais pas « cochon » (participant décisionnel). C''est une règle Scrum fondamentale.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-daily-2', 4, 'Fin du Daily. Le Sprint Burndown montre un retard de 30 % sur les 3 premiers jours.', 'Fin du Daily. Le Sprint Burndown montre un retard de 30 % sur les 3 premiers jours.', 'Comment tu interprètes et réagis à ce retard sur le Burndown ?', 'Comment tu interprètes et réagis à ce retard sur le Burndown ?', 'Tu organises un point d''équipe rapide pour identifier la cause (mauvaise estimation, complexité imprévue, blocage) et tu ajustes le plan de Sprint si nécessaire.', 'Tu organises un point d''équipe rapide pour identifier la cause (mauvaise estimation, complexité imprévue, blocage) et tu ajustes le plan de Sprint si nécessaire.', 'Tu paniques et tu envoies un email d''alarme au COMEX.', 'Tu paniques et tu envoies un email d''alarme au COMEX.', 'Tu ignores — 3 jours c''est trop tôt pour s''inquiéter.', 'Tu ignores — 3 jours c''est trop tôt pour s''inquiéter.', 0, 'Un retard de 30 % en J3 est un signal d''alerte à inspecter sans dramatiser. L''adaptation rapide (Scrum Pilier Adaptation) évite que la situation empire jusqu''à la Sprint Review.', 'Un retard de 30 % en J3 est un signal d''alerte à inspecter sans dramatiser. L''adaptation rapide (Scrum Pilier Adaptation) évite que la situation empire jusqu''à la Sprint Review.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('scrum-sprint-review-3', 'sprint-review', 'Sprint Review — Sprint 4', 'Sprint Review — Sprint 4', 'La Sprint Review réunit l''équipe et les parties prenantes clés. On démontre ce qui a été livré ce Sprint. Le PO valide ou rejette chaque incrément.', 'La Sprint Review réunit l''équipe et les parties prenantes clés. On démontre ce qui a été livré ce Sprint. Le PO valide ou rejette chaque incrément.', 'Sprint Review terminée. L''incrément est présenté. Le backlog est mis à jour.', 'Sprint Review terminée. L''incrément est présenté. Le backlog est mis à jour.', '{"kind":"sprint-review","title":"Sprint Review — Sprint 4","opening":"La Sprint Review réunit l''équipe et les parties prenantes clés. On démontre ce qui a été livré ce Sprint. Le PO valide ou rejette chaque incrément.","questions":[{"npcLine":"Le PO : « Cette User Story est techniquement prête mais elle ne correspond pas à ce que j''avais en tête. »","question":"Comment tu gères un rejet d''US en Sprint Review ?","options":["Tu acceptes le rejet, tu notes les clarifications du PO, tu renvois l''US dans le Product Backlog avec les nouvelles critères d''acceptation et tu planifies le reraffinement.","Tu défends l''US coûte que coûte — l''équipe a travaillé dur.","Tu livres quand même sans validation du PO."],"correctIndex":0,"correction":"Le PO a le dernier mot sur l''acceptation des US. Un rejet en Sprint Review est une information précieuse — pas un échec. C''est le feedback loop qui rend l''Agile efficace."},{"npcLine":"Une partie prenante propose de nombreuses nouvelles fonctionnalités pendant la démo.","question":"Comment tu captures ces nouvelles idées sans perturber le Sprint Review ?","options":["Tu notes toutes les idées dans un backlog d''idées dédié, tu remercies pour les retours et tu planifies un backlog refinement pour les analyser avec le PO.","Tu acceptes toutes les idées en direct et tu promets de les livrer au prochain Sprint.","Tu ignores les idées pour ne pas perturber le Sprint Review."],"correctIndex":0,"correction":"La Sprint Review génère du feedback précieux. Toutes les idées méritent d''être capturées — mais leur priorisation appartient au PO lors du refinement, pas pendant la réunion."},{"npcLine":"L''équipe a livré 32 points sur 38 prévus. Le PO demande une explication.","question":"Comment tu présentes un Sprint incomplet lors de la Sprint Review ?","options":["Tu présentes honnêtement ce qui est \"Done\" selon la DoD, tu expliques pourquoi les 6 points n''ont pas été livrés et tu proposes comment les traiter au prochain Sprint.","Tu présente le travail en cours comme \"livré\" pour atteindre les 38 points.","Tu blâmes un membre de l''équipe pour justifier le retard."],"correctIndex":0,"correction":"La transparence en Sprint Review est fondamentale. Présenter du work-in-progress comme \"Done\" est une fraude agile qui mine la confiance et fausse les métriques."},{"npcLine":"Le product backlog n''a pas été mis à jour depuis 2 Sprints. Le PO est débordé.","question":"Comment tu aides à maintenir un Product Backlog sain ?","options":["Tu planifies des sessions de Backlog Refinement régulières (min. 10 % de la capacité Sprint) et tu aide le PO à structurer ses sessions.","Tu prends en charge le Product Backlog à la place du PO.","Tu attends que le PO le fasse de son côté sans t''impliquer."],"correctIndex":0,"correction":"Le Backlog Refinement est un événement continu en Scrum. Le Scrum Master aide le PO à le tenir à jour — sans lui substituer l''ownership du produit."},{"npcLine":"À la fin de la Sprint Review, les parties prenantes semblent satisfaites mais peu engagées.","question":"Comment tu renforces l''engagement des parties prenantes dans le processus Agile ?","options":["Tu les invites à tester eux-mêmes l''incrément, tu crées des moments d''interaction directe avec le produit et tu leur expliques comment leur feedback influence le prochain Sprint.","Tu leur envoies un rapport de Sprint Review par email à la place.","Tu réduis la fréquence des Sprint Reviews pour ne pas les mobiliser trop souvent."],"correctIndex":0,"correction":"L''engagement des stakeholders est un facteur de succès Agile critique. Les faire toucher le produit et voir l''impact direct de leur feedback renforce leur implication."}],"closing":"Sprint Review terminée. L''incrément est présenté. Le backlog est mis à jour."}'::jsonb, '{"kind":"sprint-review","title":"Sprint Review — Sprint 4","opening":"La Sprint Review réunit l''équipe et les parties prenantes clés. On démontre ce qui a été livré ce Sprint. Le PO valide ou rejette chaque incrément.","questions":[{"npcLine":"Le PO : « Cette User Story est techniquement prête mais elle ne correspond pas à ce que j''avais en tête. »","question":"Comment tu gères un rejet d''US en Sprint Review ?","options":["Tu acceptes le rejet, tu notes les clarifications du PO, tu renvois l''US dans le Product Backlog avec les nouvelles critères d''acceptation et tu planifies le reraffinement.","Tu défends l''US coûte que coûte — l''équipe a travaillé dur.","Tu livres quand même sans validation du PO."],"correctIndex":0,"correction":"Le PO a le dernier mot sur l''acceptation des US. Un rejet en Sprint Review est une information précieuse — pas un échec. C''est le feedback loop qui rend l''Agile efficace."},{"npcLine":"Une partie prenante propose de nombreuses nouvelles fonctionnalités pendant la démo.","question":"Comment tu captures ces nouvelles idées sans perturber le Sprint Review ?","options":["Tu notes toutes les idées dans un backlog d''idées dédié, tu remercies pour les retours et tu planifies un backlog refinement pour les analyser avec le PO.","Tu acceptes toutes les idées en direct et tu promets de les livrer au prochain Sprint.","Tu ignores les idées pour ne pas perturber le Sprint Review."],"correctIndex":0,"correction":"La Sprint Review génère du feedback précieux. Toutes les idées méritent d''être capturées — mais leur priorisation appartient au PO lors du refinement, pas pendant la réunion."},{"npcLine":"L''équipe a livré 32 points sur 38 prévus. Le PO demande une explication.","question":"Comment tu présentes un Sprint incomplet lors de la Sprint Review ?","options":["Tu présentes honnêtement ce qui est \"Done\" selon la DoD, tu expliques pourquoi les 6 points n''ont pas été livrés et tu proposes comment les traiter au prochain Sprint.","Tu présente le travail en cours comme \"livré\" pour atteindre les 38 points.","Tu blâmes un membre de l''équipe pour justifier le retard."],"correctIndex":0,"correction":"La transparence en Sprint Review est fondamentale. Présenter du work-in-progress comme \"Done\" est une fraude agile qui mine la confiance et fausse les métriques."},{"npcLine":"Le product backlog n''a pas été mis à jour depuis 2 Sprints. Le PO est débordé.","question":"Comment tu aides à maintenir un Product Backlog sain ?","options":["Tu planifies des sessions de Backlog Refinement régulières (min. 10 % de la capacité Sprint) et tu aide le PO à structurer ses sessions.","Tu prends en charge le Product Backlog à la place du PO.","Tu attends que le PO le fasse de son côté sans t''impliquer."],"correctIndex":0,"correction":"Le Backlog Refinement est un événement continu en Scrum. Le Scrum Master aide le PO à le tenir à jour — sans lui substituer l''ownership du produit."},{"npcLine":"À la fin de la Sprint Review, les parties prenantes semblent satisfaites mais peu engagées.","question":"Comment tu renforces l''engagement des parties prenantes dans le processus Agile ?","options":["Tu les invites à tester eux-mêmes l''incrément, tu crées des moments d''interaction directe avec le produit et tu leur expliques comment leur feedback influence le prochain Sprint.","Tu leur envoies un rapport de Sprint Review par email à la place.","Tu réduis la fréquence des Sprint Reviews pour ne pas les mobiliser trop souvent."],"correctIndex":0,"correction":"L''engagement des stakeholders est un facteur de succès Agile critique. Les faire toucher le produit et voir l''impact direct de leur feedback renforce leur implication."}],"closing":"Sprint Review terminée. L''incrément est présenté. Le backlog est mis à jour."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-review-3', 0, 'Le PO : « Cette User Story est techniquement prête mais elle ne correspond pas à ce que j''avais en tête. »', 'Le PO : « Cette User Story est techniquement prête mais elle ne correspond pas à ce que j''avais en tête. »', 'Comment tu gères un rejet d''US en Sprint Review ?', 'Comment tu gères un rejet d''US en Sprint Review ?', 'Tu acceptes le rejet, tu notes les clarifications du PO, tu renvois l''US dans le Product Backlog avec les nouvelles critères d''acceptation et tu planifies le reraffinement.', 'Tu acceptes le rejet, tu notes les clarifications du PO, tu renvois l''US dans le Product Backlog avec les nouvelles critères d''acceptation et tu planifies le reraffinement.', 'Tu défends l''US coûte que coûte — l''équipe a travaillé dur.', 'Tu défends l''US coûte que coûte — l''équipe a travaillé dur.', 'Tu livres quand même sans validation du PO.', 'Tu livres quand même sans validation du PO.', 0, 'Le PO a le dernier mot sur l''acceptation des US. Un rejet en Sprint Review est une information précieuse — pas un échec. C''est le feedback loop qui rend l''Agile efficace.', 'Le PO a le dernier mot sur l''acceptation des US. Un rejet en Sprint Review est une information précieuse — pas un échec. C''est le feedback loop qui rend l''Agile efficace.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-review-3', 1, 'Une partie prenante propose de nombreuses nouvelles fonctionnalités pendant la démo.', 'Une partie prenante propose de nombreuses nouvelles fonctionnalités pendant la démo.', 'Comment tu captures ces nouvelles idées sans perturber le Sprint Review ?', 'Comment tu captures ces nouvelles idées sans perturber le Sprint Review ?', 'Tu notes toutes les idées dans un backlog d''idées dédié, tu remercies pour les retours et tu planifies un backlog refinement pour les analyser avec le PO.', 'Tu notes toutes les idées dans un backlog d''idées dédié, tu remercies pour les retours et tu planifies un backlog refinement pour les analyser avec le PO.', 'Tu acceptes toutes les idées en direct et tu promets de les livrer au prochain Sprint.', 'Tu acceptes toutes les idées en direct et tu promets de les livrer au prochain Sprint.', 'Tu ignores les idées pour ne pas perturber le Sprint Review.', 'Tu ignores les idées pour ne pas perturber le Sprint Review.', 0, 'La Sprint Review génère du feedback précieux. Toutes les idées méritent d''être capturées — mais leur priorisation appartient au PO lors du refinement, pas pendant la réunion.', 'La Sprint Review génère du feedback précieux. Toutes les idées méritent d''être capturées — mais leur priorisation appartient au PO lors du refinement, pas pendant la réunion.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-review-3', 2, 'L''équipe a livré 32 points sur 38 prévus. Le PO demande une explication.', 'L''équipe a livré 32 points sur 38 prévus. Le PO demande une explication.', 'Comment tu présentes un Sprint incomplet lors de la Sprint Review ?', 'Comment tu présentes un Sprint incomplet lors de la Sprint Review ?', 'Tu présentes honnêtement ce qui est "Done" selon la DoD, tu expliques pourquoi les 6 points n''ont pas été livrés et tu proposes comment les traiter au prochain Sprint.', 'Tu présentes honnêtement ce qui est "Done" selon la DoD, tu expliques pourquoi les 6 points n''ont pas été livrés et tu proposes comment les traiter au prochain Sprint.', 'Tu présente le travail en cours comme "livré" pour atteindre les 38 points.', 'Tu présente le travail en cours comme "livré" pour atteindre les 38 points.', 'Tu blâmes un membre de l''équipe pour justifier le retard.', 'Tu blâmes un membre de l''équipe pour justifier le retard.', 0, 'La transparence en Sprint Review est fondamentale. Présenter du work-in-progress comme "Done" est une fraude agile qui mine la confiance et fausse les métriques.', 'La transparence en Sprint Review est fondamentale. Présenter du work-in-progress comme "Done" est une fraude agile qui mine la confiance et fausse les métriques.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-review-3', 3, 'Le product backlog n''a pas été mis à jour depuis 2 Sprints. Le PO est débordé.', 'Le product backlog n''a pas été mis à jour depuis 2 Sprints. Le PO est débordé.', 'Comment tu aides à maintenir un Product Backlog sain ?', 'Comment tu aides à maintenir un Product Backlog sain ?', 'Tu planifies des sessions de Backlog Refinement régulières (min. 10 % de la capacité Sprint) et tu aide le PO à structurer ses sessions.', 'Tu planifies des sessions de Backlog Refinement régulières (min. 10 % de la capacité Sprint) et tu aide le PO à structurer ses sessions.', 'Tu prends en charge le Product Backlog à la place du PO.', 'Tu prends en charge le Product Backlog à la place du PO.', 'Tu attends que le PO le fasse de son côté sans t''impliquer.', 'Tu attends que le PO le fasse de son côté sans t''impliquer.', 0, 'Le Backlog Refinement est un événement continu en Scrum. Le Scrum Master aide le PO à le tenir à jour — sans lui substituer l''ownership du produit.', 'Le Backlog Refinement est un événement continu en Scrum. Le Scrum Master aide le PO à le tenir à jour — sans lui substituer l''ownership du produit.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-review-3', 4, 'À la fin de la Sprint Review, les parties prenantes semblent satisfaites mais peu engagées.', 'À la fin de la Sprint Review, les parties prenantes semblent satisfaites mais peu engagées.', 'Comment tu renforces l''engagement des parties prenantes dans le processus Agile ?', 'Comment tu renforces l''engagement des parties prenantes dans le processus Agile ?', 'Tu les invites à tester eux-mêmes l''incrément, tu crées des moments d''interaction directe avec le produit et tu leur expliques comment leur feedback influence le prochain Sprint.', 'Tu les invites à tester eux-mêmes l''incrément, tu crées des moments d''interaction directe avec le produit et tu leur expliques comment leur feedback influence le prochain Sprint.', 'Tu leur envoies un rapport de Sprint Review par email à la place.', 'Tu leur envoies un rapport de Sprint Review par email à la place.', 'Tu réduis la fréquence des Sprint Reviews pour ne pas les mobiliser trop souvent.', 'Tu réduis la fréquence des Sprint Reviews pour ne pas les mobiliser trop souvent.', 0, 'L''engagement des stakeholders est un facteur de succès Agile critique. Les faire toucher le produit et voir l''impact direct de leur feedback renforce leur implication.', 'L''engagement des stakeholders est un facteur de succès Agile critique. Les faire toucher le produit et voir l''impact direct de leur feedback renforce leur implication.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('scrum-sprint-retro-4', 'sprint-retro', 'Sprint Retrospective — Sprint 4', 'Sprint Retrospective — Sprint 4', 'La Rétrospective réunit uniquement l''équipe Scrum. Espace safe pour parler franchement de ce qui a bien marché et de ce qui doit changer.', 'La Rétrospective réunit uniquement l''équipe Scrum. Espace safe pour parler franchement de ce qui a bien marché et de ce qui doit changer.', 'Rétrospective terminée. 3 actions concrètes. L''équipe repart avec de l''énergie.', 'Rétrospective terminée. 3 actions concrètes. L''équipe repart avec de l''énergie.', '{"kind":"sprint-retro","title":"Sprint Retrospective — Sprint 4","opening":"La Rétrospective réunit uniquement l''équipe Scrum. Espace safe pour parler franchement de ce qui a bien marché et de ce qui doit changer.","questions":[{"npcLine":"Hugo : « Je veux qu''on parle des estimations — on s''est toujours trompé cette année. »","question":"Comment tu facilites une discussion sur les estimations en rétro ?","options":["Tu analyses les données historiques (écart estimation/réalité), tu identifies les patterns (mauvais splitting, complexité cachée) et tu proposes une expérimentation pour le prochain Sprint.","Tu défends les estimations passées — l''équipe a fait de son mieux.","Tu proposes d''arrêter d''estimer pour éviter le problème."],"correctIndex":0,"correction":"L''amélioration des estimations passe par l''analyse de données, pas par la suppression des estimations. La Rétrospective est le lieu idéal pour identifier les patterns d''écart et expérimenter."},{"npcLine":"L''ambiance de la rétrospective est tendue — deux personnes ont un conflit ouvert.","question":"Comment tu gères un conflit interpersonnel en Rétrospective ?","options":["Tu recentres la discussion sur les systèmes et les processus (pas les personnes), tu rappelles la règle de la prime directive et tu proposes un bilatéral de médiation hors rétrospective si nécessaire.","Tu prends parti pour l''une des deux personnes.","Tu annules la rétrospective pour éviter le conflit."],"correctIndex":0,"correction":"La Prime Directive des Rétrospectives : \"Everyone did the best job they could given what they knew.\" Le focus est sur les améliorations système, pas sur les blâmes personnels."},{"npcLine":"Léa : « On identifie les mêmes problèmes chaque Sprint mais rien ne change jamais. »","question":"Comment tu rends les rétrospectives vraiment actionnables ?","options":["Tu limites les actions à maximum 2-3 items par Sprint, tu désignes un owner pour chacune, tu les intègres dans le Sprint Backlog et tu vérifie à la prochaine rétro.","Tu continues à lister tous les problèmes et tu espères que ça changera.","Tu arrêtes les rétrospectives — elles ne servent à rien."],"correctIndex":0,"correction":"Une Rétrospective efficace produit 2-3 actions maximum avec owner et deadline. Trop d''actions = aucune action. L''intégration dans le Sprint Backlog garantit l''exécution."},{"npcLine":"Rania : « L''environnement de dev est instable depuis 2 Sprints — ça nous ralentit énormément. »","question":"Comment tu traites un problème d''environnement récurrent en Rétrospective ?","options":["Tu escalades ce blocage infrastructure comme un impediment formel au management (hors portée de l''équipe), avec impact chiffré sur la vélocité et demande de résolution sous 1 semaine.","Tu demandes à l''équipe de s''adapter à l''environnement instable.","Tu notes le problème dans la rétro mais tu n''escalades pas."],"correctIndex":0,"correction":"Les impediments hors portée de l''équipe doivent être escaladés par le Scrum Master. Un environnement instable est un impediment systémique qui impacte directement la vélocité."},{"npcLine":"À la fin de la Rétrospective, l''équipe semble plus soudée qu''en début de séance.","question":"Comment tu capitalises sur cette dynamique positive en fin de rétro ?","options":["Tu célèbres explicitement ce qui a bien marché ce Sprint, tu formules les actions comme des expériences positives et tu termines sur une note d''espoir et d''équipe.","Tu enchaînes immédiatement sur d''autres réunions sans marquer la fin.","Tu ne dis rien — les émotions n''ont pas leur place en Scrum."],"correctIndex":0,"correction":"Terminer la Rétrospective sur une note positive et des célébrations concrètes renforce la cohésion d''équipe. Le Scrum Master est aussi un animateur — pas seulement un facilitateur de processus."}],"closing":"Rétrospective terminée. 3 actions concrètes. L''équipe repart avec de l''énergie."}'::jsonb, '{"kind":"sprint-retro","title":"Sprint Retrospective — Sprint 4","opening":"La Rétrospective réunit uniquement l''équipe Scrum. Espace safe pour parler franchement de ce qui a bien marché et de ce qui doit changer.","questions":[{"npcLine":"Hugo : « Je veux qu''on parle des estimations — on s''est toujours trompé cette année. »","question":"Comment tu facilites une discussion sur les estimations en rétro ?","options":["Tu analyses les données historiques (écart estimation/réalité), tu identifies les patterns (mauvais splitting, complexité cachée) et tu proposes une expérimentation pour le prochain Sprint.","Tu défends les estimations passées — l''équipe a fait de son mieux.","Tu proposes d''arrêter d''estimer pour éviter le problème."],"correctIndex":0,"correction":"L''amélioration des estimations passe par l''analyse de données, pas par la suppression des estimations. La Rétrospective est le lieu idéal pour identifier les patterns d''écart et expérimenter."},{"npcLine":"L''ambiance de la rétrospective est tendue — deux personnes ont un conflit ouvert.","question":"Comment tu gères un conflit interpersonnel en Rétrospective ?","options":["Tu recentres la discussion sur les systèmes et les processus (pas les personnes), tu rappelles la règle de la prime directive et tu proposes un bilatéral de médiation hors rétrospective si nécessaire.","Tu prends parti pour l''une des deux personnes.","Tu annules la rétrospective pour éviter le conflit."],"correctIndex":0,"correction":"La Prime Directive des Rétrospectives : \"Everyone did the best job they could given what they knew.\" Le focus est sur les améliorations système, pas sur les blâmes personnels."},{"npcLine":"Léa : « On identifie les mêmes problèmes chaque Sprint mais rien ne change jamais. »","question":"Comment tu rends les rétrospectives vraiment actionnables ?","options":["Tu limites les actions à maximum 2-3 items par Sprint, tu désignes un owner pour chacune, tu les intègres dans le Sprint Backlog et tu vérifie à la prochaine rétro.","Tu continues à lister tous les problèmes et tu espères que ça changera.","Tu arrêtes les rétrospectives — elles ne servent à rien."],"correctIndex":0,"correction":"Une Rétrospective efficace produit 2-3 actions maximum avec owner et deadline. Trop d''actions = aucune action. L''intégration dans le Sprint Backlog garantit l''exécution."},{"npcLine":"Rania : « L''environnement de dev est instable depuis 2 Sprints — ça nous ralentit énormément. »","question":"Comment tu traites un problème d''environnement récurrent en Rétrospective ?","options":["Tu escalades ce blocage infrastructure comme un impediment formel au management (hors portée de l''équipe), avec impact chiffré sur la vélocité et demande de résolution sous 1 semaine.","Tu demandes à l''équipe de s''adapter à l''environnement instable.","Tu notes le problème dans la rétro mais tu n''escalades pas."],"correctIndex":0,"correction":"Les impediments hors portée de l''équipe doivent être escaladés par le Scrum Master. Un environnement instable est un impediment systémique qui impacte directement la vélocité."},{"npcLine":"À la fin de la Rétrospective, l''équipe semble plus soudée qu''en début de séance.","question":"Comment tu capitalises sur cette dynamique positive en fin de rétro ?","options":["Tu célèbres explicitement ce qui a bien marché ce Sprint, tu formules les actions comme des expériences positives et tu termines sur une note d''espoir et d''équipe.","Tu enchaînes immédiatement sur d''autres réunions sans marquer la fin.","Tu ne dis rien — les émotions n''ont pas leur place en Scrum."],"correctIndex":0,"correction":"Terminer la Rétrospective sur une note positive et des célébrations concrètes renforce la cohésion d''équipe. Le Scrum Master est aussi un animateur — pas seulement un facilitateur de processus."}],"closing":"Rétrospective terminée. 3 actions concrètes. L''équipe repart avec de l''énergie."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-retro-4', 0, 'Hugo : « Je veux qu''on parle des estimations — on s''est toujours trompé cette année. »', 'Hugo : « Je veux qu''on parle des estimations — on s''est toujours trompé cette année. »', 'Comment tu facilites une discussion sur les estimations en rétro ?', 'Comment tu facilites une discussion sur les estimations en rétro ?', 'Tu analyses les données historiques (écart estimation/réalité), tu identifies les patterns (mauvais splitting, complexité cachée) et tu proposes une expérimentation pour le prochain Sprint.', 'Tu analyses les données historiques (écart estimation/réalité), tu identifies les patterns (mauvais splitting, complexité cachée) et tu proposes une expérimentation pour le prochain Sprint.', 'Tu défends les estimations passées — l''équipe a fait de son mieux.', 'Tu défends les estimations passées — l''équipe a fait de son mieux.', 'Tu proposes d''arrêter d''estimer pour éviter le problème.', 'Tu proposes d''arrêter d''estimer pour éviter le problème.', 0, 'L''amélioration des estimations passe par l''analyse de données, pas par la suppression des estimations. La Rétrospective est le lieu idéal pour identifier les patterns d''écart et expérimenter.', 'L''amélioration des estimations passe par l''analyse de données, pas par la suppression des estimations. La Rétrospective est le lieu idéal pour identifier les patterns d''écart et expérimenter.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-retro-4', 1, 'L''ambiance de la rétrospective est tendue — deux personnes ont un conflit ouvert.', 'L''ambiance de la rétrospective est tendue — deux personnes ont un conflit ouvert.', 'Comment tu gères un conflit interpersonnel en Rétrospective ?', 'Comment tu gères un conflit interpersonnel en Rétrospective ?', 'Tu recentres la discussion sur les systèmes et les processus (pas les personnes), tu rappelles la règle de la prime directive et tu proposes un bilatéral de médiation hors rétrospective si nécessaire.', 'Tu recentres la discussion sur les systèmes et les processus (pas les personnes), tu rappelles la règle de la prime directive et tu proposes un bilatéral de médiation hors rétrospective si nécessaire.', 'Tu prends parti pour l''une des deux personnes.', 'Tu prends parti pour l''une des deux personnes.', 'Tu annules la rétrospective pour éviter le conflit.', 'Tu annules la rétrospective pour éviter le conflit.', 0, 'La Prime Directive des Rétrospectives : "Everyone did the best job they could given what they knew." Le focus est sur les améliorations système, pas sur les blâmes personnels.', 'La Prime Directive des Rétrospectives : "Everyone did the best job they could given what they knew." Le focus est sur les améliorations système, pas sur les blâmes personnels.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-retro-4', 2, 'Léa : « On identifie les mêmes problèmes chaque Sprint mais rien ne change jamais. »', 'Léa : « On identifie les mêmes problèmes chaque Sprint mais rien ne change jamais. »', 'Comment tu rends les rétrospectives vraiment actionnables ?', 'Comment tu rends les rétrospectives vraiment actionnables ?', 'Tu limites les actions à maximum 2-3 items par Sprint, tu désignes un owner pour chacune, tu les intègres dans le Sprint Backlog et tu vérifie à la prochaine rétro.', 'Tu limites les actions à maximum 2-3 items par Sprint, tu désignes un owner pour chacune, tu les intègres dans le Sprint Backlog et tu vérifie à la prochaine rétro.', 'Tu continues à lister tous les problèmes et tu espères que ça changera.', 'Tu continues à lister tous les problèmes et tu espères que ça changera.', 'Tu arrêtes les rétrospectives — elles ne servent à rien.', 'Tu arrêtes les rétrospectives — elles ne servent à rien.', 0, 'Une Rétrospective efficace produit 2-3 actions maximum avec owner et deadline. Trop d''actions = aucune action. L''intégration dans le Sprint Backlog garantit l''exécution.', 'Une Rétrospective efficace produit 2-3 actions maximum avec owner et deadline. Trop d''actions = aucune action. L''intégration dans le Sprint Backlog garantit l''exécution.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-retro-4', 3, 'Rania : « L''environnement de dev est instable depuis 2 Sprints — ça nous ralentit énormément. »', 'Rania : « L''environnement de dev est instable depuis 2 Sprints — ça nous ralentit énormément. »', 'Comment tu traites un problème d''environnement récurrent en Rétrospective ?', 'Comment tu traites un problème d''environnement récurrent en Rétrospective ?', 'Tu escalades ce blocage infrastructure comme un impediment formel au management (hors portée de l''équipe), avec impact chiffré sur la vélocité et demande de résolution sous 1 semaine.', 'Tu escalades ce blocage infrastructure comme un impediment formel au management (hors portée de l''équipe), avec impact chiffré sur la vélocité et demande de résolution sous 1 semaine.', 'Tu demandes à l''équipe de s''adapter à l''environnement instable.', 'Tu demandes à l''équipe de s''adapter à l''environnement instable.', 'Tu notes le problème dans la rétro mais tu n''escalades pas.', 'Tu notes le problème dans la rétro mais tu n''escalades pas.', 0, 'Les impediments hors portée de l''équipe doivent être escaladés par le Scrum Master. Un environnement instable est un impediment systémique qui impacte directement la vélocité.', 'Les impediments hors portée de l''équipe doivent être escaladés par le Scrum Master. Un environnement instable est un impediment systémique qui impacte directement la vélocité.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('scrum-sprint-retro-4', 4, 'À la fin de la Rétrospective, l''équipe semble plus soudée qu''en début de séance.', 'À la fin de la Rétrospective, l''équipe semble plus soudée qu''en début de séance.', 'Comment tu capitalises sur cette dynamique positive en fin de rétro ?', 'Comment tu capitalises sur cette dynamique positive en fin de rétro ?', 'Tu célèbres explicitement ce qui a bien marché ce Sprint, tu formules les actions comme des expériences positives et tu termines sur une note d''espoir et d''équipe.', 'Tu célèbres explicitement ce qui a bien marché ce Sprint, tu formules les actions comme des expériences positives et tu termines sur une note d''espoir et d''équipe.', 'Tu enchaînes immédiatement sur d''autres réunions sans marquer la fin.', 'Tu enchaînes immédiatement sur d''autres réunions sans marquer la fin.', 'Tu ne dis rien — les émotions n''ont pas leur place en Scrum.', 'Tu ne dis rien — les émotions n''ont pas leur place en Scrum.', 0, 'Terminer la Rétrospective sur une note positive et des célébrations concrètes renforce la cohésion d''équipe. Le Scrum Master est aussi un animateur — pas seulement un facilitateur de processus.', 'Terminer la Rétrospective sur une note positive et des célébrations concrètes renforce la cohésion d''équipe. Le Scrum Master est aussi un animateur — pas seulement un facilitateur de processus.', 0) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('comex-comex-danger', 'comex-danger', 'Signal COMEX — Convocation informelle', 'Signal COMEX — Convocation informelle', 'La DRH t''a convoqué pour un entretien informel. À côté d''elle, le CTO et ton N+1. L''atmosphère est froide. Ton taux de risque vient de passer à 50 %. Chacune de tes réponses compte.', 'La DRH t''a convoqué pour un entretien informel. À côté d''elle, le CTO et ton N+1. L''atmosphère est froide. Ton taux de risque vient de passer à 50 %. Chacune de tes réponses compte.', 'L''entretien se termine. La DRH note tes réponses. Tes réponses ont influencé la perception du COMEX.', 'L''entretien se termine. La DRH note tes réponses. Tes réponses ont influencé la perception du COMEX.', '{"kind":"comex-danger","title":"Signal COMEX — Convocation informelle","opening":"La DRH t''a convoqué pour un entretien informel. À côté d''elle, le CTO et ton N+1. L''atmosphère est froide. Ton taux de risque vient de passer à 50 %. Chacune de tes réponses compte.","questions":[{"npcLine":"DRH : « Plusieurs livrables n''ont pas été validés lors des derniers sprints. Le COMEX s''inquiète de la régularité de tes résultats. Que s''est-il passé ? »","question":"Comment tu réponds à cette question en entretien disciplinaire ?","options":["Tu reconnais les difficultés rencontrées, tu expliques les causes techniques ou contextuelles sans te dédouaner, et tu présentes un plan d''amélioration concret.","Tu minimises les problèmes : « Ce n''était pas si grave, tout le monde fait des erreurs. »","Tu accuses l''équipe ou les outils pour justifier les échecs."],"correctIndex":0,"correction":"Assumer les difficultés et proposer un plan correctif démontre la maturité professionnelle. La minimisation ou le déplacement de responsabilité aggrave la situation.","fireRiskDelta":-8},{"npcLine":"CTO : « Ta maîtrise technique est remise en question par certains membres de l''équipe. Comment tu te situes toi-même ? »","question":"Comment tu gères une remise en question de tes compétences ?","options":["Tu fais un bilan honnête de tes forces et axes d''amélioration, et tu proposes un plan de montée en compétences concret (formations, mentorat, pair programming).","Tu contestes les avis de tes collègues et tu défends ton niveau coûte que coûte.","Tu prétends n''avoir aucune lacune pour ne pas paraître faible."],"correctIndex":0,"correction":"L''autocritique constructive et un plan de développement personnel démontrent l''intelligence émotionnelle. Nier ses lacunes en entretien de performance est contre-productif.","fireRiskDelta":-7},{"npcLine":"N+1 : « Qu''est-ce que tu peux t''engager à faire différemment dès maintenant ? »","question":"Comment tu formules un engagement professionnel crédible ?","options":["Tu proposes 2-3 engagements SMART (Spécifiques, Mesurables, Atteignables, Réalistes, Temporels) avec des indicateurs de succès clairs.","Tu fais des promesses générales et vagues : « Je vais m''améliorer, je vous le promets. »","Tu demandes qu''on te fixe tes objectifs à ta place."],"correctIndex":0,"correction":"Un engagement crédible est SMART et vérifiable. Les promesses floues ne rassurent pas le management — elles signalent l''absence de plan réel.","fireRiskDelta":-9},{"npcLine":"DRH : « Dans quelle mesure tu estimes avoir contribué aux difficultés de l''équipe ? »","question":"Comment tu évalues ta part de responsabilité dans les difficultés collectives ?","options":["Tu reconnais objectivement ta part (communication insuffisante, estimations trop optimistes) sans te flageller ni reporter tout sur l''extérieur.","Tu dis que tu n''as aucune responsabilité — c''est entièrement la faute des autres.","Tu dis que c''est 100 % de ta faute pour paraître humble."],"correctIndex":0,"correction":"La responsabilité partagée et calibrée est la marque d''un professionnel mature. Ni auto-flagellation ni déni — une analyse équilibrée des causes.","fireRiskDelta":-6},{"npcLine":"CTO : « Donne-nous une raison concrète de continuer à investir sur toi. »","question":"Comment tu défends ta valeur dans un contexte sous pression ?","options":["Tu cites des contributions concrètes récentes (livrables réussis, problèmes résolus, valeur apportée) et tu projettes sur ce que tu peux apporter dans les 3 prochains mois.","Tu dis que tu travailles dur et que tu mérites une chance.","Tu pleures ou tu te mets en colère face à cette question."],"correctIndex":0,"correction":"La valeur se démontre avec des faits concrets. « Je travaille dur » n''est pas un argument — les livrables, les résolutions de problèmes et la vision prospective en sont.","fireRiskDelta":-10}],"closing":"L''entretien se termine. La DRH note tes réponses. Tes réponses ont influencé la perception du COMEX."}'::jsonb, '{"kind":"comex-danger","title":"Signal COMEX — Convocation informelle","opening":"La DRH t''a convoqué pour un entretien informel. À côté d''elle, le CTO et ton N+1. L''atmosphère est froide. Ton taux de risque vient de passer à 50 %. Chacune de tes réponses compte.","questions":[{"npcLine":"DRH : « Plusieurs livrables n''ont pas été validés lors des derniers sprints. Le COMEX s''inquiète de la régularité de tes résultats. Que s''est-il passé ? »","question":"Comment tu réponds à cette question en entretien disciplinaire ?","options":["Tu reconnais les difficultés rencontrées, tu expliques les causes techniques ou contextuelles sans te dédouaner, et tu présentes un plan d''amélioration concret.","Tu minimises les problèmes : « Ce n''était pas si grave, tout le monde fait des erreurs. »","Tu accuses l''équipe ou les outils pour justifier les échecs."],"correctIndex":0,"correction":"Assumer les difficultés et proposer un plan correctif démontre la maturité professionnelle. La minimisation ou le déplacement de responsabilité aggrave la situation.","fireRiskDelta":-8},{"npcLine":"CTO : « Ta maîtrise technique est remise en question par certains membres de l''équipe. Comment tu te situes toi-même ? »","question":"Comment tu gères une remise en question de tes compétences ?","options":["Tu fais un bilan honnête de tes forces et axes d''amélioration, et tu proposes un plan de montée en compétences concret (formations, mentorat, pair programming).","Tu contestes les avis de tes collègues et tu défends ton niveau coûte que coûte.","Tu prétends n''avoir aucune lacune pour ne pas paraître faible."],"correctIndex":0,"correction":"L''autocritique constructive et un plan de développement personnel démontrent l''intelligence émotionnelle. Nier ses lacunes en entretien de performance est contre-productif.","fireRiskDelta":-7},{"npcLine":"N+1 : « Qu''est-ce que tu peux t''engager à faire différemment dès maintenant ? »","question":"Comment tu formules un engagement professionnel crédible ?","options":["Tu proposes 2-3 engagements SMART (Spécifiques, Mesurables, Atteignables, Réalistes, Temporels) avec des indicateurs de succès clairs.","Tu fais des promesses générales et vagues : « Je vais m''améliorer, je vous le promets. »","Tu demandes qu''on te fixe tes objectifs à ta place."],"correctIndex":0,"correction":"Un engagement crédible est SMART et vérifiable. Les promesses floues ne rassurent pas le management — elles signalent l''absence de plan réel.","fireRiskDelta":-9},{"npcLine":"DRH : « Dans quelle mesure tu estimes avoir contribué aux difficultés de l''équipe ? »","question":"Comment tu évalues ta part de responsabilité dans les difficultés collectives ?","options":["Tu reconnais objectivement ta part (communication insuffisante, estimations trop optimistes) sans te flageller ni reporter tout sur l''extérieur.","Tu dis que tu n''as aucune responsabilité — c''est entièrement la faute des autres.","Tu dis que c''est 100 % de ta faute pour paraître humble."],"correctIndex":0,"correction":"La responsabilité partagée et calibrée est la marque d''un professionnel mature. Ni auto-flagellation ni déni — une analyse équilibrée des causes.","fireRiskDelta":-6},{"npcLine":"CTO : « Donne-nous une raison concrète de continuer à investir sur toi. »","question":"Comment tu défends ta valeur dans un contexte sous pression ?","options":["Tu cites des contributions concrètes récentes (livrables réussis, problèmes résolus, valeur apportée) et tu projettes sur ce que tu peux apporter dans les 3 prochains mois.","Tu dis que tu travailles dur et que tu mérites une chance.","Tu pleures ou tu te mets en colère face à cette question."],"correctIndex":0,"correction":"La valeur se démontre avec des faits concrets. « Je travaille dur » n''est pas un argument — les livrables, les résolutions de problèmes et la vision prospective en sont.","fireRiskDelta":-10}],"closing":"L''entretien se termine. La DRH note tes réponses. Tes réponses ont influencé la perception du COMEX."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
