INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('comex-comex-danger', 4, 'CTO : « Donne-nous une raison concrète de continuer à investir sur toi. »', 'CTO : « Donne-nous une raison concrète de continuer à investir sur toi. »', 'Comment tu défends ta valeur dans un contexte sous pression ?', 'Comment tu défends ta valeur dans un contexte sous pression ?', 'Tu cites des contributions concrètes récentes (livrables réussis, problèmes résolus, valeur apportée) et tu projettes sur ce que tu peux apporter dans les 3 prochains mois.', 'Tu cites des contributions concrètes récentes (livrables réussis, problèmes résolus, valeur apportée) et tu projettes sur ce que tu peux apporter dans les 3 prochains mois.', 'Tu dis que tu travailles dur et que tu mérites une chance.', 'Tu dis que tu travailles dur et que tu mérites une chance.', 'Tu pleures ou tu te mets en colère face à cette question.', 'Tu pleures ou tu te mets en colère face à cette question.', 0, 'La valeur se démontre avec des faits concrets. « Je travaille dur » n''est pas un argument — les livrables, les résolutions de problèmes et la vision prospective en sont.', 'La valeur se démontre avec des faits concrets. « Je travaille dur » n''est pas un argument — les livrables, les résolutions de problèmes et la vision prospective en sont.', -10) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('comex-comex-warning', 'comex-warning', 'COMEX — Entretien de recadrage formel', 'COMEX — Entretien de recadrage formel', 'Convocation officielle au bureau du DG. Le dossier est posé sur la table. Ton risque de licenciement est à 75 %. Chaque réponse peut faire basculer la décision.', 'Convocation officielle au bureau du DG. Le dossier est posé sur la table. Ton risque de licenciement est à 75 %. Chaque réponse peut faire basculer la décision.', 'Le COMEX délibère. Tes réponses ont pesé dans la balance. La décision sera communiquée.', 'Le COMEX délibère. Tes réponses ont pesé dans la balance. La décision sera communiquée.', '{"kind":"comex-warning","title":"COMEX — Entretien de recadrage formel","opening":"Convocation officielle au bureau du DG. Le dossier est posé sur la table. Ton risque de licenciement est à 75 %. Chaque réponse peut faire basculer la décision.","questions":[{"npcLine":"DG : « Nous vous avons convoqué suite à une série de manquements répétés. Avez-vous conscience de la gravité de la situation ? »","question":"Comment tu répondes à cette mise en garde directe ?","options":["Tu confirmes ta pleine conscience de la gravité, tu reconnais les manquements précis et tu demandes la possibilité de présenter ton plan correctif.","Tu contestes la qualification de « manquements répétés » point par point.","Tu demandes à ton avocat d''être présent avant de répondre."],"correctIndex":0,"correction":"En entretien de recadrage formel, reconnaître la gravité de la situation sans se défendre immédiatement est la posture professionnelle attendue. La contestation immédiate aggrave la perception.","fireRiskDelta":-10},{"npcLine":"DRH : « Quels moyens concrets avez-vous mis en place pour améliorer votre performance depuis notre dernier entretien ? »","question":"Comment tu démontres une amélioration concrète sous pression ?","options":["Tu présentes des preuves factuelles : livrables réussis, feedbacks positifs récents, formations suivies, indicateurs améliorés.","Tu dis que tu as essayé mais que les conditions de travail ne t''ont pas aidé.","Tu n''as rien fait et tu demandes plus de temps."],"correctIndex":0,"correction":"Les preuves factuelles sont le seul argument crédible en entretien de recadrage. Sans données concrètes, la promesse d''amélioration est perçue comme un discours de façade.","fireRiskDelta":-12},{"npcLine":"DG : « Si nous décidons de vous maintenir dans l''entreprise, quels sont vos engagements précis pour les 30 prochains jours ? »","question":"Comment tu formules un plan d''action sur 30 jours en situation de crise ?","options":["Tu proposes des objectifs hebdomadaires mesurables, des checkpoints intermédiaires et une revue de performance à J+30 avec indicateurs de succès définis ensemble.","Tu promets de « tout faire pour vous satisfaire » sans détailler.","Tu demandes 60 jours au lieu de 30 pour te donner plus de marge."],"correctIndex":0,"correction":"Un plan de 30 jours crédible est précis, mesurable et avec des checkpoints. L''ambiguïté sur les engagements pris dans un contexte disciplinaire est rédhibitoire.","fireRiskDelta":-11},{"npcLine":"DRH : « Vos collègues ont fait part de difficultés à collaborer avec vous. Comment vous l''expliquez ? »","question":"Comment tu traites un feedback négatif sur la collaboration ?","options":["Tu écoutes sans interrompre, tu reconnais que ta communication a pu être perçue différemment de ton intention, et tu proposes des actions concrètes pour améliorer la dynamique d''équipe.","Tu nies les difficultés et tu dis que tes collègues exagèrent.","Tu demandes à confronter directement les collègues qui ont fait ce retour."],"correctIndex":0,"correction":"La différence entre intention et impact est réelle. Reconnaître que ta communication a pu créer des difficultés — même involontairement — est la posture mature attendue.","fireRiskDelta":-8},{"npcLine":"DG : « Nous allons délibérer. Avez-vous quelque chose à ajouter avant que nous nous retirions ? »","question":"Quelle est ta dernière intervention avant la délibération ?","options":["Tu réaffirmes ton engagement envers le projet Mutualis, tu résumes les actions que tu t''es engagé à prendre et tu remercies le COMEX pour l''opportunité de t''exprimer.","Tu plaides de façon émotionnelle en te justifiant longuement.","Tu gardes le silence total pour montrer ta dignité."],"correctIndex":0,"correction":"La dernière intervention est une opportunité de synthèse. Réaffirmer son engagement et ses actions concrètes laisse une impression de professionnel organisé et déterminé.","fireRiskDelta":-9}],"closing":"Le COMEX délibère. Tes réponses ont pesé dans la balance. La décision sera communiquée."}'::jsonb, '{"kind":"comex-warning","title":"COMEX — Entretien de recadrage formel","opening":"Convocation officielle au bureau du DG. Le dossier est posé sur la table. Ton risque de licenciement est à 75 %. Chaque réponse peut faire basculer la décision.","questions":[{"npcLine":"DG : « Nous vous avons convoqué suite à une série de manquements répétés. Avez-vous conscience de la gravité de la situation ? »","question":"Comment tu répondes à cette mise en garde directe ?","options":["Tu confirmes ta pleine conscience de la gravité, tu reconnais les manquements précis et tu demandes la possibilité de présenter ton plan correctif.","Tu contestes la qualification de « manquements répétés » point par point.","Tu demandes à ton avocat d''être présent avant de répondre."],"correctIndex":0,"correction":"En entretien de recadrage formel, reconnaître la gravité de la situation sans se défendre immédiatement est la posture professionnelle attendue. La contestation immédiate aggrave la perception.","fireRiskDelta":-10},{"npcLine":"DRH : « Quels moyens concrets avez-vous mis en place pour améliorer votre performance depuis notre dernier entretien ? »","question":"Comment tu démontres une amélioration concrète sous pression ?","options":["Tu présentes des preuves factuelles : livrables réussis, feedbacks positifs récents, formations suivies, indicateurs améliorés.","Tu dis que tu as essayé mais que les conditions de travail ne t''ont pas aidé.","Tu n''as rien fait et tu demandes plus de temps."],"correctIndex":0,"correction":"Les preuves factuelles sont le seul argument crédible en entretien de recadrage. Sans données concrètes, la promesse d''amélioration est perçue comme un discours de façade.","fireRiskDelta":-12},{"npcLine":"DG : « Si nous décidons de vous maintenir dans l''entreprise, quels sont vos engagements précis pour les 30 prochains jours ? »","question":"Comment tu formules un plan d''action sur 30 jours en situation de crise ?","options":["Tu proposes des objectifs hebdomadaires mesurables, des checkpoints intermédiaires et une revue de performance à J+30 avec indicateurs de succès définis ensemble.","Tu promets de « tout faire pour vous satisfaire » sans détailler.","Tu demandes 60 jours au lieu de 30 pour te donner plus de marge."],"correctIndex":0,"correction":"Un plan de 30 jours crédible est précis, mesurable et avec des checkpoints. L''ambiguïté sur les engagements pris dans un contexte disciplinaire est rédhibitoire.","fireRiskDelta":-11},{"npcLine":"DRH : « Vos collègues ont fait part de difficultés à collaborer avec vous. Comment vous l''expliquez ? »","question":"Comment tu traites un feedback négatif sur la collaboration ?","options":["Tu écoutes sans interrompre, tu reconnais que ta communication a pu être perçue différemment de ton intention, et tu proposes des actions concrètes pour améliorer la dynamique d''équipe.","Tu nies les difficultés et tu dis que tes collègues exagèrent.","Tu demandes à confronter directement les collègues qui ont fait ce retour."],"correctIndex":0,"correction":"La différence entre intention et impact est réelle. Reconnaître que ta communication a pu créer des difficultés — même involontairement — est la posture mature attendue.","fireRiskDelta":-8},{"npcLine":"DG : « Nous allons délibérer. Avez-vous quelque chose à ajouter avant que nous nous retirions ? »","question":"Quelle est ta dernière intervention avant la délibération ?","options":["Tu réaffirmes ton engagement envers le projet Mutualis, tu résumes les actions que tu t''es engagé à prendre et tu remercies le COMEX pour l''opportunité de t''exprimer.","Tu plaides de façon émotionnelle en te justifiant longuement.","Tu gardes le silence total pour montrer ta dignité."],"correctIndex":0,"correction":"La dernière intervention est une opportunité de synthèse. Réaffirmer son engagement et ses actions concrètes laisse une impression de professionnel organisé et déterminé.","fireRiskDelta":-9}],"closing":"Le COMEX délibère. Tes réponses ont pesé dans la balance. La décision sera communiquée."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
