INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('comex-comex-warning', 4, 'DG : « Nous allons délibérer. Avez-vous quelque chose à ajouter avant que nous nous retirions ? »', 'DG : « Nous allons délibérer. Avez-vous quelque chose à ajouter avant que nous nous retirions ? »', 'Quelle est ta dernière intervention avant la délibération ?', 'Quelle est ta dernière intervention avant la délibération ?', 'Tu réaffirmes ton engagement envers le projet Mutualis, tu résumes les actions que tu t''es engagé à prendre et tu remercies le COMEX pour l''opportunité de t''exprimer.', 'Tu réaffirmes ton engagement envers le projet Mutualis, tu résumes les actions que tu t''es engagé à prendre et tu remercies le COMEX pour l''opportunité de t''exprimer.', 'Tu plaides de façon émotionnelle en te justifiant longuement.', 'Tu plaides de façon émotionnelle en te justifiant longuement.', 'Tu gardes le silence total pour montrer ta dignité.', 'Tu gardes le silence total pour montrer ta dignité.', 0, 'La dernière intervention est une opportunité de synthèse. Réaffirmer son engagement et ses actions concrètes laisse une impression de professionnel organisé et déterminé.', 'La dernière intervention est une opportunité de synthèse. Réaffirmer son engagement et ses actions concrètes laisse une impression de professionnel organisé et déterminé.', -9) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('comex-comex-notice', 'comex-notice', 'COMEX — Entretien préalable au licenciement', 'COMEX — Entretien préalable au licenciement', 'Entretien préalable au licenciement. Le DRH et le DG sont face à toi. Un conseiller du salarié est présent à ta demande. Risque : 80 %. Tout se joue maintenant.', 'Entretien préalable au licenciement. Le DRH et le DG sont face à toi. Un conseiller du salarié est présent à ta demande. Risque : 80 %. Tout se joue maintenant.', 'L''entretien préalable est terminé. Le COMEX dispose de 2 jours ouvrés pour notifier sa décision. Tes réponses ont pu faire la différence.', 'L''entretien préalable est terminé. Le COMEX dispose de 2 jours ouvrés pour notifier sa décision. Tes réponses ont pu faire la différence.', '{"kind":"comex-notice","title":"COMEX — Entretien préalable au licenciement","opening":"Entretien préalable au licenciement. Le DRH et le DG sont face à toi. Un conseiller du salarié est présent à ta demande. Risque : 80 %. Tout se joue maintenant.","questions":[{"npcLine":"DRH : « Nous avons convoqué cet entretien conformément à l''article L1232-2 du Code du Travail. La direction envisage de mettre fin à votre contrat pour insuffisance de résultats. »","question":"Quelle est ta réaction à l''ouverture de cet entretien préalable ?","options":["Tu écoutes attentivement les faits reprochés, tu prends des notes et tu réserves ta réponse pour la phase de contradiction — c''est la procédure légale.","Tu interromps immédiatement pour contester les faits.","Tu sors de la réunion sans répondre."],"correctIndex":0,"correction":"L''entretien préalable suit un protocole légal : présentation des faits, puis droit de réponse du salarié. Écouter d''abord et prendre des notes est la bonne pratique juridique et professionnelle.","fireRiskDelta":-12},{"npcLine":"DG : « Les faits reprochés sont : 3 livrables manqués, 2 retards de reporting, une absence de communication sur un blocage critique. Que répondez-vous ? »","question":"Comment tu contestes ou nuances les faits reprochés de façon professionnelle ?","options":["Tu reconvoques les faits avec précision : tu contestes ce qui est inexact avec des preuves, tu contextualises ce qui est partiel, et tu reconnais ce qui est fondé.","Tu contestes en bloc tous les faits reprochés.","Tu acceptes en bloc sans nuancer pour éviter le conflit."],"correctIndex":0,"correction":"Une défense efficace en entretien préalable est factuelle et nuancée. Contester l''ensemble sans preuves ou accepter tout en bloc sont deux erreurs symétriques.","fireRiskDelta":-13},{"npcLine":"DRH : « Avez-vous des éléments de contexte que vous souhaitez porter à notre connaissance ? »","question":"Quels éléments de contexte peux-tu apporter pour nuancer la situation ?","options":["Tu présentes les contraintes structurelles (charge de travail, ressources insuffisantes, dépendances bloquantes) sans les utiliser comme excuse, mais comme éléments d''information.","Tu accuses directement le management d''être responsable de tes échecs.","Tu ne dis rien — le contexte ne compte pas."],"correctIndex":0,"correction":"Le contexte est pertinent mais ne doit pas être utilisé comme dédouanement. Présenter les contraintes structurelles de façon factuelle aide à nuancer le dossier sans paraître irresponsable.","fireRiskDelta":-10},{"npcLine":"DG : « Si nous décidons de ne pas procéder au licenciement, quelles garanties pouvez-vous nous donner ? »","question":"Comment tu formules des garanties crédibles en situation de préavis ?","options":["Tu proposes un plan de performance formel sur 60 jours avec des objectifs précis, des jalons de contrôle hebdomadaires et une clause de révision après 30 jours.","Tu jures que ça ne se reproduira plus.","Tu demandes un changement de poste ou de manager comme condition."],"correctIndex":0,"correction":"Un plan de performance formalisé est la seule garantie crédible en situation de préavis. Il doit être précis, mesurable et demander un suivi rapproché — démontrant que tu prends la situation au sérieux.","fireRiskDelta":-15},{"npcLine":"L''entretien approche de sa fin. DRH : « Avez-vous des éléments supplémentaires à apporter à notre réflexion ? »","question":"Comment tu clôtures cet entretien préalable de façon optimale ?","options":["Tu résumes tes 3 arguments principaux, tu confirmes ta disponibilité immédiate pour mettre en œuvre le plan de performance et tu remercies pour le processus équitable.","Tu pleures pour toucher émotionnellement les décideurs.","Tu demandes la décision immédiate pour ne pas rester dans l''incertitude."],"correctIndex":0,"correction":"Une clôture structurée et professionnelle laisse une dernière impression de sérieux. La gestion émotionnelle est clé — ni détresse démonstrative ni froideur distante.","fireRiskDelta":-11}],"closing":"L''entretien préalable est terminé. Le COMEX dispose de 2 jours ouvrés pour notifier sa décision. Tes réponses ont pu faire la différence."}'::jsonb, '{"kind":"comex-notice","title":"COMEX — Entretien préalable au licenciement","opening":"Entretien préalable au licenciement. Le DRH et le DG sont face à toi. Un conseiller du salarié est présent à ta demande. Risque : 80 %. Tout se joue maintenant.","questions":[{"npcLine":"DRH : « Nous avons convoqué cet entretien conformément à l''article L1232-2 du Code du Travail. La direction envisage de mettre fin à votre contrat pour insuffisance de résultats. »","question":"Quelle est ta réaction à l''ouverture de cet entretien préalable ?","options":["Tu écoutes attentivement les faits reprochés, tu prends des notes et tu réserves ta réponse pour la phase de contradiction — c''est la procédure légale.","Tu interromps immédiatement pour contester les faits.","Tu sors de la réunion sans répondre."],"correctIndex":0,"correction":"L''entretien préalable suit un protocole légal : présentation des faits, puis droit de réponse du salarié. Écouter d''abord et prendre des notes est la bonne pratique juridique et professionnelle.","fireRiskDelta":-12},{"npcLine":"DG : « Les faits reprochés sont : 3 livrables manqués, 2 retards de reporting, une absence de communication sur un blocage critique. Que répondez-vous ? »","question":"Comment tu contestes ou nuances les faits reprochés de façon professionnelle ?","options":["Tu reconvoques les faits avec précision : tu contestes ce qui est inexact avec des preuves, tu contextualises ce qui est partiel, et tu reconnais ce qui est fondé.","Tu contestes en bloc tous les faits reprochés.","Tu acceptes en bloc sans nuancer pour éviter le conflit."],"correctIndex":0,"correction":"Une défense efficace en entretien préalable est factuelle et nuancée. Contester l''ensemble sans preuves ou accepter tout en bloc sont deux erreurs symétriques.","fireRiskDelta":-13},{"npcLine":"DRH : « Avez-vous des éléments de contexte que vous souhaitez porter à notre connaissance ? »","question":"Quels éléments de contexte peux-tu apporter pour nuancer la situation ?","options":["Tu présentes les contraintes structurelles (charge de travail, ressources insuffisantes, dépendances bloquantes) sans les utiliser comme excuse, mais comme éléments d''information.","Tu accuses directement le management d''être responsable de tes échecs.","Tu ne dis rien — le contexte ne compte pas."],"correctIndex":0,"correction":"Le contexte est pertinent mais ne doit pas être utilisé comme dédouanement. Présenter les contraintes structurelles de façon factuelle aide à nuancer le dossier sans paraître irresponsable.","fireRiskDelta":-10},{"npcLine":"DG : « Si nous décidons de ne pas procéder au licenciement, quelles garanties pouvez-vous nous donner ? »","question":"Comment tu formules des garanties crédibles en situation de préavis ?","options":["Tu proposes un plan de performance formel sur 60 jours avec des objectifs précis, des jalons de contrôle hebdomadaires et une clause de révision après 30 jours.","Tu jures que ça ne se reproduira plus.","Tu demandes un changement de poste ou de manager comme condition."],"correctIndex":0,"correction":"Un plan de performance formalisé est la seule garantie crédible en situation de préavis. Il doit être précis, mesurable et demander un suivi rapproché — démontrant que tu prends la situation au sérieux.","fireRiskDelta":-15},{"npcLine":"L''entretien approche de sa fin. DRH : « Avez-vous des éléments supplémentaires à apporter à notre réflexion ? »","question":"Comment tu clôtures cet entretien préalable de façon optimale ?","options":["Tu résumes tes 3 arguments principaux, tu confirmes ta disponibilité immédiate pour mettre en œuvre le plan de performance et tu remercies pour le processus équitable.","Tu pleures pour toucher émotionnellement les décideurs.","Tu demandes la décision immédiate pour ne pas rester dans l''incertitude."],"correctIndex":0,"correction":"Une clôture structurée et professionnelle laisse une dernière impression de sérieux. La gestion émotionnelle est clé — ni détresse démonstrative ni froideur distante.","fireRiskDelta":-11}],"closing":"L''entretien préalable est terminé. Le COMEX dispose de 2 jours ouvrés pour notifier sa décision. Tes réponses ont pu faire la différence."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
