INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('comex-comex-notice', 4, 'L''entretien approche de sa fin. DRH : « Avez-vous des éléments supplémentaires à apporter à notre réflexion ? »', 'L''entretien approche de sa fin. DRH : « Avez-vous des éléments supplémentaires à apporter à notre réflexion ? »', 'Comment tu clôtures cet entretien préalable de façon optimale ?', 'Comment tu clôtures cet entretien préalable de façon optimale ?', 'Tu résumes tes 3 arguments principaux, tu confirmes ta disponibilité immédiate pour mettre en œuvre le plan de performance et tu remercies pour le processus équitable.', 'Tu résumes tes 3 arguments principaux, tu confirmes ta disponibilité immédiate pour mettre en œuvre le plan de performance et tu remercies pour le processus équitable.', 'Tu pleures pour toucher émotionnellement les décideurs.', 'Tu pleures pour toucher émotionnellement les décideurs.', 'Tu demandes la décision immédiate pour ne pas rester dans l''incertitude.', 'Tu demandes la décision immédiate pour ne pas rester dans l''incertitude.', 0, 'Une clôture structurée et professionnelle laisse une dernière impression de sérieux. La gestion émotionnelle est clé — ni détresse démonstrative ni froideur distante.', 'Une clôture structurée et professionnelle laisse une dernière impression de sérieux. La gestion émotionnelle est clé — ni détresse démonstrative ni froideur distante.', -11) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
INSERT INTO meetings (id, kind, title_fr, title_en, opening_fr, opening_en, closing_fr, closing_en, payload_fr, payload_en) VALUES ('comex-comex-fired', 'comex-fired', 'COMEX — Réunion de licenciement', 'COMEX — Réunion de licenciement', 'Convocation finale. La lettre est sur la table. Risque à 100 %. Mais il reste une dernière chance : tes réponses pourraient convaincre le COMEX de reconsidérer sa décision.', 'Convocation finale. La lettre est sur la table. Risque à 100 %. Mais il reste une dernière chance : tes réponses pourraient convaincre le COMEX de reconsidérer sa décision.', 'Le COMEX revient. La décision finale a été influencée par tes réponses. Tes choix ont compté.', 'Le COMEX revient. La décision finale a été influencée par tes réponses. Tes choix ont compté.', '{"kind":"comex-fired","title":"COMEX — Réunion de licenciement","opening":"Convocation finale. La lettre est sur la table. Risque à 100 %. Mais il reste une dernière chance : tes réponses pourraient convaincre le COMEX de reconsidérer sa décision.","questions":[{"npcLine":"DG : « La décision de licenciement a été prise. Souhaitez-vous vous exprimer une dernière fois ? »","question":"Comment tu te positionnes face à une décision de licenciement annoncée ?","options":["Tu restes calme, tu demandes les modalités de la procédure, tu annonces ton intention de contester si tu estimes la décision infondée, et tu gardes ta dignité.","Tu éclates en larmes ou en colère.","Tu acceptes immédiatement sans répondre."],"correctIndex":0,"correction":"La dignité et le sang-froid en situation de licenciement sont des qualités qui peuvent encore influencer la décision finale ou les modalités de départ. La réaction émotionnelle incontrôlée nuit.","fireRiskDelta":-15},{"npcLine":"DRH : « Avez-vous conscience d''avoir épuisé toutes les opportunités qui vous ont été données ? »","question":"Comment tu réponds à cette question sur les opportunités manquées ?","options":["Tu reconnais honnêtement les opportunités que tu n''as pas saisies tout en signalant les points sur lesquels tu as progressé — une réponse équilibrée et factuelle.","Tu dis que tu n''as jamais eu de vraie chance.","Tu attaques la direction pour les conditions imposées."],"correctIndex":0,"correction":"Reconnaître ses manquements tout en mettant en valeur ses progrès réels est la posture la plus crédible. Elle peut influencer les modalités de départ (outplacement, préavis) même si la décision est prise.","fireRiskDelta":-12},{"npcLine":"CTO : « Si on vous donnait une dernière chance, qu''est-ce qui changerait concrètement par rapport aux fois précédentes ? »","question":"Quelle réponse peut encore convaincre le COMEX de reconsidérer la décision ?","options":["Tu présentes un changement de méthode de travail radical et vérifiable, avec des indicateurs de résultat hebdomadaires et une période probatoire sous supervision étroite acceptée volontairement.","Tu répètes les mêmes promesses que lors des entretiens précédents.","Tu dis que la situation était impossible et que personne ne pouvait réussir."],"correctIndex":0,"correction":"Un changement radical et vérifiable avec supervision volontaire est le seul argument qui peut encore peser. Répéter des promesses déjà faites ou imputer la faute à l''extérieur scelle la décision.","fireRiskDelta":-18},{"npcLine":"DRH : « Votre comportement envers vos collègues a été mentionné comme problématique. Que pensez-vous de cette évaluation ? »","question":"Comment tu abordes la dimension relationnelle dans cet entretien final ?","options":["Tu reconnais l''impact que ton comportement a pu avoir sur tes collègues, tu t''en excuses sincèrement et tu proposes des modalités concrètes pour réparer les relations.","Tu nies les problèmes relationnels — tes collègues ne peuvent pas témoigner contre toi.","Tu demandes les noms de ceux qui ont témoigné pour les confronter."],"correctIndex":0,"correction":"Les excuses sincères avec des propositions concrètes de réparation démontrent une intelligence émotionnelle et sociale. Nier ou chercher à confronter les témoins aggrave irrémédiablement la situation.","fireRiskDelta":-14},{"npcLine":"Le COMEX se consulte à voix basse. DG : « Nous allons vous laisser quelques minutes. » — ils reviennent 5 minutes plus tard.","question":"Comment tu gères cette attente décisive ?","options":["Tu restes calme et composé, tu prépares mentalement les deux scenarios (maintien ou départ), et tu te souviens que ta réaction à l''annonce finale fera aussi partie de l''évaluation.","Tu commences à envoyer des messages paniqués à tes contacts.","Tu demandes à quitter la salle pendant la délibération."],"correctIndex":0,"correction":"La gestion de l''attente stressante est elle-même observée. Un professionnel calme et préparé aux deux scenari démontre une maturité émotionnelle qui peut encore jouer en sa faveur.","fireRiskDelta":-16}],"closing":"Le COMEX revient. La décision finale a été influencée par tes réponses. Tes choix ont compté."}'::jsonb, '{"kind":"comex-fired","title":"COMEX — Réunion de licenciement","opening":"Convocation finale. La lettre est sur la table. Risque à 100 %. Mais il reste une dernière chance : tes réponses pourraient convaincre le COMEX de reconsidérer sa décision.","questions":[{"npcLine":"DG : « La décision de licenciement a été prise. Souhaitez-vous vous exprimer une dernière fois ? »","question":"Comment tu te positionnes face à une décision de licenciement annoncée ?","options":["Tu restes calme, tu demandes les modalités de la procédure, tu annonces ton intention de contester si tu estimes la décision infondée, et tu gardes ta dignité.","Tu éclates en larmes ou en colère.","Tu acceptes immédiatement sans répondre."],"correctIndex":0,"correction":"La dignité et le sang-froid en situation de licenciement sont des qualités qui peuvent encore influencer la décision finale ou les modalités de départ. La réaction émotionnelle incontrôlée nuit.","fireRiskDelta":-15},{"npcLine":"DRH : « Avez-vous conscience d''avoir épuisé toutes les opportunités qui vous ont été données ? »","question":"Comment tu réponds à cette question sur les opportunités manquées ?","options":["Tu reconnais honnêtement les opportunités que tu n''as pas saisies tout en signalant les points sur lesquels tu as progressé — une réponse équilibrée et factuelle.","Tu dis que tu n''as jamais eu de vraie chance.","Tu attaques la direction pour les conditions imposées."],"correctIndex":0,"correction":"Reconnaître ses manquements tout en mettant en valeur ses progrès réels est la posture la plus crédible. Elle peut influencer les modalités de départ (outplacement, préavis) même si la décision est prise.","fireRiskDelta":-12},{"npcLine":"CTO : « Si on vous donnait une dernière chance, qu''est-ce qui changerait concrètement par rapport aux fois précédentes ? »","question":"Quelle réponse peut encore convaincre le COMEX de reconsidérer la décision ?","options":["Tu présentes un changement de méthode de travail radical et vérifiable, avec des indicateurs de résultat hebdomadaires et une période probatoire sous supervision étroite acceptée volontairement.","Tu répètes les mêmes promesses que lors des entretiens précédents.","Tu dis que la situation était impossible et que personne ne pouvait réussir."],"correctIndex":0,"correction":"Un changement radical et vérifiable avec supervision volontaire est le seul argument qui peut encore peser. Répéter des promesses déjà faites ou imputer la faute à l''extérieur scelle la décision.","fireRiskDelta":-18},{"npcLine":"DRH : « Votre comportement envers vos collègues a été mentionné comme problématique. Que pensez-vous de cette évaluation ? »","question":"Comment tu abordes la dimension relationnelle dans cet entretien final ?","options":["Tu reconnais l''impact que ton comportement a pu avoir sur tes collègues, tu t''en excuses sincèrement et tu proposes des modalités concrètes pour réparer les relations.","Tu nies les problèmes relationnels — tes collègues ne peuvent pas témoigner contre toi.","Tu demandes les noms de ceux qui ont témoigné pour les confronter."],"correctIndex":0,"correction":"Les excuses sincères avec des propositions concrètes de réparation démontrent une intelligence émotionnelle et sociale. Nier ou chercher à confronter les témoins aggrave irrémédiablement la situation.","fireRiskDelta":-14},{"npcLine":"Le COMEX se consulte à voix basse. DG : « Nous allons vous laisser quelques minutes. » — ils reviennent 5 minutes plus tard.","question":"Comment tu gères cette attente décisive ?","options":["Tu restes calme et composé, tu prépares mentalement les deux scenarios (maintien ou départ), et tu te souviens que ta réaction à l''annonce finale fera aussi partie de l''évaluation.","Tu commences à envoyer des messages paniqués à tes contacts.","Tu demandes à quitter la salle pendant la délibération."],"correctIndex":0,"correction":"La gestion de l''attente stressante est elle-même observée. Un professionnel calme et préparé aux deux scenari démontre une maturité émotionnelle qui peut encore jouer en sa faveur.","fireRiskDelta":-16}],"closing":"Le COMEX revient. La décision finale a été influencée par tes réponses. Tes choix ont compté."}'::jsonb) ON CONFLICT (id) DO UPDATE SET kind=EXCLUDED.kind, title_fr=EXCLUDED.title_fr, opening_fr=EXCLUDED.opening_fr, closing_fr=EXCLUDED.closing_fr, payload_fr=EXCLUDED.payload_fr;
INSERT INTO meeting_questions (meeting_id, sort_order, npc_line_fr, npc_line_en, question_fr, question_en, option_a_fr, option_a_en, option_b_fr, option_b_en, option_c_fr, option_c_en, correct_index, correction_fr, correction_en, fire_risk_delta) VALUES ('comex-comex-fired', 0, 'DG : « La décision de licenciement a été prise. Souhaitez-vous vous exprimer une dernière fois ? »', 'DG : « La décision de licenciement a été prise. Souhaitez-vous vous exprimer une dernière fois ? »', 'Comment tu te positionnes face à une décision de licenciement annoncée ?', 'Comment tu te positionnes face à une décision de licenciement annoncée ?', 'Tu restes calme, tu demandes les modalités de la procédure, tu annonces ton intention de contester si tu estimes la décision infondée, et tu gardes ta dignité.', 'Tu restes calme, tu demandes les modalités de la procédure, tu annonces ton intention de contester si tu estimes la décision infondée, et tu gardes ta dignité.', 'Tu éclates en larmes ou en colère.', 'Tu éclates en larmes ou en colère.', 'Tu acceptes immédiatement sans répondre.', 'Tu acceptes immédiatement sans répondre.', 0, 'La dignité et le sang-froid en situation de licenciement sont des qualités qui peuvent encore influencer la décision finale ou les modalités de départ. La réaction émotionnelle incontrôlée nuit.', 'La dignité et le sang-froid en situation de licenciement sont des qualités qui peuvent encore influencer la décision finale ou les modalités de départ. La réaction émotionnelle incontrôlée nuit.', -15) ON CONFLICT (meeting_id, sort_order) DO UPDATE SET npc_line_fr=EXCLUDED.npc_line_fr, question_fr=EXCLUDED.question_fr, option_a_fr=EXCLUDED.option_a_fr, option_b_fr=EXCLUDED.option_b_fr, option_c_fr=EXCLUDED.option_c_fr, correct_index=EXCLUDED.correct_index, correction_fr=EXCLUDED.correction_fr, fire_risk_delta=EXCLUDED.fire_risk_delta;
